        [7906] = "Прикликає $s1 $lTamed Cat:Tamed Cats; супроводжувати заклинача, доки їх не відкличуть.",
        [7914] = "Захоплює дух найближчого члена Палаючого Клинка. Якщо ціль помре під час висмоктування, заклинач отримає 1 Насичений палаючий самоцвіт.",
        [7924] = "Дає лікарю змогу виготовляти й використовувати бинти до максимальної навички 225. Тканину для бинтів можна знайти на гуманоїдах у світі.",
        [7926] = "Зцілює на $o1 протягом $d.",
        [7927] = "Зцілює на $o1 протягом $d.",
        [7932] = "Зцілює ціль від отрут до 25 рівня.",
        [7933] = "Зцілює ціль від отрут до 35 рівня.",
        [7934] = "Створює 3 фіали протиотрути.",
        [7935] = "Створює $M1 фіалів сильної протиотрути.",
        [7938] = "Висмоктує з ворога $s1 здоров’я, зцілюючи заклинача на величину до подвійної кількості.",
        [7939] = "Переводить заклинача в непомітність, але зменшує швидкість руху до $s2% від звичайної. Триває до скасування.",
        [7947] = "Завдає ворогу $s1 шкоди від сил природи кожні $t1 с протягом $d.",
        [7948] = "Зцілює заклинача на $s1 кожні $t1 сек. протягом $d.",
        [7951] = "Завдає ворогові шкоди від сил природи.",
        [7960] = "Створює $M1 $lloaf:loaves; хліба, забезпечуючи мага та його союзників їжею.",
        [7964] = "Кидає димову бомбу, приголомшуючи ворогів поблизу на $d.",
        [7965] = "Перетворюється на змію на $d., збільшуючи шкоду атак на $s2 і час між атаками на $s3%.",
        [7966] = "Завдає $s1 шкоди від сил природи будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура триває $d.",
        [7967] = "Присипляє ворожу ціль до $d. Будь-яка ворожа дія пробудить її. Одночасно може спати лише одна ціль.",
        [7974] = "Дарує лорду Азретоку здатність літати.",
        [7978] = "Завдає $s1 шкоди від вогню всім ворогам у вибраній зоні.",
        [7979] = "Прикликає $s1 $lCompact Harvest Reaper:Compact Harvest Reapers; на допомогу заклиначеві в бою на $d. Жниваря не можна зцілити, але після знищення з нього можна взяти здобич.",
        [7992] = "Збільшує час між атаками ворога на $s1% і зменшує швидкість руху на $s2% на $d.",
        [7993] = "Прикликає $s1 $lTreant Ally:Treant Allies; супроводжувати заклинача, доки їх не відкличуть.",
        [7994] = "Висмоктує з ворога $s1 мани та переносить її до заклинача.",
        [7997] = "Зменшує силу ворога на $s1, спритність на $s2 і витривалість на $s3 на $d.",
        [8000] = "Викликає стовп полум’я, що завдає всім ворогам у вибраній зоні $s1 шкоди від вогню та ще $s2 шкоди кожні $t2 сек. протягом $d.",
        [8004] = "Зцілює дружню ціль на $s1.",
        [8005] = "Зцілює дружню ціль на $s1.",
        [8008] = "Зцілює дружню ціль на $s1.",
        [8010] = "Зцілює дружню ціль на $s1.",
        [8012] = "Розвіює з ворожої цілі $m1 корисний магічний $leffect:effects;.",
        [8014] = "Зменшує витривалість ворога на $s1 протягом $d.",
        [8016] = "Зменшує дух ворога на $s1 на $d.",
        [8017] = "Насичує зброю шамана, збільшуючи силу атак ближнього бою на $10400s1 і створюючи додаткову загрозу атаками цією зброєю. Триває 60 хвилин.",
        [8018] = "Насичує зброю шамана, збільшуючи силу атак ближнього бою на $15567s1 і створюючи додаткову загрозу атаками цією зброєю. Триває 60 хвилин.",
        [8019] = "Насичує зброю шамана, збільшуючи силу атак ближнього бою на $15568s1 і створюючи додаткову загрозу атаками цією зброєю. Триває 60 хвилин.",
        [8024] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8026m1/77-1} до ${$8026m1/25} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8027] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8028m1/77-1} до ${$8028m1/25} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8030] = "Насичує зброю шамана вогнем. Кожен удар завдає від ${$8029m1/77-1} до ${$8029m1/25} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди від вогню за удар. На основній руці скасовує вашу особисту користь від Тотема язика полум’я. Триває 60 хвилин.",
        [8033] = "Насичує зброю шамана кригою. Кожен удар має шанс завдати додатково $8034s2 шкоди від криги та зменшити швидкість руху цілі на $8034s1% протягом $8034d. Триває 60 хвилин.",
        [8038] = "Насичує зброю шамана кригою. Кожен удар має шанс завдати додатково $8037s2 шкоди від криги та зменшити швидкість руху цілі на $8037s1% протягом $8037d. Триває 60 хвилин.",
        [8040] = "Присипляє ворожу ціль до $d. Будь-яка ворожа дія пробудить її. Одночасно може спати лише одна ціль.",
        [8041] = "Перетворюється на змію на $d., збільшуючи фізичну шкоду на $s3, але втрачаючи можливість застосовувати закляття.",
        [8042] = "Миттєво вражає ціль ударною силою, завдаючи $s1 шкоди від сил природи. Також перериває застосування закляття й не дає застосовувати закляття тієї самої школи протягом $d. Створює значну загрозу.",
        [8044] = "Миттєво вражає ціль ударною силою, завдаючи $s1 шкоди від сил природи. Також перериває застосування закляття й не дає застосовувати закляття тієї самої школи протягом $d. Створює значну загрозу.",
        [8045] = "Миттєво вражає ціль ударною силою, завдаючи $s1 шкоди від сил природи. Також перериває застосування закляття й не дає застосовувати закляття тієї самої школи протягом $d. Створює значну загрозу.",
        [8046] = "Миттєво вражає ціль ударною силою, завдаючи $s1 шкоди від сил природи. Також перериває застосування закляття й не дає застосовувати закляття тієї самої школи протягом $d. Створює значну загрозу.",
        [8050] = "Миттєво обпалює ціль вогнем, завдаючи $s1 шкоди від вогню одразу та ще $o2 протягом $d.",
