        [8119] = "Збільшує силу цілі на $s1 на $d.",
        [8120] = "Збільшує силу цілі на $s1 на $d.",
        [8121] = "Навчає «Захисної стійки», «Розколу броні» (Ранг 1) і «Провокації» (Ранг 1).",
        [8122] = "Заклинач видає психічний крик, змушуючи $i ворогів у межах $a1 м тікати протягом $d. Завдана шкода може перервати ефект.",
        [8124] = "Заклинач видає психічний крик, змушуючи $i ворогів у межах $a1 м тікати протягом $d. Завдана шкода може перервати ефект.",
        [8129] = "Висмоктує з цілі $s1 мани. За кожну висмоктану одиницю мани ціль отримує 0.5 шкоди від тіні.",
        [8131] = "Висмоктує з цілі $s1 мани. За кожну висмоктану одиницю мани ціль отримує 0.5 шкоди від тіні.",
        [8134] = "Заклинача оточують $n куль блискавки. Коли заклинача вражає закляття, атака ближнього чи дальнього бою, нападник отримує $26369s1 шкоди від сил природи. Це витрачає одну кулю блискавки. Одна куля може спрацювати лише раз на кілька секунд. Триває $d.",
        [8137] = "Збільшує фізичну шкоду, яку отримує ворог, на $s1% на $d.",
        [8138] = "Зменшує витривалість ворога на $s1 протягом $d.",
        [8139] = "Зменшує інтелект ворога на $s1, а дух — на $s2 на $d.",
        [8140] = "Зменшує швидкість застосування заклинань ворога на $s1% протягом $d.",
        [8141] = "Використовує святий еліксир, щоб зцілити заклинача на $s1.",
        [8142] = "Завдає фізичної шкоди ворогам поблизу, збиваючи їх з ніг і знерухомлюючи на $d.",
        [8143] = "Прикликає Тотем тремтіння з $s1 здоров’я біля ніг заклинача. Він стрясає землю, знімаючи страх, причарування та сон з учасників групи в межах $8146a1 м. Триває $d.",
        [8147] = "Завдає ворогам поблизу $s1 шкоди від сил природи, збільшуючи час між їхніми атаками на $s3% і зменшуючи швидкість руху на $s2% на $d.",
        [8148] = "Завдає $s1 шкоди від сил природи будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура триває $d.",
        [8150] = "Завдає ворогам поблизу $s1 шкоди від сил природи та приголомшує їх на $d.",
        [8151] = "Під час атаки з непомітності завдає ворогові звичайної шкоди та ще $s1, приголомшуючи ціль на $d.",
        [8152] = "Переводить заклинача в непомітність, але зменшує швидкість руху на $s2%. Триває до скасування.",
        [8153] = "Перетворює друїда на летючу форму, збільшуючи швидкість руху.",
        [8154] = "Прикликає Тотем кам’яної шкіри з $s1 здоров’я біля ніг заклинача. Тотем захищає учасників групи в межах $8156a1 м, зменшуючи отримувану фізичну шкоду на $8156s1. Триває $d.",
        [8155] = "Прикликає Тотем кам’яної шкіри з $s1 здоров’я біля ніг заклинача. Тотем захищає учасників групи в межах $8157a1 м, зменшуючи отримувану фізичну шкоду на $8157s1. Триває $d.",
        [8160] = "Прикликає Тотем сили землі з $s1 здоров’я біля ніг заклинача. Тотем збільшує силу учасників групи в межах $8162a1 м на $8162s1. Триває $d.",
        [8161] = "Прикликає Тотем сили землі з $s1 здоров’я біля ніг заклинача. Тотем збільшує силу учасників групи в межах $8163a1 м на $8163s1. Триває $d.",
        [8166] = "Прикликає Тотем очищення від отрути з $s1 здоров’я біля ніг заклинача, який намагається зняти 1 ефект отрути з учасників групи в межах $8168a1 м кожні $8167t1 секунд. Триває $d.",
        [8170] = "Прикликає Тотем очищення від хвороб з $s1 здоров’я біля ніг заклинача, який намагається зняти 1 ефект хвороби з учасників групи в межах $8171a1 м кожні $8172t1 секунд. Триває $d.",
        [8176] = "Прикликає скверногона-вартового, який захищатиме вас протягом $d.",
        [8177] = "Прикликає Тотем заземлення з $s1 здоров’я біля ніг заклинача, який кожні $8179t1 секунд перенаправляє на себе одне шкідливе закляття, спрямоване на учасника групи поблизу. Не перенаправляє закляття по області. Триває $d.",
        [8181] = "Прикликає Тотем опору кризі з $s1 здоров’я біля ніг заклинача на $d. Тотем збільшує опір кризі учасників групи й рейду в межах $8182a1 м на $8182s1.",
        [8184] = "Прикликає Тотем опору вогню з $s1 здоров’я біля ніг заклинача на $d, який збільшує опір вогню учасників групи й рейду в межах $8185a1 м на $8185s1.",
        [8190] = "Прикликає Тотем магми з $s1 здоров’я біля ніг заклинача на $d, який завдає істотам у межах $8187a1 м $8187s1 шкоди від вогню кожні $8188t1 секунд.",
        [8191] = "Спалах енергії наповнює заклинача, збільшуючи $ghis:her; шкоду на $s1 і броню на $s2 на $d.",
        [8192] = "Заспокоює ціль, зменшуючи відстань, з якої вона атакуватиме вас, на $s1 ярдів.  Діє лише на гуманоїдів рівня $v або нижче.  Триває $d.",
        [8198] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8199] = "Навчає «Тотема кам’яної шкіри» (Ранг 1).",
        [8200] = "Навчає «Тотема пекучого полум’я» (Ранг 1).",
        [8201] = "Навчає «Тотема цілющого потоку» (Ранг 1).",
        [8202] = "Дає шаманові змогу бачити духів стихій.",
        [8204] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8205] = "Вражає ворогів поблизу громом, збільшуючи час між їхніми атаками на $s2% на $d і завдаючи $s1 шкоди. Вражає до $i цілей.",
        [8209] = "Створює $s1 Вибухову вівцю, яка $lcharges:charge; до найближчого $lenemy:enemies; і $lexplodes:explode;. Вибухові вівці нестабільні й самознищаться через $d.",
        [8210] = "Прикликає $s1 $lSavannah Cub:Savannah Cubs; на допомогу заклиначеві в бою на $d.",
        [8211] = "Вражає ворога антимановою стрілою, що перескакує на іншого ворога поблизу. За кожну поглинуту одиницю мани ціль отримує $e1 шкоди. Закляття вражає до $x1 цілей.",
        [8212] = "Ваш розмір збільшується, а сила зростає на $s1 відповідно до нового розміру. Триває $d.",
        [8213] = "З’їж мене.",
        [8227] = "Прикликає Тотем язика полум’я з $s1 здоров’я біля ніг заклинача. Тотем зачаровує вогнем зброю в основній руці всіх учасників групи в межах $8230a1 м. Кожен удар завдає від ${$8253m1/77*$<mult>-1} до ${$8253M1/25*$<mult>} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди за удар. Триває $d.",
        [8232] = "Насичує зброю шамана вітром. Кожен удар має 20% шанс надати $8233s2 додаткові $lattack:attacks; з $8233s1 додаткової сили атаки ближнього бою. На основній руці скасовує вашу особисту користь від Тотема люті вітру. Триває 60 хвилин.",
        [8235] = "Насичує зброю шамана вітром. Кожен удар має 20% шанс надати $8236s2 додаткові $lattack:attacks; з $8236s1 додаткової сили атаки ближнього бою. На основній руці скасовує вашу особисту користь від Тотема люті вітру. Триває 60 хвилин.",
        [8242] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [8245] = "Зменшує броню ворогів поблизу на $s1 на $d.",
        [8246] = "Вражає ворога блискавкою, завдаючи $s1 шкоди від сил природи.",
        [8249] = "Прикликає Тотем язика полум’я з $s1 здоров’я біля ніг заклинача. Тотем посилює атаки ближнього бою всіх учасників групи в межах $8250a1 м. Кожен удар основною рукою завдає від ${$8248m1/77*$<mult>-1} до ${$8248M1/25*$<mult>} додаткової шкоди від вогню залежно від швидкості зброї. Повільніша зброя завдає більше шкоди за удар. Триває $d.",
        [8255] = "Завдає ворогові та його найближчим союзникам звичайної шкоди й додатково $s1, вражаючи до $x1 цілей і збільшуючи час між їхніми атаками на $s2% на $d.",
        [8256] = "Завдає ворогу $s1 шкоди від сил природи кожні $t1 с протягом $d.",
        [8257] = "Завдає ворогові $s2 шкоди від сил природи, а потім ще $s1 шкоди кожні $t1 сек. протягом $d.",
        [8258] = "Надає учасникам групи поблизу $s1 додаткової броні на $d. На гравцеві одночасно може діяти лише одна аура від одного паладина.",
        [8259] = "Завдає звичайної шкоди та додатково $s1 усім ворогам поблизу.",
        [8260] = "Збільшує швидкість руху заклинача на $s1% на $d. і додає $s2 шкоди до його першої атаки.",
        [8262] = "Прикликає Тотем захисту від стихій біля ніг заклинача. Тотем існує $d. і збільшує опір шкідливій магії учасників групи поблизу.",
        [8264] = "Прикликає Тотем лавового струменя біля ніг заклинача. Тотем існує $d. і завдає ворогам поблизу $8265s1 шкоди від вогню кожні $8266t1 сек.",
        [8267] = "Зменшує інтелект ворогів поблизу на $s1 на $d.",
        [8269] = "Збільшує швидкість атак заклинача на $s2% і завдану ним фізичну шкоду на $s1 на $d.",
        [8270] = "Прикликає $s1 $lStone Rumbler:Stone Rumblers; супроводжувати заклинача, доки їх не відкличуть.",
        [8271] = "Прикликає $s1 $lWind Howler:Wind Howlers; супроводжувати заклинача, доки їх не відкличуть.",
        [8272] = "Зменшує швидкість застосування заклинань ворога на $s1% протягом $d.",
        [8274] = "Прикликає $s1 $lTamed Battleboar:Tamed Battleboars; супроводжувати заклинача, доки їх не відкличуть.",
        [8275] = "Завдає ворогові звичайної шкоди та додатково $s2, а потім ще $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8276] = "Прикликає $s1 $lTamed Hyena:Tamed Hyenas; супроводжувати заклинача, доки їх не відкличуть.",
        [8277] = "Фізична шкода, яку завдає ціль, зменшується на $s1 на $d.",
        [8281] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, не даючи їм застосовувати закляття протягом $d.",
        [8282] = "Збільшує отримувану ворогом фізичну шкоду на $s1 протягом $d.",
        [8283] = "Для використання на Ховрасі-винюхувачі.",
        [8285] = "Завдає ворогам поблизу звичайної шкоди та ще $s1, приголомшуючи їх на $d.",
        [8286] = "Прикликає $s1 $lBoar Spirit:Boar Spirits; на допомогу заклиначеві в бою на $d.",
        [8288] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [8289] = "Висмоктує душу цілі, завдаючи $o2 шкоди від тіні протягом $d. Нетруді цілі, уражені Висмоктуванням душі, можуть дати вам уламок душі. Нетруді цілі, вбиті Висмоктуванням душі, завжди дають уламок душі. Уламки душі потрібні для інших заклинань.",
        [8292] = "Вражає ворога блискавкою, що перескакує на іншого ворога поблизу. Закляття вражає до $x1 цілей, завдаючи кожній $s1 шкоди від сил природи.",
        [8293] = "Створює хмару блискавок на $d., що вражає всіх ворогів у вибраній зоні на $s1 шкоди від сил природи та завдає ще $s2 шкоди кожні $t2 сек.",
        [8296] = "Дає шахтарю змогу виплавити 10 шматків мідної руди в 10 мідних зливків. Для виплавки міді потрібне горно.",
        [8312] = "Знерухомлює ціль на $d.",
        [8313] = "Отруює ціль, завдаючи $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8316] = "Оточує ціль вогняним щитом.  Кожен удар по цілі завдає нападнику $s1 шкоди від вогню.  Триває $d.  Ваш вихованець не може застосувати Вогняний щит на себе.",
        [8317] = "Оточує ціль вогняним щитом.  Кожен удар по цілі завдає нападнику $s1 шкоди від вогню.  Триває $d.  Ваш вихованець не може застосувати Вогняний щит на себе.",
        [8331] = "Динаміт для неінженерів, який майже завжди долітає до цілі! Завдає $s1 шкоди від вогню в радіусі 5 м.",
        [8332] = "Завдає $s1 шкоди від вогню в радіусі 5 ярдів.",
        [8333] = "Завдає $s1 шкоди від вогню в радіусі 5 ярдів.",
        [8342] = "Кабелі запуску іноді можуть ударом струму повернути мертвого гравця до життя. Не можна використовувати в бою.",
        [8344] = "Дає змогу ненадовго контролювати механічну ціль. Може не спрацювати, лише знерухомити механізм або дуже-дуже його розлютити. Гномська інженерія у всій красі.",
        [8348] = "Зцілює носія на $o1 протягом $d.",
        [8355] = "Завдає ворогові звичайної шкоди та ще $s1, але лише під час атаки ззаду.",
        [8358] = "Відновлює ману заклинача.",
        [8361] = "Робить заклинача несприйнятливим до всіх атак і заклять на $d.",
        [8362] = "Зцілює союзника на $s1 кожні $t1 сек. протягом $d.",
        [8363] = "Завдає ворогові звичайної шкоди та додатково $s2, а потім ще $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8364] = "Викликає хуртовину на $d., що завдає всім ворогам у вибраній зоні $s1 шкоди від криги кожні $t1 сек.",
        [8365] = "Збільшує фізичну шкоду союзника на $s1 на $d.",
        [8372] = "Прикликає $s1 $lAqua Guardian:Aqua Guardians; супроводжувати заклинача, доки їх не відкличуть.",
        [8374] = "Завдає лютого дугового удару, вражаючи ворогів у конусі перед заклиначем.",
        [8375] = "Назавжди зачаровує рукавиці, додаючи +$13838s1 до навички гірництва.",
        [8376] = "Прикликає Тотем захоплення землі на $d., який періодично знерухомлює ворогів поблизу.",
        [8379] = "Роззброює ворога, змушуючи його припинити використовувати зброю на $d.",
        [8380] = "Розколює броню цілі, зменшуючи її на $s1 за кожен ефект «Розкол броні» та створюючи значну загрозу. Накладається до 5 разів. Триває $d.",
        [8382] = "Висмоктує з ворога $s1 здоров’я кожні $t1 с протягом $d та переносить його до заклинача.",
        [8387] = "Кущі трав поблизу відображаються на мінімапі.   Одночасно можна вистежувати лише один тип об’єктів.",
        [8388] = "Мінеральні жили поблизу відображаються на мінімапі.   Одночасно можна вистежувати лише один тип об’єктів.",
        [8391] = "Завдає ворогу звичайної шкоди плюс $s1 і приголомшує його на $d.",
        [8394] = "Прикликає або відкликає верхового Смугастого кригозуба.",
        [8395] = "Прикликає або відкликає верхового раптора.",
        [8396] = "Прикликає або відкликає верхового довгонога.",
        [8397] = "При отриманні удару в ближньому бою має $s1% шанс отримати святий щит, що поглинає $10368s1 шкоди протягом $10368d. У Пустках і Проклятих місцевостях цей шанс подвоюється.",
        [8398] = "Завдає ворогам поблизу $s2 шкоди від криги та зменшує швидкість їхнього руху на $s1% на $d.",
        [8399] = "Присипляє ворогів поблизу до $d. Будь-яка завдана шкода пробудить їх.",
        [8400] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [8401] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [8402] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
        [8406] = "Запускає у ворога крижану стрілу, що завдає від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги та зменшує швидкість руху на $s1% протягом $d.",
        [8407] = "Запускає у ворога крижану стрілу, що завдає від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги та зменшує швидкість руху на $s1% протягом $d.",
        [8408] = "Запускає у ворога крижану стрілу, що завдає від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги та зменшує швидкість руху на $s1% протягом $d.",
        [8412] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [8413] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [8416] = "Випускає в ворога Таємні стріли, що завдають $8419s1 шкоди від таємної магії щосекунди протягом $d.",
        [8417] = "Випускає в ворога Таємні стріли, що завдають $8418s1 шкоди від таємної магії щосекунди протягом $d.",
        [8418] = "Випускає у ворога Таємну стрілу, що завдає $s1 шкоди від таємної магії.",
        [8419] = "Випускає у ворога Таємну стрілу, що завдає $s1 шкоди від таємної магії.",
        [8422] = "Викликає стовп вогню, що завдає всім ворогам у зоні $s1 шкоди від вогню та ще ${$1279987m1*4} шкоди від вогню протягом $d. Одночасно в одного мага може бути активний лише один «Вогняний стовп».",
        [8423] = "Викликає стовп вогню, що завдає всім ворогам у зоні $s1 шкоди від вогню та ще ${$1279988m1*4} шкоди від вогню протягом $d. Одночасно в одного мага може бути активний лише один «Вогняний стовп».",
        [8427] = "Крижані уламки обрушуються на вибрану ділянку, завдаючи ${$1279978m1*$d*$<frostdamage>} шкоди від криги протягом $d.",
        [8435] = "Завдає $s1 шкоди від сил природи ворогам у конусі перед заклиначем.",
        [8437] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [8438] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [8439] = "Спричиняє вибух таємної магії навколо заклинача, завдаючи $s1 шкоди від таємної магії всім цілям у межах $a1 ярдів.",
        [8444] = "Обпалює ворога, завдаючи $s1 шкоди від вогню.",
        [8445] = "Обпалює ворога, завдаючи $s1 шкоди від вогню.",
        [8446] = "Обпалює ворога, завдаючи $s1 шкоди від вогню.",
        [8450] = "Послаблює магію, спрямовану на вибраного члена групи, зменшуючи шкоду від заклинань на величину до $s1, а зцілення від заклинань — на величину до $s2.  Триває $d.",
        [8451] = "Послаблює магію, спрямовану на вибраного члена групи, зменшуючи шкоду від заклинань на величину до $s1, а зцілення від заклинань — на величину до $s2.  Триває $d.",
        [8455] = "Підсилює магію, спрямовану на вибраного члена групи, збільшуючи шкоду від заклинань на величину до $s1, а зцілення від заклинань — на величину до $s2.  Триває $d.",
        [8457] = "Поглинає $s1 шкоди від вогню$?s11094[ і дає $s2% шанс відбити заклинання та ефекти вогню][].  Триває $d.",
        [8458] = "Поглинає $s1 шкоди від вогню$?s11094[ і дає $s2% шанс відбити заклинання та ефекти вогню][].  Триває $d.",
        [8461] = "Поглинає $s1 шкоди від криги$?s11189[ і дає $s2% шанс відбити закляття й ефекти криги][]. Триває $d.",
        [8462] = "Поглинає $s1 шкоди від криги$?s11189[ і дає $s2% шанс відбити закляття й ефекти криги][]. Триває $d.",
        [8492] = "Цілі в конусі перед заклиначем отримують від ${$m2$*$<frostdamage>} до ${$M2*$<frostdamage>} шкоди від криги, а їхня швидкість руху зменшується на $s1% протягом $d.",
        [8494] = "Поглинає $s1 фізичної шкоди, натомість витрачаючи ману.  Витрачає $e мани за кожну поглинуту одиницю шкоди.  Триває $d.",
        [8495] = "Поглинає $s1 фізичної шкоди, натомість витрачаючи ману.  Витрачає $e мани за кожну поглинуту одиницю шкоди.  Триває $d.",
        [8512] = "Прикликає Тотем люті вітру з $s1 здоров’я біля ніг заклинача. Тотем посилює атаки ближнього бою всіх учасників групи в межах $8515a1 м. Кожен удар основною рукою має 20% шанс надати нападникові $8516s2 додаткову атаку з ${$8516m1*$<mult>} додаткової сили атаки ближнього бою. Триває $d.",
        [8516] = "Силу атаки збільшено на $s1. Надано $s2 додаткову атаку.",
        [8517] = "Відкриває скриньку Мертвого Зуба.",
        [8532] = "При нанесенні на вудку збільшує навичку риболовлі на 50 протягом 10 хвилин.",
        [8552] = "Шкода, яку завдає ціль, зменшується на $s1 на $d.",
        [8553] = "Розігріває кров і притуплює нерви.",
        [8555] = "Завдає ворогові $s1 шкоди й змушує його прикинутися мертвим до $8359d.",
        [8593] = "Символ Життя поверне до життя того, хто з ним налаштований.",
        [8594] = "Прикликає $s1 $lMoonstalker Runt:Moonstalker Runts; супроводжувати заклинача, доки їх не відкличуть.",
        [8595] = "Зцілює союзника на $s1.",
        [8596] = "Зцілює вашу ціль на $s1.",
        [8598] = "Вражає ворога блискавкою, завдаючи $s1 шкоди від сил природи.",
        [8600] = "Завдає ворогові $s1 шкоди від сил природи, а потім ще $s2 шкоди кожні $t2 сек. протягом $d.",
        [8605] = "Навчає готувати Яйце, запечене з травами.",
        [8606] = "Прикликає Циклонія.",
        [8612] = "Дає шанс стати невидимим при отриманні удару.",
        [8613] = "Основи зняття шкур і хутра з тварин для шкіряництва. Максимальна навичка зняття шкур — 75. Потрібен ніж для зняття шкур.",
        [8616] = "Навчає «Стійки берсерка» (Ранг 1). Навчає «Перехоплення» (Ранг 1).",
        [8617] = "Поглиблені навички зняття шкур зі звірів для шкіряництва. Максимальна навичка зняття шкур — 150. Потрібен ніж для зняття шкур.",
        [8618] = "Експертні навички зняття шкур зі звірів для шкіряництва. Максимальна навичка зняття шкур — 225. Потрібен ніж для зняття шкур.",
        [8621] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
        [8623] = "Завершальний прийом, що завдає шкоди за кожне очко серії; шкода збільшується від сили атаки:\r\n   1 очко  : ${$m1+(1*$b1*$<mult>)}-${$M1+(1*$b1*$<mult>)} шкоди\r\n   2 очки: ${$m1+(2*$b1*$<mult>)}-${$M1+(2*$b1*$<mult>)} шкоди\r\n   3 очки: ${$m1+(3*$b1*$<mult>)}-${$M1+(3*$b1*$<mult>)} шкоди\r\n   4 очки: ${$m1+(4*$b1*$<mult>)}-${$M1+(4*$b1*$<mult>)} шкоди\r\n   5 очок: ${$m1+(5*$b1*$<mult>)}-${$M1+(5*$b1*$<mult>)} шкоди",
        [8624] = "Завершальний прийом, що завдає шкоди за кожне очко серії; шкода збільшується від сили атаки:\r\n   1 очко  : ${$m1+(1*$b1*$<mult>)}-${$M1+(1*$b1*$<mult>)} шкоди\r\n   2 очки: ${$m1+(2*$b1*$<mult>)}-${$M1+(2*$b1*$<mult>)} шкоди\r\n   3 очки: ${$m1+(3*$b1*$<mult>)}-${$M1+(3*$b1*$<mult>)} шкоди\r\n   4 очки: ${$m1+(4*$b1*$<mult>)}-${$M1+(4*$b1*$<mult>)} шкоди\r\n   5 очок: ${$m1+(5*$b1*$<mult>)}-${$M1+(5*$b1*$<mult>)} шкоди",
        [8627] = "Б’є ціль у спину, завдаючи $s2% шкоди зброєю та ще $s1. Потрібно бути в непомітності позаду цілі. Дає $s3 очко серії.",
        [8629] = "Завдає $s1 шкоди, припиняє вашу атаку та виводить ціль із ладу на $d.  Ціль має дивитися на вас.  Будь-яка отримана шкода перерве ефект.  Дає $s2 $lpoint:очко:очки; серії.",
        [8631] = "Душить ворога, завдаючи $o1 шкоди протягом $d; шкода збільшується від вашої сили атаки.  Потрібно перебувати в непомітності позаду цілі.  Дає $s2 $lpoint:очко:очки; серії.",
        [8632] = "Душить ворога, завдаючи $o1 шкоди протягом $d; шкода збільшується від вашої сили атаки.  Потрібно перебувати в непомітності позаду цілі.  Дає $s2 $lpoint:очко:очки; серії.",
        [8633] = "Душить ворога, завдаючи $o1 шкоди протягом $d; шкода збільшується від вашої сили атаки.  Потрібно перебувати в непомітності позаду цілі.  Дає $s2 $lpoint:очко:очки; серії.",
        [8637] = "Виконує фінт, не завдаючи шкоди, але значно знижуючи вашу загрозу, через що ворог рідше атакуватиме вас.",
        [8639] = "Завершальний прийом, що завдає періодичної шкоди, збільшеної вашою силою атаки.  Тривалість залежить від кількості очок серії:\r\n   1 очко  : ${($m1+$b1)*4} шкоди протягом 8 с\r\n   2 очки: ${($m1+$b1*2)*5} шкоди протягом 10 с\r\n   3 очки: ${($m1+$b1*3)*6} шкоди протягом 12 с\r\n   4 очки: ${($m1+$b1*4)*7} шкоди протягом 14 с\r\n   5 очок: ${($m1+$b1*5)*8} шкоди протягом 16 с",
        [8640] = "Завершальний прийом, що завдає періодичної шкоди, збільшеної вашою силою атаки.  Тривалість залежить від кількості очок серії:\r\n   1 очко  : ${($m1+$b1)*4} шкоди протягом 8 с\r\n   2 очки: ${($m1+$b1*2)*5} шкоди протягом 10 с\r\n   3 очки: ${($m1+$b1*3)*6} шкоди протягом 12 с\r\n   4 очки: ${($m1+$b1*4)*7} шкоди протягом 14 с\r\n   5 очок: ${($m1+$b1*5)*8} шкоди протягом 16 с",
        [8643] = "Завершальний прийом, що приголомшує ціль. Тривалість залежить від очок серії:\r\n   1 очко  : 2 секунди\r\n   2 очки: 3 секунди\r\n   3 очки: 4 секунди\r\n   4 очки: 5 секунд\r\n   5 очок: 6 секунд",
        [8646] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [8647] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [8649] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [8650] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [8656] = "Прикликає $s1 $lCrawler:Crawlers; супроводжувати заклинача, доки їх не відкличуть.",
        [8674] = "Викликає сукубу за допомогою кола виклику.",
        [8676] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброєю та ще 70. Потрібно бути в непомітності позаду цілі. Потребує кинджала в основній руці. Дає $s3 $lpoint:points; серії.",
        [8679] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, миттєво завдаючи $8680s1 шкоди від сил природи. $m2 зарядів.",
        [8680] = "$s1 шкоди від сил природи.",
        [8681] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $8679h% шанс отруїти ворога, миттєво завдаючи $8680s1 шкоди від сил природи. $m3 зарядів.",
        [8682] = "Стріляє в ціль із далекобійної зброї.",
        [8685] = "$s1 шкоди від сил природи.",
        [8686] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, миттєво завдаючи $8685s1 шкоди від сил природи. $m2 зарядів.",
        [8687] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $8686h% шанс отруїти ворога, миттєво завдаючи $8685s1 шкоди від сил природи. $m3 зарядів.",
        [8688] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, миттєво завдаючи $8689s1 шкоди від сил природи. $m2 зарядів.",
        [8689] = "$s1 шкоди від сил природи.",
        [8690] = "Повертає вас до $z. Поговоріть з господарем заїзду в іншому місці, щоб змінити точку повернення.",
        [8691] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $8688h% шанс отруїти ворога, миттєво завдаючи $8689s1 шкоди від сил природи. $m3 зарядів.",
        [8693] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, збільшуючи час застосування його заклять на $8692s1% протягом $8692d. $m2 зарядів.",
        [8694] = "Покриває зброю отрутою на ${$m2/60} хвилин.\r\nКожен удар має $8693h% шанс отруїти ворога, збільшуючи час застосування його заклять на $8692s1% протягом $8692d. $m3 зарядів.",
        [8696] = "Збільшує швидкість руху розбійника на $s1% протягом $d.  Не перериває непомітність.",
        [8699] = "Збільшує швидкість атак союзника на $s1% на $d., але також завдає йому $s2 шкоди від сил природи кожні $t2 сек.",
        [8712] = "Викликає скверногона за допомогою кола виклику.",
        [8713] = "Заклинач періодично завдає всім ворогам у вибраній зоні $8714s1 шкоди від сил природи, перериваючи застосування їхніх заклять на $8714d. Триває до скасування.",
        [8715] = "Змушує ворогів поблизу тікати від страху протягом $d.",
        [8716] = "Приголомшує ворога й зменшує швидкість його руху на $s2%, а також збільшує шкоду заклинача в ближньому бою на $s1. Триває $d.",
        [8717] = "Вивчає «Прикликати скверногона».",
        [8721] = "Завдає цілі удару в спину, спричиняючи $s2% шкоди від зброї плюс $s1 шкоди.  Потрібно перебувати позаду цілі.  Потребує кинджала в основній руці.  Дає $s3 $lpoint:очко:очки; серії.",
        [8722] = "Прикликає $s1 $lSuccubus:Succubi; супроводжувати заклинача, доки їх не відкличуть.",
        [8724] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброєю та ще 100. Потрібно бути в непомітності позаду цілі. Потребує кинджала в основній руці. Дає $s3 $lpoint:points; серії.",
        [8725] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброєю та ще 125. Потрібно бути в непомітності позаду цілі. Потребує кинджала в основній руці. Дає $s3 $lpoint:points; серії.",
        [8732] = "Завдає всім ворогам поблизу $s1 шкоди від сил природи",
        [8735] = "Переносить гравця до Чорноводної Безодні",
        [8736] = "Створює їжу.",
        [8747] = "Збільшує швидкість плавання на $s1%.",
        [8768] = "Створює дві залізні пряжки, що використовуються в інших ремеслах.",
        [8788] = "Оточує союзника $n кулями блискавки, кожна з яких має $h% шанс завдати нападникові в ближньому чи дальньому бою $s1 шкоди. Після кожного спрацювання одна куля розсіюється. Щит зникає через $d. або після $n спрацювань.",
        [8806] = "Завдає ворогові звичайної шкоди та додатково $s2, а потім ще $s1 шкоди від сил природи кожні $t1 сек. протягом $d.",
        [8809] = "Висмоктує з вихованця заклинача $s1 здоров’я, зцілюючи заклинача на величину до 150% цієї кількості.",
        [8812] = "Зцілює заклинача на $s1.",
        [8813] = "Прикликає Підкореного Курзена супроводжувати заклинача, доки його не відкличуть.",
        [8814] = "Викликає стовп полум’я, що завдає всім ворогам у вибраній зоні $s1 шкоди від вогню та ще $s2 шкоди кожні $t2 сек. протягом $d.",
        [8817] = "Кидає димову бомбу, приголомшуючи ворогів поблизу на $d. і переводячи заклинача в непомітність.",
        [8818] = "Під час атаки з непомітності завдає ворогові $s1 шкоди кожні $t1 сек. протягом $d.",
        [8820] = "Завдає супротивнику удару, спричиняючи шкоду від зброї плюс $s1.",
        [8822] = "Переводить заклинача в режим непомітності на $d.",
        [8823] = "Удар, що завдає $s1 шкоди й збільшує отримувану ціллю шкоду від святості на величину до $s2 за кожен Удар хрестоносця.  Накопичується до 5 разів.  Триває $d.",
        [8824] = "Удар, що завдає $s1 шкоди й збільшує отримувану ціллю шкоду від святості на величину до $s2 за кожен Удар хрестоносця.  Накопичується до 5 разів.  Триває $d.",
        [8832] = "Ставить тотем Оберега Занзіла на $d., який періодично прикликає Скелета Зум’ра. Кожен скелет існує $8834d.",
        [8835] = "Прикликає Тотем грації повітря з $s1 здоров’я біля ніг заклинача. Тотем збільшує спритність учасників групи в межах $8836a1 м на $8836s1. Триває $d.",
        [8838] = "Навчає шити Лазурові шовкові рукавиці.",
        [8853] = "Прикликає $s1 $lSkeleton:Skeletons; супроводжувати заклинача, доки їх не відкличуть.",
        [8854] = "Клацніть правою кнопкою миші, щоб спробувати зламати.",
