        [8874] = "Дає розбійнику змогу крастися, але зменшує швидкість до $s2% від звичайної. Триває до скасування.",
        [8876] = "Дає шанс виконати дві додаткові атаки",
        [8892] = "Ці небезпечно виглядаючі чоботи значно збільшують швидкість бігу на $d. Вони схильні вибухати, тож використовуйте обережно.",
        [8898] = "Дає шаманові змогу бачити духів стихій.",
        [8899] = "Дає шаманові змогу бачити духів стихій.",
        [8900] = "Дає шаманові змогу бачити духів стихій.",
        [8903] = "Зцілює дружню ціль на $s1.",
        [8905] = "Завдає цілі $s1 шкоди від сил природи.",
