        [8909] = "Збільшує броню заклинача та опір закляттям на $d.",
        [8910] = "Зцілює ціль на $o1 протягом $d.",
        [8912] = "Візуальний ефект кування Кулака Веріґана Джорданом Стілвеллом.",
