        [11100] = "Збільшує дальність ваших вогняних заклять на $s1 ярдів.",
        [11103] = "Ваші вогняні закляття мають $m1% шанс приголомшити ціль на $12355d.",
        [11108] = "Збільшує шанс критичного удару Вогняного стовпа на $s1%.",
        [11113] = "Хвиля полум’я розходиться від заклинача, завдаючи всім ворогам у вибуху $s1 шкоди від вогню та сповільнюючи їхній рух на $s2% на $d.",
        [11115] = "Збільшує шанс критичного удару ваших вогняних заклять на $s1%.",
        [11119] = "Критичні удари ваших заклять вогню підпалюють ціль, завдаючи додатково $m1% шкоди закляття протягом $412538d.",
        [11124] = "Збільшує шкоду ваших вогняних заклять на $s1%.",
        [11129] = "Після активації кожне влучання вашого вогняного закляття збільшує шанс критичного удару вогняними закляттями на $28682s1%.  Ефект триває, доки ви не завдасте $n неперіодичних критичних ударів вогняними закляттями.",
        [11130] = "Завдає ворогам поблизу звичайної шкоди плюс $s1 і відкидає їх назад.",
        [11131] = "Вистрілює крижаною стрілою, завдаючи ворогові $s2 шкоди від криги та сповільнюючи його рух на $s1% на $d.",
        [11151] = "Збільшує шкоду ваших крижаних заклять на $s1%.",
        [11160] = "Зменшує витрати мани на крижані закляття на $s1% і загрозу від них на $s2%.",
        [11165] = "Зменшує час відновлення Крижаного кільця на $/1000;s1 с.",
        [11170] = "Збільшує шанс критичного удару всіх ваших заклять по заморожених цілях на $m1%.",
        [11175] = "Збільшує тривалість ваших ефектів охолодження на $s1% і додатково зменшує швидкість цілі на $s2%.",
        [11180] = "Ваші закляття крижаної шкоди мають $m2% шанс накласти Зимовий холод, що збільшує шанс критичного удару Крижаного списа та Крижаної стріли по цілі на $12579s1% на $12579d. Накопичується до $s1 разів.",
        [11185] = "Додає до Завірюхи ефект охолодження, який зменшує швидкість руху цілі на $m1% на $12484d.",
        [11189] = "Збільшує броню та опір від Крижаної броні й Льодяної броні на $s1%. Крім того, надає Варті від криги $s2% шанс відбивати крижані закляття й ефекти, поки вона активна.",
        [11190] = "Збільшує шкоду Конуса холоду на $s1%.",
        [11197] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [11198] = "Завершальний прийом, що послаблює броню цілі на $d залежно від очок серії:\r\n   1 очко  : ${$b*-1} броні\r\n   2 очки: ${$b*-2} броні\r\n   3 очки: ${$b*-3} броні\r\n   4 очки: ${$b*-4} броні\r\n   5 очок: ${$b*-5} броні",
        [11201] = "Швидкість руху зменшено на $s1%.",
        [11202] = "Покриває зброю отрутою на ${$m1/60} хвилин.\r\nКожен удар має $h% шанс отруїти ворога, сповільнюючи його рух на $11201s1% на $11201d.",
        [11207] = "Збільшує бонус критичної шкоди ваших крижаних заклять на $s1%.",
        [11209] = "Викликає Молот майстерності.",
        [11210] = "Зменшує опір цілі всім вашим закляттям на $s2 і загрозу від ваших заклять таємної магії на $s1%.",
        [11213] = "Після влучання будь-якого закляття шкоди ви маєте $m1% шанс увійти в стан Ясного розуму.  Ясний розум зменшує витрати мани на ваше наступне закляття шкоди на $/10;12536s1%.",
        [11222] = "Збільшує шанс влучити закляттями таємної магії на $s1%.",
        [11232] = "Збільшує ваш інтелект на $m1% і бонус критичної шкоди заклять таємної магії на $m2%.",
        [11237] = "Надає $m1% шанс уникнути переривання від шкоди під час підтримання Таємних стріл і $m2% шанс під час застосування Таємного вибуху.",
        [11242] = "Збільшує шанс критичного удару ваших заклять таємної магії на $m1%.",
        [11247] = "Збільшує дальність ваших заклять таємної магії на $m1 ярдів.",
        [11252] = "Зменшує втрату мани на одиницю отриманої шкоди, коли активний Щит мани, на $m1% і збільшує опір, наданий Магічною бронею, на $m2%.",
        [11255] = "Ваш Контрзакляття також накладає мовчанку на ціль на ${$m1/1000} с.",
        [11262] = "Зменшує час відновлення Блимання на $/1000;s1 с.",
        [11264] = "Завдає ворогам поблизу $s1 шкоди від криги та заморожує їх на місці на час до $d.",
        [11267] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброї плюс 185.  Потрібно бути в непомітності позаду цілі.  Потрібен кинджал у правій руці.  Дає $s3 $lpoint:points; серії.",
        [11268] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброї плюс 230.  Потрібно бути в непомітності позаду цілі.  Потрібен кинджал у правій руці.  Дає $s3 $lpoint:points; серії.",
        [11269] = "Нападає із засідки, завдаючи цілі $s2% шкоди зброї плюс 290.  Потрібно бути в непомітності позаду цілі.  Потрібен кинджал у правій руці.  Дає $s3 $lpoint:points; серії.",
        [11273] = "Завершальний прийом, що завдає періодичної шкоди, збільшеної вашою силою атаки.  Тривалість залежить від кількості очок серії:\r\n   1 очко  : ${($m1+$b1)*4} шкоди протягом 8 с\r\n   2 очки: ${($m1+$b1*2)*5} шкоди протягом 10 с\r\n   3 очки: ${($m1+$b1*3)*6} шкоди протягом 12 с\r\n   4 очки: ${($m1+$b1*4)*7} шкоди протягом 14 с\r\n   5 очок: ${($m1+$b1*5)*8} шкоди протягом 16 с",
        [11274] = "Завершальний прийом, що завдає періодичної шкоди, збільшеної вашою силою атаки.  Тривалість залежить від кількості очок серії:\r\n   1 очко  : ${($m1+$b1)*4} шкоди протягом 8 с\r\n   2 очки: ${($m1+$b1*2)*5} шкоди протягом 10 с\r\n   3 очки: ${($m1+$b1*3)*6} шкоди протягом 12 с\r\n   4 очки: ${($m1+$b1*4)*7} шкоди протягом 14 с\r\n   5 очок: ${($m1+$b1*5)*8} шкоди протягом 16 с",
        [11275] = "Завершальний прийом, що завдає періодичної шкоди, збільшеної вашою силою атаки.  Тривалість залежить від кількості очок серії:\r\n   1 очко  : ${($m1+$b1)*4} шкоди протягом 8 с\r\n   2 очки: ${($m1+$b1*2)*5} шкоди протягом 10 с\r\n   3 очки: ${($m1+$b1*3)*6} шкоди протягом 12 с\r\n   4 очки: ${($m1+$b1*4)*7} шкоди протягом 14 с\r\n   5 очок: ${($m1+$b1*5)*8} шкоди протягом 16 с",
        [11279] = "Завдає цілі удару в спину, спричиняючи $s2% шкоди від зброї плюс $s1 шкоди.  Потрібно перебувати позаду цілі.  Потребує кинджала в основній руці.  Дає $s3 $lpoint:очко:очки; серії.",
        [11280] = "Завдає цілі удару в спину, спричиняючи $s2% шкоди від зброї плюс $s1 шкоди.  Потрібно перебувати позаду цілі.  Потребує кинджала в основній руці.  Дає $s3 $lpoint:очко:очки; серії.",
        [11281] = "Завдає цілі удару в спину, спричиняючи $s2% шкоди від зброї плюс $s1 шкоди.  Потрібно перебувати позаду цілі.  Потребує кинджала в основній руці.  Дає $s3 $lpoint:очко:очки; серії.",
        [11285] = "Завдає $s1 шкоди, припиняє вашу атаку та виводить ціль із ладу на $d.  Ціль має дивитися на вас.  Будь-яка отримана шкода перерве ефект.  Дає $s2 $lpoint:очко:очки; серії.",
        [11286] = "Завдає $s1 шкоди, припиняє вашу атаку та виводить ціль із ладу на $d.  Ціль має дивитися на вас.  Будь-яка отримана шкода перерве ефект.  Дає $s2 $lpoint:очко:очки; серії.",
        [11289] = "Душить ворога, завдаючи $o1 шкоди протягом $d; шкода збільшується від вашої сили атаки.  Потрібно перебувати в непомітності позаду цілі.  Дає $s2 $lpoint:очко:очки; серії.",
        [11290] = "Душить ворога, завдаючи $o1 шкоди протягом $d; шкода збільшується від вашої сили атаки.  Потрібно перебувати в непомітності позаду цілі.  Дає $s2 $lpoint:очко:очки; серії.",
        [11293] = "Миттєвий удар, що завдає $s1 додаткової шкоди понад звичайну шкоду від зброї.  Дає $s2 $lpoint:очко:очки; серії.",
