        [11407] = "Показує розташування всіх демонів поблизу на мінімапі протягом $d.",
        [11409] = "Переміщує гравця до Гномреґана.",
        [11416] = "Створює портал, що переміщує членів групи, які ним скористаються, до Залізогарта.",
        [11417] = "Створює портал, що переміщує членів групи, які ним скористаються, до Орґріммара.",
        [11418] = "Створює портал, що переміщує членів групи, які ним скористаються, до Підмістя.",
        [11419] = "Створює портал, що переміщує членів групи, які ним скористаються, до Дарнаса.",
        [11420] = "Створює портал, що переміщує членів групи, які ним скористаються, до Громового Бескиду.",
        [11426] = "Миттєво оточує вас щитом, що поглинає $s1 шкоди. Триває $d. Поки щит тримається, отримання шкоди не перериває й не затримує застосування ваших заклять.\r\n",
        [11427] = "Завдає ворогові та його найближчим союзникам звичайної шкоди й додатково $s1, вражаючи до $x1 цілей.",
        [11428] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [11430] = "Збиває ворога на землю, завдаючи фізичної шкоди та приголомшуючи його на $d.",
        [11431] = "Закликає сили природи, щоб зцілити союзника.",
        [11433] = "Закликає згубну силу смерті й розкладу, завдаючи шкоди від тіні всім ворогам у вибраній ділянці протягом $d.",
        [11435] = "Використати біля вівтаря Джинта’Алора, щоб створити Молот Зул’Фаррака.",
