        [11757] = "Клацніть правою кнопкою, щоб видобути кобальт Ґордунні.",
        [11758] = "Наповніть невикористаний лозошукач біля водойми у Варті Піскоскорботних.",
        [11759] = "Перевірте цей зразок на якість.  Потрібен польовий набір для випробувань.",
        [11760] = "Перевірте цей зразок на якість.  Потрібен польовий набір для випробувань.",
