        [16298] = "Збільшує шанс блокувати атаки щитом на $s1% і кількість заблокованої шкоди на $s2%.",
        [16299] = "Збільшує шанс блокувати атаки щитом на $s1% і кількість заблокованої шкоди на $s2%.",
        [16300] = "Збільшує шанс блокувати атаки щитом на $s1% і кількість заблокованої шкоди на $s2%.",
        [16301] = "Збільшує шанс блокувати атаки щитом на $s1% і кількість заблокованої шкоди на $s2%.",
        [16314] = "Наділяє зброю шамана силою, збільшуючи силу атаки ближнього бою на $16311s1 і дозволяючи атакам ближнього бою створювати додаткову загрозу цією зброєю.  Триває 60 хвилин.",
        [16315] = "Наділяє зброю шамана силою, збільшуючи силу атаки ближнього бою на $16312s1 і дозволяючи атакам ближнього бою створювати додаткову загрозу цією зброєю.  Триває 60 хвилин.",
        [16316] = "Наділяє зброю шамана силою, збільшуючи силу атаки ближнього бою на $16313s1 і дозволяючи атакам ближнього бою створювати додаткову загрозу цією зброєю.  Триває 60 хвилин.",
