        [18769] = "Збільшує всю шкоду, яку завдають ваші біси, Порожнечники, сукуби, інкуби й скверногончаки, на $s1%.",
        [18774] = "Збільшує кількість шкоди, яку поглинає ваш Камінь заклять, на $s1%.",
        [18775] = "Збільшує кількість шкоди, яку поглинає ваш Камінь заклять, на $s1%.",
        [18787] = "Збільшує силу атаки на $s1 протягом $d.",
        [18788] = "Після активації приносить у жертву викликаного демона, щоб посилити протилежний аспект вашої сили, надаючи ефект на $18789d. Ефект скасовується, якщо викликати будь-якого демона.\r\n\r\nБіс: збільшує вашу шкоду від тіні на $18789s1%.\r\n\r\nПорожнечник: відновлює $18792s1% від загального запасу мани кожні $18792t1 с.\r\n\r\nСукуб/інкуб: збільшує вашу шкоду від вогню на $18791s1%.\r\n\r\nСкверногончак: відновлює $18790s1% від загального запасу здоров’я кожні $18790t1 с.",
        [18793] = "Використовується, щоб зняти з гравця негативний ефект Приманка для кодо",
        [18796] = "Жбурляє вогняну кулю, що завдає $s1 шкоди від вогню та ще $o2 шкоди протягом $d.",
        [18797] = "Надає $s1 додаткову атаку під час наступного замаху.",
        [18799] = "Під час отримання удару в бою має 1% шанс завдати нападникові $18798s2 шкоди від криги й заморозити його на $18798d.",
        [18802] = "Стріляє у ворога, завдаючи додатково $s1 шкоди від криги та сповільнюючи його рух на $s2% протягом $d.",
        [18803] = "Наступне закляття, застосоване протягом $d, буде миттєвим.",
        [18805] = "Розвіює ефекти Перетворення з дружньої цілі.  Також відновлює $s2 здоров’я та $s3 мани.",
        [18807] = "Атакує розум цілі тіньовою енергією, завдаючи $o1 шкоди від тіні протягом $d і сповільнюючи її рух на $m2%.",
        [18809] = "Жбурляє величезну вогняну брилу, що завдає $s1 шкоди від вогню та додатково $o2 шкоди від вогню протягом $d.",
