        [20026] = "Назавжди зачаровує нагрудний обладунок, надаючи +10 витривалості.",
        [20028] = "Назавжди зачаровує нагрудний обладунок, надаючи +10 інтелекту.",
        [20029] = "Назавжди зачаровує зброю ближнього бою, надаючи їй шанс охолодити ціль і зменшити швидкість її руху та атак.",
        [20030] = "Назавжди зачаровує дворучну зброю ближнього бою, збільшуючи її шкоду на 9.",
        [20031] = "Назавжди зачаровує зброю ближнього бою, збільшуючи її шкоду на 5.",
        [20032] = "Назавжди зачаровує зброю ближнього бою, надаючи їй шанс викрасти життя ворога та передати його власникові зброї.",
        [20033] = "Назавжди зачаровує зброю ближнього бою, надаючи їй шанс накласти на ціль прокляття, що зменшує її шкоду в ближньому бою.",
        [20034] = "Назавжди зачаровує зброю ближнього бою: її атаки мають шанс зцілити на $20007s2 та збільшити силу на $20007s1 на $20007d.",
