        [20040] = "Перетворює одну велику вічну есенцію на три малі.",
        [20041] = "Насіння Геї Таммри Заклиначки",
        [20042] = "Збільшує бонус до сили атаки ближнього бою від вашого «Благословення могутності» на $s1%.",
        [20043] = "Мисливець і всі члени групи та рейду в межах $a1 м переймають аспект дикої природи, збільшуючи опір силам природи на $s1. Одночасно може бути активний лише один аспект.",
        [20045] = "Збільшує бонус до сили атаки ближнього бою від вашого «Благословення могутності» на $s1%.",
        [20046] = "Збільшує бонус до сили атаки ближнього бою від вашого «Благословення могутності» на $s1%.",
        [20047] = "Збільшує бонус до сили атаки ближнього бою від вашого «Благословення могутності» на $s1%.",
        [20048] = "Збільшує бонус до сили атаки ближнього бою від вашого «Благословення могутності» на $s1%.",
        [20049] = "Після неперіодичного критичного удару збільшує завдану вами фізичну шкоду та шкоду від святості на $s1% на $20050d. Сумується до $20050u разів.",
        [20060] = "Збільшує шанс парирування на $s1%.",
        [20066] = "Вводить ворожу ціль у стан медитації, знешкоджуючи її на час до $d. Будь-яка отримана шкода пробуджує ціль. Діє лише на гуманоїдів.",
        [20091] = "Збільшує шкоду від вашої «Аури відплати» на $s1%.",
        [20092] = "Збільшує шкоду від вашої «Аури відплати» на $s1%.",
        [20096] = "Збільшує навичку захисту на $m1.",
        [20101] = "Зменшує витрати мани на всі миттєві закляття та здібності на $m1%.",
        [20111] = "Збільшує шкоду, яку ви завдаєте дворучною зброєю ближнього бою, на $s1%.",
        [20116] = "Освячує землю під паладином, завдаючи ворогам, які входять у цю область, ${$1280346m1*8} шкоди від святості протягом $d. Перші $s3 вороги, що увійдуть в область, отримають додатково ${$1280346m2*8} шкоди протягом $d.",
        [20117] = "Збільшує шанс критичного удару атаками ближнього бою на $s1%.",
        [20127] = "Атаки ближнього бою, що завдають вам шкоди, мають $h% шанс збільшити вашу ймовірність блокування на $m1%. Триває $20128d або до $20128n блокувань.",
        [20138] = "Збільшує бонус броні від вашої «Аури відданості» на $s1%, а також усе отримуване зцілення членами групи під дією ваших аур на $m2%.",
        [20143] = "Збільшує броню від предметів на $s1%.",
        [20148] = "Збільшує кількість шкоди, яку поглинає ваш щит, на $s1%.",
        [20149] = "Збільшує кількість шкоди, яку поглинає ваш щит, на $s1%.",
        [20150] = "Збільшує кількість шкоди, яку поглинає ваш щит, на $m1%, а ваші блокування мають $m2% шанс відновити $1310925m1% від максимальної мани. Може спрацьовувати не частіше ніж раз на $proccooldown с.",
        [20154] = "Сповнює паладина священним духом на $d, завдяки чому кожна атака ближнього бою завдає додатково від $/87;s1 до $/25;s1 шкоди від святості. Повільніша зброя завдає більше шкоди від святості за удар. Одночасно на паладині може бути активна лише одна печатка.",
        [20162] = "Сповнює паладина духом хрестоносця на $d, надаючи $s1 сили атаки ближнього бою. Паладин також атакує на $s2% швидше, але кожна атака завдає менше шкоди. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки накладе на ворога Правосуддя на $20188d, збільшуючи отримувану ним шкоду від святості на величину до $20188s1. Ваші атаки ближнього бою поновлюватимуть тривалість ефекту. Одночасно може бути активне лише одне Правосуддя від кожного паладина.",
        [20163] = "Сповнює паладина божественною люттю на $d, завдяки чому атаки ближнього бою завдають додатково $20231s1 шкоди від святості. Поки споряджено щит, кожна атака також створює щит поглинання, що дорівнює $m2% завданої шкоди від святості. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки завдає ворогові $20183s1 шкоди від святості та провокує ціль атакувати вас протягом $20232d.",
        [20164] = "Сповнює паладина духом справедливості на $d, надаючи кожній атаці ближнього бою шанс приголомшити ціль на $20170d. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки накладе на ворога Правосуддя на $20184d, не даючи йому втекти. Ваші атаки ближнього бою поновлюватимуть тривалість ефекту. Одночасно може бути активне лише одне Правосуддя від кожного паладина.",
        [20165] = "Сповнює паладина божественним світлом на $d, надаючи кожній атаці ближнього бою шанс зцілити паладина на $20167s1. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки накладе на ворога Правосуддя на $20185d, надаючи атакам ближнього бою проти засудженого ворога шанс зцілити нападника на $20267s1. Ваші атаки ближнього бою поновлюватимуть тривалість ефекту. Одночасно може бути активне лише одне Правосуддя від кожного паладина.",
        [20166] = "Сповнює паладина божественною мудрістю на $d, надаючи кожній атаці ближнього бою шанс відновити $20168s1 мани паладина. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки накладе на ворога Правосуддя на $20186d, надаючи атакам і закляттям проти засудженого ворога шанс відновити нападникові $20268s1 мани. Ваші атаки ближнього бою поновлюватимуть тривалість ефекту. Одночасно може бути активне лише одне Правосуддя від кожного паладина.",
        [20174] = "Зменшує час відновлення вашого «Благословення захисту» на $/60000;s1 хв і збільшує тривалість вашого «Благословення свободи» на $/1000;s2 с.",
        [20177] = "Дає вам $m1% шанс отримати додаткову атаку після блокування атаки ближнього бою та ${$m1*2.5}% шанс отримати додаткову атаку після отримання неперіодичного критичного удару.",
        [20178] = "Надає додаткові атаки після блокування.",
        [20183] = "Застосовує Правосуддя до цілі, завдаючи шкоди від святості.",
        [20189] = "Збільшує шанс влучення на $s1%.",
        [20190] = "Мисливець і всі члени групи та рейду в межах $a1 м переймають аспект дикої природи, збільшуючи опір силам природи на $s1. Одночасно може бути активний лише один аспект.",
        [20194] = "Збільшує тривалість вашого «Благословення спасіння» на $/60000;s1 хв.",
        [20195] = "Збільшує тривалість вашого «Благословення спасіння» на $/60000;s1 хв.",
        [20196] = "Збільшує шкоду, яку ви завдаєте одноручною зброєю ближнього бою, на $s1%.",
        [20203] = "Завдає шкоди від вогню ворогам поблизу.",
        [20205] = "Дає вашим закляттям «Спалах Світла», «Світло небес» і «Бдіння Світла» $s1% шанс не втрачати час вимовляння від отриманої шкоди.",
        [20210] = "Після критичного ефекту вашого зцілювального закляття «Спалах Світла», «Світло небес», «Бдіння Світла» або «Священний шок» ви маєте $m1% шанс отримати ману в кількості $m3% від базової вартості закляття.",
        [20216] = "Після активації надає вашому наступному закляттю «Спалах Світла», «Світло небес» або «Священний шок» $s1% шанс критичного ефекту.",
        [20217] = "Накладає на дружню ціль благословення, збільшуючи всі характеристики на $s1% на $d. На гравцеві одночасно може бути активне лише одне благословення від кожного паладина.",
        [20218] = "Збільшує шкоду від святості, яку завдають члени групи в межах $a1 м, на $s1%. На гравцеві одночасно може бути активна лише одна аура від кожного паладина.",
        [20219] = "Дає інженеру змогу створювати дивовижні, хоча й ненадійні, гномські пристрої.",
