        [20224] = "Збільшує шкоду від ваших печаток і правосудь на $s1%.",
        [20228] = "Завдає ворогові $s1 шкоди від вогню та обпалює ціль, завдаючи додатково $s2 шкоди кожні $t2 с протягом $d.",
        [20229] = "Завдає ворогам поблизу $s1 шкоди від вогню та зменшує швидкість їхнього руху на $s2% на $d.",
        [20230] = "Миттєво контратакує будь-якого ворога, який атакує вас у ближньому бою, протягом $d. Атаки ближнього бою ззаду не можна контратакувати. Відплату спричинять не більше $n атак.",
        [20231] = "Завдає додаткової шкоди від святості під час атаки ближнього бою.",
        [20232] = "Провокує ціль атакувати вас.",
        [20237] = "Збільшує зцілення від ваших заклять «Світло небес», «Спалах Світла» та «Священний шок» на $s1%.",
        [20240] = "Примітка розробника: витрачає 1 лють, щоб завдана шкода не генерувала лють.",
        [20243] = "Розколює броню цілі, накладаючи ефект «Розкол броні». Крім того, завдає $s2% шкоди зброї плюс $s3 за кожен ефект «Розкол броні» на цілі. Ефект «Розкол броні» сумується до $u разів.",
        [20244] = "Збільшує ефект вашого закляття «Благословення мудрості» на $s1%.",
        [20245] = "Збільшує ефект вашого закляття «Благословення мудрості» на $s1%.",
        [20249] = "Збільшує шанс критичного ефекту вашого закляття «Спалах Світла» на $s1%.",
        [20250] = "Збільшує шанс критичного ефекту вашого закляття «Спалах Світла» на $s1%.",
        [20251] = "Збільшує шанс критичного ефекту вашого закляття «Спалах Світла» на $s1%.",
        [20252] = "Здійснює ривок до ворога, завдаючи $20253s2 шкоди та приголомшуючи його на $20253d.",
        [20254] = "Збільшує ефект вашої «Аури зосередженості» ще на $m1%, а також зменшує тривалість ефектів мовчання та переривання на членах вашої групи на $m2%.",
        [20257] = "Збільшує ваш загальний інтелект на $s1%.",
        [20262] = "Збільшує вашу силу на $s1%.",
        [20269] = "Помістіть насіння Геї в купу землі Геї.",
        [20270] = "Навчає біса «Вогняній стрілі» (ранг 2).",
        [20271] = "Вивільняє енергію печатки на ворога. Не поглинає печатку. Ефект Правосуддя дивіться в описі відповідної печатки.",
        [20274] = "Допомагає збирати термітів із термітника у Східних Зачумлених землях.",
        [20276] = "Завдає $s2 шкоди ворогові та його найближчим союзникам і приголомшує їх на $d. Уражає до $x1 цілей.",
        [20277] = "Приголомшує ворогів поблизу, не даючи їм рухатися чи атакувати протягом $d.",
        [20279] = "Закликає ворожого гравця.",
        [20287] = "Сповнює паладина священним духом на $d, завдяки чому кожна атака ближнього бою завдає додатково від $/87;20280s3 до $/25;20280s3 шкоди від святості. Повільніша зброя завдає більше шкоди від святості за удар. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки завдає ворогові $20280s1 шкоди від святості.",
        [20288] = "Сповнює паладина священним духом на $d, завдяки чому кожна атака ближнього бою завдає додатково від $/87;20281s3 до $/25;20281s3 шкоди від святості. Повільніша зброя завдає більше шкоди від святості за удар. Одночасно на паладині може бути активна лише одна печатка.\r\n\r\nВивільнення енергії цієї печатки завдає ворогові $20281s1 шкоди від святості.",
