        [27739] = "З'єднує ліву, праву та верхню частини Амулета лорда Вальталака в одне ціле.",
        [27743] = "Рушниці збільшено на +$s1.",
        [27744] = "Навичка володіння арбалетами збільшується на $s1.",
        [27746] = "10 мани за секунду.\r\nЗбільшує швидкість руху на $s1%.",
        [27753] = "Встановлює крижану пастку, що заморожує першого ворога, який наблизиться, не даючи йому діяти до $14309d. Будь-яка отримана шкода розіб'є кригу. Пастка існує $d. Пастки можна встановлювати лише поза боєм. Одночасно може бути активна лише одна пастка.",
        [27757] = "Відкидає ворогів поблизу.",
        [27758] = "Завдає ворогам поблизу звичайної шкоди плюс $s3 та приголомшує їх на $d.",
        [27759] = "Захищає вас щитом мани, що може поглинути до $s1 шкоди. За кожну одиницю поглинутої шкоди витрачається дві одиниці мани.",
        [27760] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [27766] = "Стріляє з гармати в найближчий танчик попереду в межах $a1 м. Завдає $s1 шкоди.",
        [27774] = "Після застосування закляття є шанс збільшити вашу шкоду та зцілення на величину до $27775s1 на $27775d.",
        [27775] = "Збільшує шкоду й зцілення магічними закляттями та ефектами на величину до $s1.",
        [27776] = "Після отримання удару в бою є шанс повернути власникові 350 мани.",
        [27777] = "Відновлює $s1 мани.",
        [27778] = "Після отримання удару в бою має $h% шанс огорнути власника захисним щитом, що поглине $27779s1 шкоди. Може спрацьовувати не частіше ніж раз на $proccooldown с.",
        [27779] = "Поглинає $s1 шкоди.",
        [27780] = "Після отримання удару в бою має $h% шанс змусити нападника тікати в жаху протягом $21330d. Може спрацьовувати не частіше ніж раз на $proccooldown с.",
        [27781] = "Після отримання удару в бою є шанс повернути власникові 300 мани, 10 люті або 40 енергії.",
        [27782] = "Відновлює $s1 мани.",
        [27783] = "Генерує ${$s1/10} люті.",
        [27784] = "Відновлює $o1 енергії протягом $d.",
        [27785] = "Ваші звичайні атаки дальнього бою мають 4% шанс відновити 200 мани.",
        [27786] = "Відновлює 200 мани.",
        [27787] = "Під час атаки ближнього бою є шанс відновити $27788S1 енергії.",
        [27788] = "Відновлює $s1 енергії.",
        [27789] = "Збільшує дальність ваших заклять «Кара» та «Священний вогонь» і радіус «Молитви зцілення» та «Священної нови» на $s1%.",
        [27794] = "Завдає ворогові та його найближчим союзникам звичайної шкоди й додатково $s1, вражаючи до $x1 цілей.",
        [27797] = "Зменшує витрати мани на «Бистрину» на $s1%.",
        [27799] = "Спричиняє вибух священного світла навколо заклинача, завдаючи $s1 шкоди від святості всім ворожим цілям у межах $a1 м і зцілюючи всіх членів групи в межах $27803a1 м на $27803s1. Ці ефекти не створюють загрози.\r\n\r\nЩоразу, коли «Священний вогонь» завдає шкоди, ви маєте 5% шанс, що ваша наступна «Священна нова» не коштуватиме мани.\r\n",
        [27800] = "Спричиняє вибух священного світла навколо заклинача, завдаючи $s1 шкоди від святості всім ворожим цілям у межах $a1 м і зцілюючи всіх членів групи в межах $27804a1 м на $27804s1. Ці ефекти не створюють загрози.\r\n\r\nЩоразу, коли «Священний вогонь» завдає шкоди, ви маєте 5% шанс, що ваша наступна «Священна нова» не коштуватиме мани.\r\n",
        [27801] = "Спричиняє вибух священного світла навколо заклинача, завдаючи $s1 шкоди від святості всім ворожим цілям у межах $a1 м і зцілюючи всіх членів групи в межах $27805a1 м на $27805s1. Ці ефекти не створюють загрози.\r\n\r\nЩоразу, коли «Священний вогонь» завдає шкоди, ви маєте 5% шанс, що ваша наступна «Священна нова» не коштуватиме мани.\r\n",
        [27806] = "Плює отрутою у ворога, завдаючи шкоди від сил природи.",
        [27807] = "Завдає ворогам у конусі перед заклиначем $s2 шкоди від сил природи та додатково $s1 шкоди кожні $t1 с. Опір силам природи зменшується на $s2. Триває $d.",
        [27811] = "Після отримання критичного удару ближнього або дальнього бою чи шкоди від однієї атаки більшої за $m2% вашого максимального здоров'я зцілює $s1% отриманої шкоди протягом $27813d. Поновлення ефекту переносить залишок зцілення.",
        [27813] = "Зцілює ціль протягом $d.",
        [27814] = "Б’є ворога ногою, завдаючи $s1 шкоди та перериваючи застосування закляття на $d.",
        [27825] = "У вихорі сталі ви атакуєте до $i ворогів у межах $a1 ярдів, завдаючи кожному шкоди від зброї.",
