        [370552] = "Збільшує всі характеристики на $s1%.",
        [370575] = "Оскверняє вашу зброю, закликаючи її копію, що допомагатиме вам у бою протягом $d.",
        [370630] = "Підсилює Кел'Тузада та його лейтенантів некромантичною енергією, збільшуючи їхнє здоров'я та шкоду. За перемогу над підсиленими ворогами ви отримаєте додаткові нагороди.\r\n\r\nЕфект сумується та триває цілий тиждень.",
        [370637] = "Закликає та відкликає скелетного коня. Він слухається заклинача й може використовуватися як верхова тварина в Наксрамасі. Будь-яка ворожа дія проти вершника змушує коня в паніці втекти.\r\n",
        [370647] = "Закликає скелетну прив'язь.\r\n\r\nЧлени групи можуть скористатися нею, щоб отримати скелетного коня.\r\n",
        [370831] = "Прикріплює болти до вашої шиї, випадково накладаючи позитивний або негативний заряд, що збільшує шкоду та зцілення на $s1%.\r\n\r\nЕфект сумується поблизу союзників із таким самим зарядом і завдає союзникам із протилежним зарядом шкоди від сил природи.",
        [370832] = "Проколює вас іклом, збільшуючи швидкість руху, атаки та вимовляння заклять на $s1% на $d.",
        [381598] = "Закликає та відкликає скелетного коня. Він слухається заклинача й може використовуватися як верхова тварина в Наксрамасі. Будь-яка ворожа дія проти вершника змушує коня в паніці втекти.\r\n",
        [381599] = "Закликає та відкликає скелетного коня. Він слухається заклинача й може використовуватися як верхова тварина в Наксрамасі. Будь-яка ворожа дія проти вершника змушує коня в паніці втекти.\r\n",
        [384135] = "Надає всім членам рейду шанс знаходити додаткові нагороди з Кел'Тузада та його лейтенантів.\r\n\r\nЕфект сумується та триває цілий тиждень.",
        [384255] = "Застосовує зміни до ваших талантів.",
        [398061] = "Дає 1 комбо-очко щоразу, коли ви уникаєте атаки або закляття ворожої цілі, яка не є вашою поточною ціллю.",
        [398115] = "Завдає вам $s3% шкоди, щоб зняти з себе ефект хвороби або отрути.",
        [398117] = "Відкриває мішечок ласощів і непомітно кладе їх у кишеню цілі, збільшуючи шкоду звірів проти цієї цілі на $s2.",
        [398196] = "Дістає зброю дальнього бою й швидко стріляє у ворога, завдаючи звичайної шкоди зброї дальнього бою та зменшуючи швидкість руху цілі на $s2% на $d. Дає $s3 комбо-$lpoint:points;.\r\n\r\n«Швидкий постріл» отримує користь від усіх талантів і ефектів, що спрацьовують від «Підступної атаки» або змінюють її.\r\n",
        [398197] = "Надає здібність «Швидкий постріл»:\r\n\r\n$@spellicon398196\r\n$@spelldesc398196",
        [398198] = "Завершальний прийом, що збільшує ймовірність парирування. Тривалість і бонус парирування зростають за кожне комбо-очко:\r\n   1 очко  : 10 секунд, 12% парирування\r\n   2 очки: 15 секунд, 14% парирування\r\n   3 очки: 20 секунд, 16% парирування\r\n   4 очки: 25 секунд, 18% парирування\r\n   5 очок: 30 секунд, 20% парирування",
        [398538] = "Назавжди зачаровує наручі, збільшуючи навичку захисту власника на 1.",
        [398603] = "Наносить могутні руни на ваш обладунок.",
        [398608] = "Покриває зброю отрутою, що діє 30 хвилин.\r\nКожен удар має $h% шанс отруїти ворога, сповільнюючи його рух на $3409s1% на $3409d.",
        [398609] = "Покриває зброю отрутою, що діє 30 хвилин.\r\nКожен удар має 30% шанс отруїти ворога, сповільнюючи його рух на $3409s1% на $3409d.",
        [399699] = "Збільшує ймовірність критичного удару на шоломі на 2% на 30 хвилин.",
        [399954] = "Спорядіть предмет у комірку нагрудника з вигравіюваною руною, щоб активувати здібність у цій комірці.",
        [399956] = "Миттєво атакує обома зброями, завдаючи $399960s2% шкоди зброї плюс додатково ${$399960m1*$399960m2/100} кожною зброєю. Шкода збільшується на $m4% проти отруєних цілей. Дає $m1 комбо-$LPoint:Points;.",
        [399962] = "Надає здібність «Калічення»:\r\n\r\n$@spellicon399956\r\n$@spelldesc399956",
        [399965] = "Надає кілька покращень вашим отрутам:\r\n\r\nКоли ви накладаєте на ціль будь-яку іншу отруту, ви також накладаєте «Смертельну отруту».\r\n\r\nЯкщо на вашу зброю не нанесено отруту, вона має шанс спрацювати так, ніби на ній нанесена «Миттєва отрута».\r\n\r\n«Смертельна отрута» та «Миттєва отрута» тепер отримують додаткову шкоду від вашої сили атаки.\r\n\r\nВаша «Смертельна отрута» тепер може діяти на цілях під дією «Смертельної отрути» іншого розбійника.",
        [399966] = "Спорядіть предмет у комірку ніг із вигравіюваною руною, щоб активувати здібність у цій комірці.",
        [399967] = "Спорядіть предмет у комірку рук із вигравіюваною руною, щоб активувати здібність у цій комірці.",
        [399968] = "Надає здібність «Отруєння»:\r\n\r\n$@spellicon399963\r\n$@spelldesc399963",
        [399969] = "Надає здібність «Смертельний настій»:\r\n\r\n$@spellicon399965\r\n$@spelldesc399965",
        [399985] = "Телепортується за спину цілі та атакує, завдаючи $s3% шкоди зброї. Потрібно бути непомітним. Дає $s4 комбо-$lpoint:points;.",
        [399986] = "Кидає сюрикен у ворога, завдаючи шкоди в розмірі $s1% вашої сили атаки, а також вражає до ${$x1-1} додаткових цілей поблизу. Дає $s2 комбо-$lpoint:points; за кожну вражену ціль.\r\n",
        [400009] = "Завершальний прийом дальнього бою, що завдає шкоди за кожне комбо-очко, посиленої силою атаки, та приголомшує ціль:\r\n\r\n   1 очко:   ${$m1/100*($<base>+$<percombo>)}–${$M1/100*($<base>+$<percombo>)} шкоди, 1 с приголомшення\r\n   2 очки: ${$m1/100*($<base>+$<percombo>*2)}–${$M1/100*($<base>+$<percombo>*2)} шкоди, 2 с приголомшення\r\n   3 очки: ${$m1/100*($<base>+$<percombo>*3)}–${$M1/100*($<base>+$<percombo>*3)} шкоди, 3 с приголомшення\r\n   4 очки: ${$m1/100*($<base>+$<percombo>*4)}–${$M1/100*($<base>+$<percombo>*4)} шкоди, 4 с приголомшення\r\n   5 очок: ${$m1/100*($<base>+$<percombo>*5)}–${$M1/100*($<base>+$<percombo>*5)} шкоди, 5 с приголомшення\r\n\r\nМає спільний час відновлення з «Ударом по нирках».",
        [400012] = "Завершальний прийом, що збільшує ймовірність парирування на $s2% і надає $s4 сили атаки за кожну одиницю навички захисту понад ${$PL*5}. Триває довше за кожне комбо-очко:\r\n\r\n   1 очко  : 14 секунд\r\n   2 очки: 18 секунд\r\n   3 очки: 22 секунди\r\n   4 очки: 26 секунд\r\n   5 очок: 30 секунд",
        [400014] = "Поки «Танець клинків» активний, ви отримуєте на $s1% менше фізичної шкоди, ще на 1% менше за кожні $s12 навички захисту понад ${$PL*5}. Крім того, ваша ймовірність ухилення множиться на $s11%, ймовірність отримати критичний удар ближнього бою зменшується на $s3%, ви завдаєте на $s10% менше шкоди, загроза від усіх ваших дій значно збільшується, а «Фінт» замінюється на «Дражнення», що провокує ціль атакувати вас.\r\n\r\n$@spellicon410412\r\n$@spelldesc410412",
        [400016] = "Щоразу, коли ви ухиляєтеся або парируєте, ваш запас здоров'я збільшується на $400015s1%, сумуючись до $s2 разів.",
        [400023] = "Будь-яка атака, яка інакше вбила б вас, натомість залишить вам 10% максимального здоров'я. Крім того, уся отримувана шкода зменшується на величину до $400024s1% на $400024d. Ефект може спрацьовувати не частіше ніж раз на хвилину.",
        [400024] = "Будь-яка атака, яка інакше вбила б вас, натомість залишить вам 10% максимального здоров'я. Крім того, уся отримувана шкода зменшується на величину до $400024s1% на $400024d. Ефект може спрацьовувати не частіше ніж раз на хвилину.",
        [400029] = "Намагається пройти крізь тіні та з'явитися за спиною ворога, збільшуючи швидкість руху на $406722s1% на $406722d.",
        [400031] = "Надає здібність «Тіньовий удар»:\r\n\r\n$@spellicon399985\r\n$@spelldesc399985",
        [400032] = "Надає здібність «Кидок сюрикена»:\r\n\r\n$@spellicon399986\r\n$@spelldesc399986",
        [400033] = "Надає здібність «Між очей»:\r\n\r\n$@spellicon400009\r\n$@spelldesc400009",
        [400037] = "Надає здібність «Крок крізь тінь»:\r\n\r\n$@spellicon400029\r\n$@spelldesc400029",
        [400038] = "Надає здібність «Танець клинків»:\r\n\r\n$@spellicon400012\r\n$@spelldesc400012",
        [400039] = "Надає здібність «Лише подряпина»:\r\n\r\n$@spellicon400014\r\n$@spelldesc400014",
        [400040] = "Надає здібність «Тримати удар»:\r\n\r\n$@spellicon400016\r\n$@spelldesc400016",
        [400080] = "Вигравіюйте на нагрудник або мантію руну «Смертельний настій»:\r\n\r\n$@spellicon399965\r\n$@spelldesc399965",
        [400081] = "Вигравіюйте на штани руну «Між очей»:\r\n\r\n$@spellicon400009\r\n$@spelldesc400009",
        [400082] = "Вигравіюйте на нагрудник або мантію руну «Лише подряпина»:\r\n\r\n$@spellicon400014\r\n$@spelldesc400014",
        [400093] = "Вигравіюйте на чоботи руну «Тримати удар»:\r\n\r\n$@spellicon400016\r\n$@spelldesc400016",
        [400094] = "Вигравіюйте на рукавиці руну «Калічення»:\r\n\r\n$@spellicon399956\r\n$@spelldesc399956",
        [400095] = "Вигравіюйте на нагрудник або мантію руну «Швидкий постріл»:\r\n\r\n$@spellicon398196\r\n$@spelldesc398196",
        [400096] = "Вигравіюйте на пояс руну «Кидок сюрикена»:\r\n\r\n$@spellicon399986\r\n$@spelldesc399986",
        [400099] = "Вигравіюйте на штани руну «Танець клинків»:\r\n\r\n$@spellicon400012\r\n$@spelldesc400012",
        [400101] = "Вигравіюйте на пояс руну «Крок крізь тінь»:\r\n\r\n$@spellicon400029\r\n$@spelldesc400029",
        [400102] = "Вигравіюйте на штани руну «Отруєння»:\r\n\r\n$@spellicon399963\r\n$@spelldesc399963",
        [400104] = "Вигравіюйте на штани руну «Крок крізь тінь»:\r\n\r\n$@spellicon400029\r\n$@spelldesc400029",
        [400105] = "Вигравіюйте на рукавиці руну «Тіньовий удар»:\r\n\r\n$@spellicon399985\r\n$@spelldesc399985",
        [400573] = "Вражає ціль енергією, завдаючи шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d.",
        [400574] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [400586] = "Вражає ціль енергією, завдаючи шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших заклять таємної магії збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d.",
        [400588] = "Надає вашому «Таємному вибуху» $m1% шанс, а «Вогняній кулі», «Крижаній стрілі» та «Крижановогняній стрілі» — ${$m1/2}% шанс зменшити тривалість підтримання наступних «Таємних стріл» на $400589s1%, витрати мани — на $400589s3%, а стріли випускатимуться кожні ${$m2/10}.1 с.",
        [400589] = "Ваші «Таємний вибух», «Вогняна куля» та «Крижана стріла» мають шанс зменшити тривалість підтримання наступних «Таємних стріл» на $400589s1%, витрати мани — на $s3%, а стріли випускатимуться кожні ${$400588m2/10}.1 с.",
        [400610] = "Випускає кілька стріл у ворожу ціль, завдаючи від ${$<power>*$m1/100} до ${$<power>*$M1/100} шкоди від таємної магії. Це закляття також має ${$400588h/2}% шанс спричинити «Шквал стріл».",
        [400613] = "Ціль стає Живою бомбою, отримуючи ${$<power>*$400613m1/100*4} шкоди від вогню протягом $d. Через $d або після розсіювання закляття ціль вибухає, завдаючи ${$<power>*$400614m1/100} шкоди від вогню всім ворогам у межах $400614a1 м.\r\n\r\n«Жива бомба» отримує користь від усіх талантів і ефектів, що спрацьовують від «Опіку» або змінюють його.",
        [400614] = "Ціль стає Живою бомбою, отримуючи ${$<power>*$400613m1/100*4} шкоди від вогню протягом $d. Через $d або після розсіювання закляття ціль вибухає, завдаючи ${$<power>*$400614m1/100} шкоди від вогню всім ворогам у межах $400614a1 м.",
        [400615] = "«Вогняний вибух» завжди завдає критичного удару, може застосовуватися під час вимовляння іншого закляття й не залежить від глобального часу відновлення, але його час відновлення збільшується до $s9 с.",
        [400616] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400618] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400619] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400620] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400621] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400622] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400623] = "Уражає ворога, завдаючи $s1 шкоди від вогню.",
        [400624] = "Ваші неперіодичні критичні удари «Вогняною кулею», «Крижановогняною стрілою», «Вогняним вибухом» та «Опіком» надають «Гарячу серію» на $400625d. «Гаряча серія» зменшує час вимовляння «Вогняного спалаху» на $400625s1%, сумуючись до $400625s2 разів.",
        [400625] = "Ваші неперіодичні критичні удари «Вогняною кулею», «Крижановогняною стрілою», «Вогняним вибухом» та «Опіком» надають «Гарячу серію» на $400625d. «Гаряча серія» зменшує час вимовляння «Вогняного спалаху» на $400625s1%, сумуючись до $400625s2 разів.\r\n",
        [400640] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [400647] = "Ваші ефекти охолодження мають $s2% шанс надати «Пальці криги», через що ваші наступні $m1 $lspell:spells; вважають ціль замороженою. Триває $400669d.",
        [400669] = "Ваші ефекти охолодження мають шанс надати «Пальці криги», через що ваші наступні закляття вважають ціль замороженою. Триває $d.",
        [400670] = "Ваші ефекти охолодження мають шанс надати «Пальці криги», через що ваші наступні закляття вважають ціль замороженою. Триває $d.",
        [400730] = "Ваше наступне закляття «Вогняна куля», «Крижана стріла заклять», «Згубна стріла» або «Крижановогняна стріла» стає миттєвим і не коштує мани.",
        [400731] = "Ваші закляття шкоди від криги з ефектами охолодження мають $h% шанс зробити наступну «Вогняну кулю», «Крижану стрілу заклять», «Згубну стрілу» або «Крижановогняну стрілу» миттєвою й безкоштовною.",
        [400735] = "Записує просторово-часове положення цілі. $s4% усієї шкоди від таємної магії, завданої заклиначем, перетворюється на хрономантичне зцілення кожної поточної цілі «Часового маяка» заклинача. Це зцілення зменшується на $s5% для самого заклинача та ще на $s6%, коли шкоду завдають закляття таємної магії, що вражають кілька цілей.",
        [401417] = "Зцілює ціль на ${$<healpower>*$m1/100*3} здоров'я протягом $d і накладає «Часовий маяк» на $400735s3 с. \r\n\r\nЧасовий маяк\r\n$@spellicon400735\r\n$@spelldesc400735",
        [401460] = "Зцілює ціль на ${$<healpower>*$m1/100*3} здоров'я протягом $d і накладає «Часовий маяк» на ${$400735m3*2/3} с.\r\n\r\n$@spellicon400735\r\n$@spelldesc400735",
        [401462] = "Ваша поточна ціль із «Часовим маяком» миттєво зцілює всю шкоду, отриману за останні $s1 секунд. Не діє на цілі, які не мали «Часового маяка» $s1 секунд тому.",
        [401488] = "Вигравіюйте на штанах руну «Тіньовий удар»:\r\n\r\n$@spellicon399985\r\n$@spelldesc399985",
        [401502] = "Запускає у ворога крижановогняну стрілу, завдаючи $s2 шкоди від крижаного вогню, сповільнюючи рух на $s1% і завдаючи додатково $o3 шкоди від крижаного вогню протягом $d. Закляття перевіряється проти меншого з опорів цілі кризі та вогню й вважається одночасно шкодою від криги та вогню.",
        [401556] = "Закликає полум'я чаровогню, що рухається до цілі, залишаючи за собою слід чаровогню. Цей слід щосекунди завдає ворогам поблизу ${$<power>*$401558m1/100} шкоди від чаровогню. Триває $d.",
        [401558] = "Завдає ${$<power>*$m1/100} шкоди від вогню кожні $t1 с.",
        [401617] = "Викопує скарб у позначеному місці.",
        [401681] = "Розшифруйте нотатки про закляття за допомогою «Підручника розуміння», щоб вивчити нове закляття гравіювання.",
        [401683] = "Спробуйте перекласти нотатки про закляття в новий рецепт вирізьблення рун.",
        [401684] = "Спробуйте перекласти нотатки про закляття в новий рецепт вирізьблення рун.",
        [401699] = "Поєднайте 8 нотаток учнів Азори, щоб відкрити новий рецепт вирізьблення рун.",
        [401719] = "Надає здібність «Таємний залп»:\r\n\r\n$@spellicon400610\r\n$@spelldesc400610",
        [401722] = "Вигравіюйте на плащі руну «Таємний залп»:\r\n\r\n$@spellicon400610\r\n$@spelldesc400610",
        [401724] = "Надає здібність «Гаряча серія»:\r\n\r\n$@spellicon400624\r\n$@spelldesc400624",
        [401725] = "Надає здібність «Замороження мозку»:\r\n\r\n$@spellicon400731\r\n$@spelldesc400731",
        [401726] = "Надає здібність «Покращений захист»:\r\n\r\n$@spellicon412115\r\n$@spelldesc412115",
        [401729] = "Надає здібність «Таємний вибух»:\r\n\r\n$@spellicon400574\r\n$@spelldesc400574",
        [401731] = "Надає здібність «Жива бомба»:\r\n\r\n$@spellicon400613\r\n$@spelldesc400613",
        [401732] = "Надає здібність «Крижаний спис»:\r\n\r\n$@spellicon400640\r\n$@spelldesc400640",
        [401734] = "Надає здібність «Перемотування часу»:\r\n\r\n$@spellicon401462\r\n$@spelldesc401462",
        [401735] = "Надає здібність «Крижановогняна стріла»:\r\n\r\n$@spellicon401502\r\n$@spelldesc401502",
        [401736] = "Ви отримуєте здібність «Залп стріл»:\r\n\r\n$@spellicon400588\r\n$@spelldesc400588",
        [401737] = "Ви отримуєте здібність «Перегрів»:\r\n\r\n$@spellicon400615\r\n$@spelldesc400615",
        [401741] = "Ви отримуєте здібність «Пальці криги»:\r\n\r\n$@spellicon400647\r\n$@spelldesc400647",
        [401743] = "Ви отримуєте здібність «Відновлення»:\r\n\r\n$@spellicon401417\r\n$@spelldesc401417",
        [401744] = "Ви отримуєте здібність «Живе полум’я»:\r\n\r\n$@spellicon401556\r\n$@spelldesc401556",
        [401749] = "Вигравіюйте на шоломі руну «Смуга везіння»:\r\n\r\n$@spellicon400624\r\n$@spelldesc400624",
        [401752] = "Вигравіюйте на чоботах руну «Замороження мозку»:\r\n\r\n$@spellicon400731\r\n$@spelldesc400731",
        [401754] = "Вигравіюйте на шоломі руну «Посилені обереги»:\r\n\r\n$@spellicon412115\r\n$@spelldesc412115",
        [401757] = "Вигравіюйте на рукавицях руну «Таємний вибух»:\r\n\r\n$@spellicon400574\r\n$@spelldesc400574",
        [401759] = "Вигравіюйте на нагруднику руну «Вигорання»:\r\n\r\n$@spellicon412286\r\n$@spelldesc412286",
        [401760] = "Вигравіюйте на рукавицях руну «Крижаний спис»:\r\n\r\n$@spellicon400640\r\n$@spelldesc400640",
        [401761] = "Вигравіюйте на наручах руну «Перемотування часу»:\r\n\r\n$@spellicon401462\r\n$@spelldesc401462",
        [401762] = "Вигравіюйте на поясі руну «Крижано-вогняна стріла»:\r\n\r\n$@spellicon401502\r\n$@spelldesc401502",
        [401763] = "Вигравіюйте на поясі руну «Залп стріл»:\r\n\r\n$@spellicon400588\r\n$@spelldesc400588",
        [401764] = "Вигравіюйте на плащі руну «Перегрів»:\r\n\r\n$@spellicon400615\r\n$@spelldesc400615",
        [401765] = "Вигравіюйте на нагруднику або мантії руну «Пальці криги»:\r\n\r\n$@spellicon400647\r\n$@spelldesc400647",
        [401767] = "Вигравіюйте на нагруднику або мантії руну «Відновлення»:\r\n\r\n$@spellicon401417\r\n$@spelldesc401417",
        [401768] = "Вигравіюйте на штанях руну «Живе полум’я»:\r\n\r\n$@spellicon401556\r\n$@spelldesc401556",
        [401847] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [401859] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [401863] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $41635a1 ярдів. Перескакує до $48113n разів і триває $48111d після кожного переходу. Одночасно це закляття може бути накладене лише на одну ціль.\r\n",
        [401877] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [401937] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [401946] = "Зцілює всіх учасників групи вибраного гравця в межах $a1 ярдів від нього на ${$<healpower>*$m1/100}–${$<healpower>*$M1/100}.",
        [401955] = "Слово темних пут, що завдає цілі від ${$<damagepower>*$m1/100} до ${$<damagepower>*$M1/100} шкоди від тіні.  Якщо ціль не загине від Слова Тіні: Смерть, заклинач отримує шкоду в розмірі $m2% від шкоди, яку мало бути завдано цілі.",
        [401962] = "Слово темних пут, що завдає цілі шкоди від тіні.  Якщо ціль не загине від Слова Тіні: Смерть, заклинач отримує стільки ж шкоди, скільки було завдано цілі.",
        [401969] = "Ваше Слово Тіні: Біль тепер також уражає до ${$m1-1} додаткових цілей поблизу в межах $s2 ярдів.",
        [401977] = "Створює тіньового демона, який атакує ціль.  Коли Тіньовий демон атакує, заклинач отримує $401988s1% мани. Триває $d.",
        [401984] = "Атаки Тіньового демона в ближньому бою висмоктують енергію з цілі й перетворюють її на ману для його господаря.",
        [401988] = "Атаки Тіньового демона в ближньому бою висмоктують енергію з цілі й перетворюють її на ману для його господаря.",
        [401990] = "Пробирається крізь тіні до ворожої цілі та збільшує шкоду Тіньового демона на $s2% протягом $d.",
        [402000] = "Зменшує час відновлення Слова сили: Щит на ${$m1/-1000} с і витрати мани на нього на $s2%.",
        [402004] = "Миттєво зменшує всю шкоду, яку отримує дружня ціль, на $s1% і підвищує опір механікам розвіювання на $s2% протягом $d.",
        [402010] = "Повертається до звичайної форми.",
        [402174] = "Випускає в ціль залп святого світла, що миттєво й кожні $402261t2 с протягом $402261d завдає ворогові $402284s1 шкоди від святості або зцілює союзника на $402289s1.",
        [402261] = "Завдає шкоди від святості кожні $t2 с.",
        [402277] = "Зцілення кожні $t2 с протягом $d.",
        [402284] = "Завдає $s1 шкоди від святості кожні $402261t2 с.",
        [402289] = "Зцілює на $s1 кожні $402277t2 с протягом $402277d.",
        [402308] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [402311] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [402319] = "Поєднайте 6 нотаток учня Азори, щоб створити новий рецепт гравіювання.",
        [402668] = "Накладає на ціль ваш талант Вампірські обійми, завдає їй ${$<damagepower>*$m2/100*5} шкоди від тіні протягом $d і змушує всіх учасників групи відновлювати ману в розмірі $s1% від шкоди тіньовими закляттями, яку ви завдаєте цілі.",
        [402779] = "$s1% отриманої шкоди від тіньових заклять відновлює ману групі жерця.",
        [402789] = "Викликає Око Порожнечі, яке битиметься за вас протягом $d. Око може накладати на вашу ціль різні прокляття.",
        [402790] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [402791] = "Проклинає ціль на $d, зменшуючи її опір тіні й таємній магії на $s1 та збільшуючи отримувану шкоду від тіні й таємної магії на $s2%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [402792] = "Проклинає ціль на $d, зменшуючи її опір вогню й кризі на $s1 та збільшуючи отримувану шкоду від вогню й криги на $s2%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.",
        [402794] = "Змушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклять на $s1%.  На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.  Триває $d.",
        [402799] = "Відколює уламки вашої душі, оживляючи $s1 мініатюрних копій вас, які намагаються атакувати поточну ціль булавою, мечем і сокирою, відповідно зменшуючи швидкість атаки, силу атаки та броню будь-якої враженої цілі.",
        [402801] = "Оживляє $s1 скелетів, які атакують вашу поточну ціль булавою, мечем і сокирою, відповідно зменшуючи її швидкість атаки, силу атаки та броню.",
        [402802] = "Оживляє $s1 скелетів, які атакують вашу поточну ціль булавою, мечем і сокирою, відповідно зменшуючи її швидкість атаки, силу атаки та броню.",
        [402808] = "Збільшує час між атаками ворога на $s1%. Триває $d.",
        [402811] = "Зменшує силу атаки цілі на $s1. Триває $d.",
        [402818] = "Зменшує броню ворога на $s1. Триває $d.",
        [402832] = "Ви отримуєте здібність «Молитва відновлення»:\r\n\r\n$@spellicon401859\r\n$@spelldesc401859",
