        [402854] = "Вигравіюйте на штанях руну «Спільний біль»:\r\n\r\n$@spellicon401969\r\n$@spelldesc401969",
        [402855] = "Вигравіюйте на чоботах руну «Придушення болю»:\r\n\r\n$@spellicon402004\r\n$@spelldesc402004",
        [402857] = "Вигравіюйте на плащі руну «Вампірський дотик»:\r\n\r\n$@spellicon402668\r\n$@spelldesc402668",
        [402859] = "Вигравіюйте на рукавицях руну «Коло зцілення»:\r\n\r\n$@spellicon401946\r\n$@spelldesc401946",
        [402861] = "Вигравіюйте на штанях руну «Тіньовий демон»:\r\n\r\n$@spellicon401977\r\n$@spelldesc401977",
        [402862] = "Вигравіюйте на рукавицях руну «Спокута»:\r\n\r\n$@spellicon402174\r\n$@spelldesc402174",
        [402864] = "Вигравіюйте на шоломі руну «Око Порожнечі»:\r\n\r\n$@spellicon402789\r\n$@spelldesc402789",
        [402877] = "Ви отримуєте лють від отриманої фізичної шкоди так, ніби не носите броні.",
        [402911] = "Лютий удар, що завдає $s1% шкоди зброєю, але його можна використати лише під дією Шаленства, Берсеркерської люті або Кривавої люті. Кожна інша здібність ближнього бою, використана під дією Шаленства, Берсеркерської люті або Кривавої люті, зменшує решту часу відновлення Лютого удару на $s3 с.",
        [402913] = "Зцілює вас на $o1% від максимального запасу здоров’я протягом $d, але може бути використано лише під дією Шаленства, Берсеркерської люті або Кривавої люті. Можна використовувати під час приголомшення.\r\n",
        [402922] = "Удар щитом тепер застосовується миттєво, але має час відновлення ${$m2/1000} с.",
        [402927] = "Миттєво атакує ціль, завдаючи ${1+$AP*$m3/100} шкоди та зцілюючи вас на $s2% від максимального запасу здоров’я.  Можна використати лише протягом $402975d після вбивства нетривіального ворога.",
        [402975] = "Стає доступним після вбивства ворога.",
        [403195] = "Поки ви перебуваєте в Захисній стійці та маєте споряджений щит, Розкол броні також завдає шкоди в розмірі $403196s1% від шкоди за секунду вашої спорядженої зброї, збільшеної на $403196s2% за кожен уже накладений на ціль ефект Розколу броні. Шкода Спустошення створює велику кількість загрози, поки ви перебуваєте в Захисній стійці.",
        [403196] = "Розкол броні також завдає $s1% шкоди зброєю, збільшеної на $s2% за кожен уже накладений на ціль ефект Розколу броні.",
        [403215] = "Воїн вигукує бойовий клич, збільшуючи витривалість усіх учасників групи в межах $a1 ярдів на $s1.  Триває $d.",
        [403218] = "Ви генеруєте на $s1% більше люті від усієї завданої вами шкоди.",
        [403219] = "Грім тепер додатково збільшує час між атаками на $s1%, може використовуватися в будь-якій стійці, завдає на $s4% більше шкоди та створює на $s3% більше загрози.",
        [403228] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас. Не діє на ворогів вище ${$PL+1} рівня або позначених як боси.",
        [403231] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас.",
        [403233] = "Кидає ланцюг із гаком, стримуючи ціль і притягуючи її до вас. Під час притягування ціль не може бути приголомшена.",
        [403332] = "Стріляє в ціль, завдаючи $s2% шкоди зброєю дальнього бою. Генерує ${$m3/10} люті.",
        [403344] = "Ви отримуєте здібність «Бичування»:\r\n\r\n$@spellicon402877\r\n$@spelldesc402877",
        [403349] = "Ви отримуєте здібність «Нескінченна лють»:\r\n\r\n$@spellicon403218\r\n$@spelldesc403218",
        [403352] = "Ви отримуєте здібність «Криваве шаленство»:\r\n\r\n$@spellicon412507\r\n$@spelldesc412507",
        [403355] = "Ви отримуєте здібність «Спустошення»:\r\n\r\n$@spellicon403195\r\n$@spelldesc403195",
        [403356] = "Ви отримуєте здібність «Лютий грім»:\r\n\r\n$@spellicon403219\r\n$@spelldesc403219",
        [403359] = "Ви отримуєте здібність «Шалене відновлення»:\r\n\r\n$@spellicon402913\r\n$@spelldesc402913",
        [403434] = "Ви отримуєте здібність «Переможний ривок»:\r\n\r\n$@spellicon402927\r\n$@spelldesc402927",
        [403435] = "Ви отримуєте здібність «Командирський крик»:\r\n\r\n$@spellicon403215\r\n$@spelldesc403215",
        [403436] = "Ви отримуєте здібність «М’ясний гак»:\r\n\r\n$@spellicon403228\r\n$@spelldesc403228",
        [403437] = "Ви отримуєте здібність «Втручання»:\r\n\r\n$@spellicon403338\r\n$@spelldesc403338",
        [403446] = "Вигравіюйте на штанях руну «Командирський крик»:\r\n\r\n$@spellicon403215\r\n$@spelldesc403215",
        [403467] = "Вигравіюйте на чоботах руну «Шалене відновлення»:\r\n\r\n$@spellicon402913\r\n$@spelldesc402913",
        [403470] = "Вигравіюйте на рукавицях руну «Переможний ривок»:\r\n\r\n$@spellicon402927\r\n$@spelldesc402927",
        [403472] = "Вигравіюйте на чоботах руну «Втручання»:\r\n\r\n$@spellicon403338\r\n$@spelldesc403338",
        [403474] = "Вигравіюйте на нагруднику руну «Криваве шаленство»:\r\n\r\n$@spellicon412507\r\n$@spelldesc412507",
        [403475] = "Вигравіюйте на рукавицях руну «Спустошення»:\r\n\r\n$@spellicon403195\r\n$@spelldesc403195",
        [403476] = "Вигравіюйте на штанях руну «Лютий грім»:\r\n\r\n$@spellicon403219\r\n$@spelldesc403219",
        [403480] = "Вигравіюйте на нагруднику руну «Бичування»:\r\n\r\n$@spellicon402877\r\n$@spelldesc402877",
        [403489] = "Вигравіюйте на шоломі руну «Нескінченна лють»:\r\n\r\n$@spellicon403218\r\n$@spelldesc403218",
        [403501] = "Посилає примарну душу атакувати вашу поточну ціль, завдаючи $s1 шкоди та збільшуючи всю періодичну шкоду від тіні, яку ви завдаєте цій цілі, на $s2% протягом $d. Коли Переслідування завершується з будь-якої причини, ви зцілюєтеся на $s3% від шкоди, завданої ним цілі.",
        [403511] = "Збільшує висмоктане здоров’я або шкоду від Висмоктування життя, Висмоктування душі та Мордування на $m1%.",
        [403619] = "Оточує заклинача енергією Скверни, збільшуючи силу заклять і зцілення на $s3, а також додатково на величину, що дорівнює $s1% вашого духу. Крім того, ви відновлюєте $s2% максимального запасу здоров’я кожні 5 с. Одночасно на чорнокнижнику може діяти лише одне закляття броні.  Триває $d.\r\n",
        [403628] = "Ваша Тіньова стріла тепер вражає до $s1 цілей ланцюгом на відстані до $s2 ярдів між ними, але завдає на $s3% менше шкоди.",
        [403629] = "Посилає у ворога стрілу хаотичного вогню, завдаючи від ${$<power>*$m1/100} до ${$<power>*$M1/100} шкоди хаосом.  Стріла хаосу завжди влучає, їй неможливо чинити опір, а знання цього закляття дозволяє всім вашим вогняним закляттям пробивати ефекти поглинання. Проти чудовиськ на 4 або більше рівнів вище за вас Стріла хаосу має високий шанс зустріти опір.",
        [403650] = "Вогняний дощ також залишає на землі Озеро вогню, яке збільшує всю шкоду від вогню, яку ви та ваш демон завдаєте ураженим ворогам, на $s1%.",
        [403666] = "Вогняний дощ більше не потребує підтримання, але отримує час відновлення $s5 с.",
        [403668] = "Висмоктування життя більше не потребує підтримання, триває $403677d і має час відновлення $403677d, коштує на $s2% більше мани та зцілює вас на $s1% більше щоразу, коли завдає шкоди.",
        [403677] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403685] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403686] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403687] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403688] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403689] = "Переносить $s1 здоров’я щосекунди від цілі до заклинача.  Триває $d.",
        [403789] = "Перетворює вас на демона, збільшуючи броню на $403816s1%, здоров’я на $403816s6%, зменшуючи шанс отримати критичний удар на $403816s2%, збільшуючи створювану загрозу на $403816s3% і ману від Переливання життя на $403816s4%, але зменшуючи всю завдану вами шкоду на $403816s5%. Метаморфоза змінює дію деяких здібностей і надає нові:\r\n\r\nПекучий біль: тепер миттєвий.\r\n\r\nТіньова стріла: перетворюється на Тіньовий розтин — атаку тінню в ближньому бою, що вражає до $403835x1 ворогів поблизу, але має час відновлення $s6 с.\r\n\r\nСтрах: замінюється Загрозою.\r\n\r\n$@spellicon403828\r\n$@spelldesc403828\r\n\r\n\r\nДемонічний ривок\r\n\r\n$@spellicon412788\r\n$@spelldesc412788\r\n\r\n\r\nДемонічне виття\r\n\r\n$@spellicon412789\r\n$@spelldesc412789",
        [403816] = "Перетворює вас на демона, збільшуючи броню на $s1%, зменшуючи шанс отримати критичний удар на $s2%, збільшуючи створювану загрозу на $s3%, збільшуючи ману від Переливання життя на $s4% і змінюючи дію деяких здібностей:\r\n\r\nПекучий біль: тепер миттєвий.\r\n\r\nТіньова стріла: перетворюється на Тіньовий розтин — атаку тінню в ближньому бою, що вражає до $s1 ворогів поблизу.\r\n\r\nПрокляття нерозважності: тепер також провокує ціль атакувати вас протягом $d.\r\n\r\nВиття жаху: тепер також змушує всіх ворогів поблизу атакувати вас протягом $d, але час відновлення збільшено до 10 хвилин.",
        [403828] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [403835] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]",
        [403839] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403840] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403841] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403842] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403843] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403844] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403848] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403851] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403852] = "Карає до $x1 ворогів поблизу тіньовим ударом, завдаючи кожному $s1 шкоди.\r\n\r\nТіньовий розтин отримує переваги від більшості талантів та ефектів, що впливають на Тіньову стрілу, і запускає їх.$?s446847[\r\n\r\nHitting a target with Shadow Cleave also grants you $460200s3 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.][]\r\n",
        [403858] = "Ви отримуєте здібність «Переслідування»:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501",
        [403860] = "Ви отримуєте здібність «Стріла хаосу»:\r\n\r\n$@spellicon403629\r\n$@spelldesc403629",
        [403863] = "Ви отримуєте здібність «Сифон душі»:\r\n\r\n$@spellicon403511\r\n$@spelldesc403511",
        [403868] = "Ви отримуєте здібність «Майстер підтримання»:\r\n\r\n$@spellicon403668\r\n$@spelldesc403668",
        [403871] = "Ви отримуєте здібність «Залп тіньових стріл»:\r\n\r\n$@spellicon403628\r\n$@spelldesc403628",
        [403872] = "Ви отримуєте здібність «Озеро вогню»:\r\n\r\n$@spellicon403666\r\n$@spelldesc403666",
        [403873] = "Ви отримуєте здібність «Метаморфоза»:\r\n\r\n$@spellicon403789\r\n$@spelldesc403789",
        [403919] = "Вигравіюйте на рукавицях руну «Переслідування»:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501",
        [403920] = "Вигравіюйте на плащі руну «Сифон душі»:\r\n\r\n$@spellicon403511\r\n$@spelldesc403511",
        [403925] = "Вигравіюйте на рукавицях руну «Стріла хаосу»:\r\n\r\n$@spellicon403629\r\n$@spelldesc403629",
        [403932] = "Вигравіюйте на нагруднику або мантії руну «Майстер підтримання»:\r\n\r\n$@spellicon403668\r\n$@spelldesc403668",
        [403936] = "Вигравіюйте на рукавицях руну «Залп тіньових стріл»:\r\n\r\n$@spellicon403628\r\n$@spelldesc403628",
        [403937] = "Вигравіюйте на нагруднику або мантії руну «Озеро вогню»:\r\n\r\n$@spellicon403666\r\n$@spelldesc403666",
        [403938] = "Вигравіюйте на рукавицях руну «Метаморфоза»:\r\n\r\n$@spellicon403789\r\n$@spelldesc403789",
        [404275] = "Завдає ворогам поблизу шкоди від криги, знерухомлюючи їх на час до $d.",
        [405092] = "Тривалість підводного дихання зменшується на $s1%.",
        [405325] = "Викопайте схований запас у позначеному місці.",
        [405667] = "Створює предмет.",
        [406634] = "Викликає та відпускає їздове оживлене панцир’я омара.",
        [406651] = "Поєднайте з 2 іншими частинами, щоб скласти повну руну.",
        [406722] = "Намагається ступити крізь тіні й з’явитися позаду ворога, а також збільшує швидкість руху на $s2% протягом $d.",
        [406746] = "Обдає всіх ворогів перед вами струменем води під тиском.",
        [407546] = "Замерз намертво.",
        [407580] = "Викликає Собоза.",
        [407627] = "Збільшує загрозу від ваших заклять святості на $s5% і відновлює вам ману, коли вас зцілюють закляття інших дружніх цілей, у розмірі $s4% від отриманого зцілення. Крім того, шкода, що знижує ваше здоров’я нижче $407627s6%, зменшується на $407627s7%. Триває $d.\r\n",
        [407628] = "Відновлює ману від отриманого зцілення.",
        [407632] = "Б’є поточну ціль і до ${$x1-1} додаткових цілей поблизу, завдаючи кожній шкоди від святості в розмірі $s3 від шкоди за секунду вашої зброї в основній руці. Має спільний час відновлення з Ударом хрестоносця.",
        [407653] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній шкоди від сил природи.",
        [407667] = "Вражає ворога блискавкою, що розгалужується на всі цілі поблизу, завдаючи кожній шкоди від сил природи.",
        [407720] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній шкоди від сил природи.",
        [407736] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній шкоди від сил природи.",
        [407745] = "Вражає ворога блискавкою, що розгалужується на всі цілі поблизу, завдаючи кожній шкоди від сил природи.",
        [407778] = "Миттєва атака зброєю, що завдає $s1% шкоди зброєю до ${$i-1} ворогам у межах $a3 ярдів.  Божественна буря зцілює до 3 учасників групи або рейду загалом на $s2% від завданої шкоди.",
        [407782] = "Шкода від Божественної бурі зцілює дружні цілі.",
        [407784] = " Шкода від Божественної бурі зцілює дружні цілі поблизу.",
        [407788] = "Збільшує всю завдану шкоду та зцілення на $s1% протягом $d.  Спричиняє Стриманість і не може використовуватися, поки Стриманість активна.",
        [407791] = "Збільшує фізичну шкоду заклинача на $s1 і прискорює його атаки на $s2% протягом $d.",
        [407794] = "Завдає ворогові фізичної шкоди кожні $t1 с. протягом $d.",
        [407798] = "Наповнює вас святим духом на $d, через що кожна ваша атака ближнього бою завдає цілі $407799s1% шкоди зброєю, але ви втрачаєте здоров’я в розмірі $s4% від завданої шкоди. Поки ця печатка активна, кожен учасник вашої групи або рейду в межах $407802a1 ярдів отримує ману в розмірі $s2% від шкоди, яку ви отримуєте від цієї печатки.\r\n\r\n\r\nВивільнення енергії цієї Печатки судить ворога, миттєво завдаючи $407803s1% шкоди зброєю ціною здоров’я в розмірі $s4% від завданої шкоди.\r\n\r\nПечатка та Суд цієї здібності отримують переваги від талантів і ефектів, що змінюють Печатку або Суд Печатки праведності.",
        [407800] = "Шкода від Печатки мучеництва також завдає шкоди паладину.",
        [407802] = "Відновлює ману від шкоди, отриманої паладином.",
        [407804] = "$s1% усієї шкоди, яку отримують учасники групи в межах $a1 ярдів, перенаправляється на паладина протягом $d. Шкода, що знижує здоров’я паладина нижче $s2%, перериває ефект і збільшує завдану паладином шкоду та зцілення на $407805s1% протягом $407805d. Божественну жертву не можна використовувати під дією Благословення захисту, Божественного щита або Божественного захисту, а поки вона активна, ці здібності не можуть бути застосовані до вас.",
        [407805] = "Після вашої жертви шкоду та зцілення збільшено.",
        [407811] = "Завдає ворогові та його найближчим союзникам шкоди зброєю плюс $s1, уражаючи до $x1 цілей.",
        [407813] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [407819] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [407821] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [407880] = "Ваша надихаюча присутність періодично розвіює ефекти Страху та Сну з учасників групи поблизу.",
        [407881] = "Ваша надихаюча присутність періодично розвіює ефекти Страху та Сну з учасників групи поблизу.",
        [407973] = "Додаткова атака.",
        [407975] = "Учасники групи в межах $8514a1 ярдів отримують підвищену бойову лють.  Кожне влучення в ближньому бою має $h% шанс надати нападнику додаткову атаку з $s1% додаткової сили атаки. Не діє, якщо учасник групи вже отримує ефект Тотема люті вітру.\r\n",
        [407977] = "Поки ви перебуваєте у Формі кота, Формі ведмедя або Формі лютого ведмедя, учасники групи чи рейду в межах $407975a1 ярдів отримують підвищену бойову лють.  Кожне влучення в ближньому бою має $407975h% шанс надати нападнику додаткову атаку з $407975s1% додаткової сили атаки. Не діє, якщо ціль уже отримує ефект Тотема люті вітру.\r\n",
        [407988] = "$?a768[|CFFFFFFFFRequires Cat Form|R][|CFFFF2020Requires Cat Form|R]\r\nЗавершальний прийом, що збільшує завдану фізичну шкоду на $s2% у Формі кота.  Триває довше за кожне очко серії:\r\n   1 очко  : ${14+$<points>} с\r\n   2 очки: ${19+$<points>} с\r\n   3 очки: ${24+$<points>} с\r\n   4 очки: ${29+$<points>} с\r\n   5 очок: ${34+$<points>} с",
        [407989] = "Завершальний прийом, що збільшує завдану фізичну шкоду на $s1%.  Триває довше за кожне очко серії:\r\n   1 очко  : 14 с\r\n   2 очки: 19 с\r\n   3 очки: 24 с\r\n   4 очки: 29 с\r\n   5 очок: 34 с",
        [407995] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1.",
        [408024] = "Після активації надає вам $408025s1% від максимального запасу здоров’я та збільшує все нефізичне зцілення, яке ви здійснюєте, на $s1% протягом $d. Після завершення ефекту це здоров’я втрачається. Можна використовувати в усіх формах, крім Форми місячного совуха.\r\n\r\nКрім того, щоразу, коли ви ухиляєтеся у Формі ведмедя або Формі лютого ведмедя, ви відновлюєте $417051s2 люті; у Формі кота — $417051s3 енергії; а в будь-якій іншій формі — $417051s4% від максимального запасу мани.",
        [408120] = "Зцілює ціль і її групу на $o1 протягом $d. Учасники групи мають бути в межах $a1 ярдів від цілі. На початку Дике зростання зцілює швидше, а ближче до завершення дії — повільніше.",
        [408124] = "Зцілює ціль на ${$m1/100*7*$<healpower>} протягом $d.  Коли Життєцвіт завершує дію або розвіюється, ціль миттєво зцілюється на ${$m2/100*$<healpower>}, а друїд повертає половину вартості закляття.  Ефект накопичується до $u разів на одній цілі.\r\n",
        [408245] = "Зцілює ціль протягом 7 с.  Коли Життєцвіт завершує дію або розвіюється, ціль миттєво зцілюється.  Ефект накопичується до 3 разів на одній цілі.",
        [408246] = "Відновлює ману, коли Життєцвіт завершується.",
        [408247] = "Зцілює дружню ціль на ${$m1/100*$<healpower>}–${$M1/100*$<healpower>}. Зцілює ще на 20% більше, якщо на цілі діє ваш ефект Омолодження, Відновлення, Життєцвіту або Дикого зростання. Це закляття отримує переваги від усіх ефектів, пов’язаних із Цілющим дотиком або Відновленням, і запускає їх.",
        [408248] = "Ваш Гнів зменшує час застосування наступних $s3 заклять Зоряного вогню на ${$m2/-1000}.2 с. Зберігає до $408255u зарядів. Триває $408255d.",
        [408258] = "Критичні удари ваших неперіодичних заклять, що завдають шкоди, дозволяють $m1% відновлення мани тривати під час застосування заклять протягом $408261d.",
        [408261] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [408307] = "Збільшує вашу силу зцілення на $s2% від шкоди заклять сил природи протягом $d.",
        [408309] = "Збільшує шкоду заклять на $s2% від різниці між вашою силою зцілення та шкодою заклять. Триває $d.",
        [408339] = "Закляття Тотем вогняної нови замінюється на Вогняну нову, яка змушує ваш поточний тотем вогню завдати шкоди у своєму місці.",
        [408341] = "Миттєво завдає ворогам у межах $8349a1 ярдів від вашого активного тотема вогню $8349s1 шкоди від вогню.",
        [408342] = "Миттєво завдає ворогам у межах $8502a1 ярдів від вашого активного тотема вогню $8502s1 шкоди від вогню.",
        [408343] = "Миттєво завдає ворогам у межах $8503a1 ярдів від вашого активного тотема вогню $8503s1 шкоди від вогню.",
        [408344] = "Миттєво завдає ворогам у межах $11306a1 ярдів від вашого активного тотема вогню $11306s1 шкоди від вогню.",
        [408345] = "Миттєво завдає ворогам у межах $11307a1 ярдів від вашого активного тотема вогню $11307s1 шкоди від вогню.",
        [408438] = "Надає вашим закляттям Блискавка та Ланцюгова блискавка $m1% шанс без додаткових витрат застосувати по тій самій цілі друге подібне закляття, що завдає половину шкоди й не створює загрози.\r\n",
        [408439] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408440] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408441] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408442] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408443] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408472] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408473] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408474] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408475] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408477] = "Випускає в ціль блискавку, що завдає $s1 шкоди від сил природи.",
        [408479] = "Жбурляє у ворога блискавку, завдаючи $s1 шкоди від сил природи, після чого вона перескакує на додаткових ворогів поблизу.  Кожен перехід зменшує шкоду на 30%.  Загалом вражає $x1 цілей.",
        [408481] = "Жбурляє у ворога блискавку, завдаючи $s1 шкоди від сил природи, після чого вона перескакує на додаткових ворогів поблизу.  Кожен перехід зменшує шкоду на 30%.  Загалом вражає $x1 цілей.",
        [408482] = "Жбурляє у ворога блискавку, завдаючи $s1 шкоди від сил природи, після чого вона перескакує на додаткових ворогів поблизу.  Кожен перехід зменшує шкоду на 30%.  Загалом вражає $x1 цілей.",
        [408484] = "Жбурляє у ворога блискавку, завдаючи $s1 шкоди від сил природи, після чого вона перескакує на додаткових ворогів поблизу.  Кожен перехід зменшує шкоду на 30%.  Загалом вражає $x1 цілей.",
        [408490] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $s2% більше шкоди.",
        [408491] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $408490s2% більше шкоди.",
        [408496] = "Під час бою з двома видами зброї збільшує шанс влучення закляттями й атаками ближнього бою на $s1%; Буревій тепер ударяє обома видами зброї, а шкода зброї в лівій руці збільшується на $s3%.",
        [408498] = "Коли ви завдаєте шкоди атакою ближнього бою, маєте шанс зменшити час застосування та витрати мани вашої наступної Блискавки на $m1%. Накопичується до $s3 разів. Триває $408505d.",
        [408505] = "Зменшує час застосування та витрати мани вашої наступної Блискавки.",
        [408507] = "Заряджає зброю в лівій руці лавою, миттєво завдаючи $s1% шкоди зброєю в лівій руці. Шкода збільшується на $s2%, якщо зброю в лівій руці зачаровано Язиком полум’я.",
        [408510] = "Заклинача оточують $n водяних сфер. Коли заклинача вражає закляття, атака ближнього або дальнього бою чи одне з його зцілювальних заклять завдає критичного ефекту, заклинач відновлює $408511s1% від максимального запасу мани, витрачаючи одну водяну сферу. Лише одна сфера може активуватися раз на кілька секунд.  Триває $d.\r\n\r\nОдночасно на шамані може діяти лише один Щит стихій.",
        [408511] = "Відновлює ману після отримання удару, поки активний Водяний щит.",
        [408514] = "Захищає ціль земляним щитом, зменшуючи втрату часу застосування або підтримання заклять від шкоди на $s2% і змушуючи атаки зцілювати захищену ціль на ${$m1*$<healpower>/100}.  Ефект може спрацьовувати лише раз на кілька секунд.  $n зарядів. Триває $d.  Земний щит можна накласти лише на одну ціль одночасно.\r\n",
        [408519] = "Зцілення Земним щитом.",
        [408521] = "Зцілює дружню ціль на $s1, додатково на $o2 протягом $d і збільшує ефективність Ланцюгового зцілення, застосованого безпосередньо до цієї цілі, на $s3%.",
        [408524] = "Щоразу, коли ви блокуєте атаку, відновлюєте ману в розмірі $408525s2% від максимального запасу та отримуєте броню в розмірі $408525s1% від броні вашого щита, накопичуючи ефект до $s3 разів. Крім того, ваш шанс блокування завжди збільшено на $s1%, а величину блокування — на $s2%.\r\n\r\nКрім того, щоразу, коли ви використовуєте здібність Шоку, отримуєте $460200s2 шкоди заклять за кожне очко навички захисту понад ${$PL*5}. Триває $460171d.\r\n",
        [408525] = "Збільшує броню на $s1% від показника броні вашого щита протягом $d, накопичуючись до $u разів.",
        [408531] = "Поки Каменебійна зброя активна на зброї в основній руці й у вас споряджено щит, ви створюєте на $408680s1% більше загрози, маєте на $408680s2% більше здоров’я, отримуєте на $408680s4% менше шкоди, маєте на $408680s5% менший шанс отримати критичний удар атакою ближнього бою, а Земний шок провокує цілі атакувати вас і має окремий час відновлення від інших заклять Шоку, але його дальність зменшується до дистанції ближнього бою. Водночас дальність ваших заклять Блискавка, Ланцюгова блискавка, Ланцюгове зцілення, Хвиля зцілення та Викид лави зменшується на $408680s13 ярдів. ",
        [408680] = "Поки Каменебійна зброя активна на зброї в основній руці, ви створюєте на $s1% більше загрози, маєте на $s2% більше здоров’я, отримуєте на $s4% менше шкоди, маєте на $s5% менший шанс отримати критичний удар атакою ближнього бою, а Земний шок провокує цілі атакувати вас і має окремий час відновлення від інших заклять Шоку.\r\n",
        [408681] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408683] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408685] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408687] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408688] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408689] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408690] = "Миттєво вражає ціль оглушливою силою, завдаючи $s1 шкоди від сил природи.  Також перериває застосування закляття й не дозволяє застосовувати закляття цієї школи протягом $d.  Створює велику кількість загрози та провокує ціль.",
        [408693] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [408696] = "Наповнює ціль духом альфа-вовка, збільшуючи всю створювану нею загрозу на $s1% протягом $d. Лише 1 ціль. Якщо застосувати не на себе, шаман також отримує Вірну бету, що збільшує завдану фізичну шкоду на $443320s1% і зменшує всю створювану загрозу на $443320s2% протягом $d. На цілі не можуть одночасно діяти Дух альфи та Вірна бета.",
        [408699] = "Ваші влучення Засідкою та Ударом у спину виводять ціль з рівноваги, збільшуючи час між її атаками ближнього бою на $408699s1% і зменшуючи швидкість руху на $408699s2% протягом $408699d.",
        [408700] = "Ваші влучення Засідкою та Ударом у спину виводять ціль з рівноваги, збільшуючи час між її атаками ближнього бою на $408699s1% і зменшуючи швидкість руху на $408699s2% протягом $408699d.",
        [408755] = "Пожертвуйте свою кров, щоб наповнити артефакт силою.",
        [409073] = "Ваші атаки ближнього бою додають ${$409073m1/10} люті.",
        [409163] = "Вигравіювати на поясі руну \"Зосереджена лють\":",
        [409239] = "Миттєво розкидає ножі у цілі в межах $a1 м, завдаючи $s1% від шкоди зброї.",
        [409240] = "Миттєво розкидає ножі у цілі в межах $a1 м, завдаючи ${$m1*1.5}% від шкоди кинджалів або $s1% від шкоди іншої зброї.",
        [409368] = "Шкода і здоров'я вашого вихованця збільшуються на $s1%, а відновлення концентрації - на $s3%. Крім того, \"Рик\" вашого вихованця тепер також провокує ціль, змушуючи її атакувати його протягом 3 секунд.",
        [409372] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [409428] = "Збільшує шанс критичного удару на 5% і зменшує витрати мани ваших здібностей \"Постріл\" на 25%.",
        [409593] = "Ви намагаєтеся добити поранену ціль точним пострілом, завдаючи їй $s2% шкоди від зброї плюс ${$m1/100*$m2/100*$<damagepower>}. \"Вбивчий постріл\" не має мінімальної дальності застосування. При застосуванні проти ворогів, що мають не більше 20% здоров'я, його відновленя завершується.",
        [409687] = "Збільшує шкоду від зброї в лівій руці на $s1%, а \"Удар раптора\" тепер б'є зброєю з обох рук.",
        [409693] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [409750] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
