        [410412] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [411115] = "Зменшує шанс отримати критичний удар в ближньому бою на 6% і зменшує всю отриману шкоду на 10%. Отримана шкода зменшується ще на 10%, якщо ви перебуваєте у подобі ведмедя або жахливого ведмедя.",
        [411128] = "Розлого б'є ворогів поблизу, завдаючи $s1% шкоди від зброї та збільшує комбінацію на один прийом",
        [411622] = "Ваша здібність \"Приручення звіра\" також діє на лугових собачок (як на улюбленців-компаньйонів)",
        [411631] = "Починає приручення звіра, щоб зробити його вашим супутником.  Поки ви зосереджені на прирученні протягом $d, ваша броня зменшена на $s3%.  Якщо ви з будь-якої причини втратите увагу звіра, приручення провалиться.  Після приручення звір буде дуже нещасним і нелояльним.  Негайно нагодуйте вихованця, щоб підняти йому настрій.",
        [411774] = "Атакує ворогів поблизу вихором сталі протягом $d. і завдає звичайної шкоди плюс $15576s1.",
        [411959] = "Вселяє у ворога страх, змушуючи його тікати в жаху протягом $d. Одночасно можна налякати лише 1 ціль.",
        [411995] = "Завдає $s1 шкоди від тіні кожні $t1 с.",
        [412020] = "Зцілення з часом.",
        [412096] = "Завершальний рух, що вражає всіх ворогів в межах $a2 м, спричиняючи кровотечу. Тривалість залежить від довжини комбінації.\n\n  1 прийом: ${$AP*0.30} шкоди за 4 c\n  2 прийоми: ${$AP*0.45} шкоди за 6 c\n  3 прийоми: ${$AP*0.60} шкоди за 8 c\n  4 прийоми: ${$AP*0.75} шкоди за 10 c\n  5 прийомів: ${$AP*0.90} шкоди за 12 c\n\nБагряний вихор взаємодіє з усіма талантоми і ефектами, що й \"Розрив\".",
        [412113] = "Знімає $m1 прокляття та $m2 негативний магічний ефект з дружньої цілі.",
        [412115] = "Ваші заклинання \"Щит мани\", \"Крижаний оберіг\" і \"Вогняний оберіг\" тепер можна застосовувати на будь-яку дружню ціль, вони поглинають на $s1% більше шкоди, а \"Щит мани\" витрачає на $s2% менше мани на поглинання шкоди. Крім того, ваше \"Зняття малого прокляття\" замінюється на \"Зняття великого прокляття\".",
        [412116] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412118] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412120] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412121] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412122] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412123] = "Поглинає $s1 одиниць фізичної шкоди дружній цілі, натомість витрачаючи ману. Висушує $s2 мани у мага за кожну одиницю шкоди. Триває $d хв.",
        [412214] = "Поглинає $s1 шкоди від вогню.  Триває $d.",
        [412218] = "Поглинає $s1 шкоди від вогню.  Триває $d.",
        [412230] = "Поглинає $s1 шкоди від вогню.  Триває $d.",
        [412231] = "Поглинає $s1 шкоди від вогню.  Триває $d.",
        [412232] = "Поглинає $s1 шкоди від вогню.  Триває $d.",
        [412286] = "Збільшує ймовірність критичного удару всіх заклинань на $s1%, але ваші неперіодичні критичні удари заклинаннями тепер мають додаткову вартість мани в розмірі $s2% від вашого базового запасу мани.",
        [412322] = "Збільшує додаткову шкоду від критичних ударів всіх заклинань на $s1%.",
        [412324] = "Ви завдаєте на $s1% більше шкоди, поки маєте більше $s2% мани. Якщо у вас менше $s3% мани, вона продовжує відновлюватись під час вимови заклять зі швидкістю $s4% від звичайної.",
        [412325] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [412326] = "Збільшує всю шкоду заклять на $s1%.",
        [412437] = "Випускає у ворога стрілу, яка завдає від ${$m1/100*$<power>} до ${$M1/100*$<power>} шкоди від криги.",
        [412507] = "\"Розрив\" тепер можна застосовувати в стійці берсерка, його шкоду збільшено на $s2% і щоразу, коли його ефект завдає шкоди, ціль отримує додаткову шкоду в розмірі $s3% від вашої сили атаки.",
        [412526] = "Завдає ворогові шкоди від тіні й зменшує швидкість його руху протягом $d.",
        [412538] = "Завдає шкоду від вогню кожні $t1 с.",
        [412545] = "Завдає шкоду від вогню кожні $t с.",
        [412689] = "\"Висмоктування життя\", \"Висмоктування душі\", \"Тіньова стріла\", \"Тіньове розсічення\", \"Палючий біль\", \"Спалення\" і \"Мара\" відновлюють час дії \"Пошесті\" на цілі до максимальної тривалості.",
        [412727] = "Збільшує шанс критичного удару атак ближнього бою та заклинань для вас і вашого прислужника на $m1%.",
        [412732] = "Збільшує шкоду і зцілення від заклинань на величину, що дорівнює $s1% від загальної витривалості та інтелекту вашого прислужника.",
        [412789] = "Змушує всіх ворогів поблизу зосередити атаки на вас протягом $d.",
        [413248] = "Зцілення за допомогою \"Швидкого зцілення\" зменшує час вимови наступного \"Малого зцілення\", \"Зцілення\", \"Великого зцілення\" або \"Молитви зцілення\" на 20% протягом 20 с. Ефект накопичується до 3 разів.",
        [413251] = "Закляття \"Вибух розуму\", \"Пронизування розуму\" та \"Муки розуму\" поновлюють тривалість одного з ваших ефектів \"Слово тіні: Біль\", \"Чума Порожнечі\" чи \"Дотик вампіра\" на цілі до максимальної тривалості. Завжди оновлює ефект з найменшою тривалістю.",
        [413301] = "Вбивство ворога, що приносить досвід або честь, додає ${$413302s1/10} люті.",
        [413380] = "\"Героїчний удар\", \"Кровожерливість\" та \"Вихор\" з ймовірністю 30% дозволяють використати наступне \"Розтрощення\" протягом 15 секунд миттєво, з обох рук і без витрат люті.",
        [413446] = "Автоматична стрільба з лука по цілі, що діє до скасування.",
        [414621] = "Вдарити ціль по черепу, перериваючи вимову заклинань і унеможливлюючи вимову заклять тієї ж школи протягом 2 с.",
        [414677] = "Коли ви зцілюєте ціль критичним ефектом будь-якого неперіодичного заклинання, ви саджаєте в неї \"Зерно життя\" на $s1% від ефекту зцілення. \"Зерно життя\" розквітне, коли ціль буде атакована або зцілена. Триває 15 секунд.",
        [414683] = "Зцілює дружню ціль на $s1.",
        [414692] = "Отримати здібність \"Сонячний вогонь\" і замінити \"Місячний вогонь\" на \"Сонячний вогонь\" (ведмідь) або \"Сонячний вогонь\" (кіт) в подобі ведмедя, кота та жахливого ведмедя. Це закляття взаємодіє з усіма ефектами, що й \"Місячний вогонь\".",
        [414719] = "Деякі ваші закляття і здібності збільшують тривалість ефектів шкоди і зцілення, що діють на ціль:\n\n\"Зоряний вогонь\" продовжує дію \"Місячного вогню\" на $s1 с.\n\"Гнів\" подовжує дію \"Сонячного вогню\" на $s2 с.\n\"Розростання\" продовжує дію \"Омолодження\" на $s3 с.\n\"Шматування\" продовжує дію \"Розірвання\" на $s4 с.\n\nКожен ефект можна продовжити лише до початкової тривалості дії.",
        [414799] = "Зменшує витрати мани на \"Гнів\" на 100%, і щоразу, коли ви завдаєте шкоди за допомогою \"Гніву\", з ймовірністю 12% наступне використання \"Цілющого дотику\" впродовж 15 с буде миттєвим і доступним в будь-якій подобі. Дозволяє вимовляти \"Гнів\" у подобі дерева життя.",
        [414900] = "Завдає $s1 шкоди від вогню кожні $t1 с.",
        [415076] = "Екзорцизм тепер можна застосувати на будь-яку ціль зі збільшеним на 100% шансом критичного удару по невмерлих та демонах.",
        [415096] = "Ефективність \"Ланцюгового зцілення\" зменшується лише на $s1% за кожен перехід, а ефективність \"Ланцюгової блискавки\" зменшується лише на $s2% за кожен перехід. Окрім того, ці закляття діють на ще одну ціль.",
        [415100] = "Щоразу, коли ви завдаєте шкоди \"Вогняним шоком\", з ймовірністю 5% час відновлення \"Виверження лави\" і \"Ланцюгової блискавки\" завершується і ви можете вимовити наступне \"Виверження лави\" або \"Ланцюгову блискавку\" протягом 10 секунд миттєво. Щоразу, коли ви зцілюєте \"Бистриною\", з ймовірністю 5% ви можете вимовити наступне \"Ланцюгове зцілення\" протягом 10 секунд миттєво. Крім того, кожні 5 секунд ви відновлюєте ману в обсязі 15% від вашого інтелекту.",
        [415231] = "Ваш \"Вогняний шок\" тепер вражає до $s1 цілей, діє на ${$m5/1000} с довше та завдає на $s3% більше шкоди. Окрім того, поки на вашу зброю в правій руці діє \"Зброя язика полум'я\", ваша шкода заклять збільшується на $s7% від показника інтелекту.",
        [415233] = "Перетворює шамана на примарного вовка, збільшуючи швидкість руху на $s2% та зменшуючи отриману шкоду на $s3%.",
        [415242] = "Зцілює 5 членам групи чи рейду в радіусі $a1 м навколо цілі ${$<healpower>*$m1/100} здоров'я.",
        [415292] = "Зцілює ${$m1/100*$<healpower>*4} здоров'я протягом $d с.",
        [415326] = "Ви і ваш вихованець одночасно завдаєте $s2% шкоди в ближньому бою. Після цього ваші здібності \"Укус мангусти\" та \"Удар раптора\" завдають на $s3% більше шкоди, ефект накопичується до $u разів. \"Удар раптора\" має $s4% шанс скинути відновлення \"Флангового удару\".",
        [415335] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415336] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415337] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415338] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415340] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415341] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415342] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415343] = "Потужна атака зі збільшеною на $s1 шкодою ближнього бою.",
        [415352] = "\"Удар раптора\" тепер застосовується миттєво, а \"Укус мангусти\" та \"Удар раптора\" з ймовірністю $s3% завершують відновлення \"Укусу мангусти\" та \"Удару раптора\".",
        [415370] = "Ви завдаєте на $s2% більше шкоди всіма атаками, поки у вас немає активного вихованця.",
        [415407] = "Наступна здібність \"Постріл\" завдає на 20% більше шкоди.",
        [415413] = "Щоразу, коли ви ставите пастку, ваша наступна здібність \"Постріл\" (окрім \"Дезорієнтуючого пострілу\") протягом 20 секунд не витрачає ману і не вимагає часу на відновлення.",
        [415423] = "Мисливець переймає аспекти гадюки, через що атаки дальнього та ближнього бою відновлюють ману, але шкода зменшується на $s2%. Крім того, ви відновлюєте $s1% від максимального запасу мани кожні $t секунди. Кількість отриманої мани залежить від швидкості вашої зброї. Одночасно може бути активним лише один аспект.",
        [415428] = "Збільшує ваш шанс ухилення на $s1% і шанс ухилення вашого вихованця на $s2%. Крім того, зменшує час відновлення \"Флангового удару\" на $s3%.",
        [415449] = "Надягніть пояс з руною, щоб активувати цю здібність.",
        [415450] = "Надягніть чоботи з руною, щоб активувати цю здібність.",
