        [417066] = "Зцілює ціль на $o1 протягом $d.",
        [417068] = "Зцілює ціль на $o1 протягом $d.",
        [417123] = "Тепер ваше \"Омолодження\" та \"Розростання\" може бути активне на цілі, яка знаходиться під ефектом \"Омолодження\" чи \"Розростання\" інших друїдів.",
        [417135] = "Збільшує шкоду від \"Урагану\" на $s1%, він більше не має часу відновлення, а витрати мани на його вимову зменшуються на $s4%.",
        [417145] = "Завдавши удару здібністю \"Розірвати\", \"Розмах\" або \"Терзання\", ви отримуєте ${$446699m1/10} люті та з ймовірністю $h% завершуєте відновлення \"Нівечення\" (ведмідь). Завдавши удару здібністю \"Нівечення\" (кіт) або \"Шматування\", ви з ймовірністю $s1% завершуєте відновлення \"Люті тигра\".",
        [417148] = "Зцілює всім учасникам групи в межах $a1 м від цілі ${$<healpower>*$m1/100} здоров'я.",
        [417159] = "Миттєво зцілює вас на 30% від максимального запасу здоров'я. Можна використовувати в будь-якій подобі.",
        [417315] = "Викликає Собоза.",
        [417345] = "Надягніть шолом з руною, щоб активувати цю здібність.",
        [417346] = "Надягніть браслети з руною, щоб активувати цю здібність.",
        [417347] = "Надягніть плащ з руною, щоб активувати цю здібність.",
        [417348] = "Надягніть наплічники з руною, щоб активувати цю здібність.",
        [417433] = "Викопує скарб у позначеному місці.",
        [417434] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [417440] = "Вражає всіх ворогів поблизу, завдаючи ${$m1*$<damagepower>/100+0.092*$AP} шкоди від кровотечі і додатково ${$417441m1*$<damagepower>/100*5+0.125*$AP} шкоди від кровотечі протягом 15 с. При застосуванні з ведмежої подоби цей ефект може накопичуватися до 3 разів.",
        [417448] = "Вражає всіх ворогів поблизу, завдаючи ${$m1*$<damagepower>/100+0.104*$AP} шкоди від кровотечі і додатково ${$m2*$<damagepower>/100*5+0.0661*5*$AP} шкоди від кровотечі протягом 15 с. Збільшує довжину комбінації на 1 прийом.",
        [417627] = "Випити на кладовищі Танаріса.",
        [418065] = "Викликає Собоза.",
        [418236] = "Ваша здібність \"Приручення звіра\" також діє на кроликів (як на улюбленців-компаньйонів)",
        [418334] = "Повертається до звичайної форми.",
        [418599] = "Викопує скарб у позначеному місці.",
        [418600] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [419417] = "Повертає вас до $z. Поговоріть з господарем заїзду в іншому місці, щоб змінити точку повернення.",
        [420526] = "Завдає ворогові шкоди від криги та зменшує швидкість його руху на $d.",
        [420536] = "Переводить заклинача в режим непомітності на $d.",
        [420794] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [420998] = "Завдає $s1 шкоди від святості будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура діє до скасування.",
        [421248] = "Заклинача оточують тіні.  Коли заклинача вражає закляття, атака ближнього або дальнього бою, нападник отримує $28377s1 шкоди від тіні.  Нападник може отримати цю шкоду лише раз на кілька секунд.  Ця шкода не створює загрози.  $n зарядів.  Триває $d.",
        [421311] = "Ваша здібність \"Приручення звіра\" також діє на оленів (як на улюбленців-компаньйонів)",
        [421424] = "Викопує скарб у позначеному місці.",
        [421425] = "Поєднайте з 3 іншими частинами, щоб скласти повну мапу.",
        [421596] = "Розшифруйте нотатки закляття за допомогою Оберега розуміння, щоб вивчити нове закляття гравіювання.",
        [422621] = "Зменшує витрати ресурсів закляттями та здібностями на $s1%.",
        [423002] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [423298] = "Збільшує швидкість плавання на $s1%.",
        [423474] = "Збільшує шкоду від \"Вогняної стріли\" вашого біса на $s1.",
        [424035] = "Дозволяє медитувати над таємницями Світла у святих місцях.",
        [424036] = "Дозволяє медитувати над таємницями Елуни біля місячних колодязів.",
        [424037] = "Дозволяє медитувати над таємницями лоа на вівтарях.",
        [424041] = "Дозволяє медитувати над таємницями невмерлості на кладовищах.",
        [424715] = "Отримати здібність \"Зоряний сплеск\":",
        [424718] = "Вигравіювати на штанях руну \"Зоряний сплеск\":",
        [424759] = "Отримати здібність \"Берсерк\":",
        [424760] = "Вигравіювати на поясі руну \"Берсерк\":",
        [424762] = "Отримати здібність \"Король джунглів\":",
        [424765] = "Вигравіювати на чоботях руну \"Король джунглів\":",
        [424785] = "Ви жорстоко рубаєте ворога, завдаючи $s2% шкоди від зброї, і викликаєте в нього кровотечу, що завдає ${$AP*$m4/100} шкоди кожні $t4 с протягом $d секунд, і ефект якої накопичується до $u разів. Кожен ефект також збільшує шкоду від вашого \"Удару шаблею\" та \"Підступного удару\" на $s5%. Збільшує довжину комбінації на 1 прийом.\n\n\"Удар шаблею\" взаємодіє з усіма талантами та ефектами, що й \"Підступний удар\".",
        [424799] = "Миттєва атака зброєю в лівій руці, що завдає шкоди від зброї та з ймовірністю 100% отруює ціль нанесеною на зброю отрутою. Повільна зброя вимагає більше витрат енергії. Збільшує довжину комбінації на $s2 прийом.\n\n\"Укол\" взаємодіє з усіма талантами та ефектами, що й \"Підступний удар\".",
        [424800] = "Миттєва атака зброєю в лівій руці, що з ймовірністю 100% отруює ціль нанесеною на зброю отрутою. Повільна зброя вимагає більше витрат енергії. Збільшує довжину комбінації на $s2 прийом.",
        [424979] = "Отримати здібність \"Удар шаблею\":",
        [424980] = "Отримати здібність \"Головоріз\":",
        [424982] = "Отримати здібність \"Удар лівицею\":",
        [424983] = "Отримати здібність \"Різанина з тіні\":",
        [424984] = "Вигравіювати на рукавицях руну \"Удар шаблею\":",
        [424988] = "Вигравіювати на рукавицях руну \"Головоріз\":",
        [424990] = "Вигравіювати на рукавицях руну \"Удар лівицею\":",
        [424992] = "Вигравіювати на нагруднику руну \"Різанина з тіні\":",
        [425012] = "Кидок зброї з лівої руки, що завдає шкоди зброї та з ймовірністю 100% викликає спрацювання нанесеної на неї отрути. Збільшує довжину комбінації на $s2 прийом. Відновлює $s3 енергії за кожен ефект смертельної отрути на цілі.\n\n\"Отруєний ніж\" взаємодіє з усіма талантами та ефектами, що й \"Підступний удар\".",
        [425013] = "Кидок зброї з лівої руки, що завдає шкоди зброї та з ймовірністю 100% викликає спрацювання нанесеної на неї отрути. Збільшує довжину комбінації на $s2 прийом.\n\n\"Отруєний ніж\" взаємодіє з усіма талантами та ефектами, що й \"Підступний удар\".",
        [425096] = "Атаки, здійснені з непомітності та протягом 6 секунд після виходу з неї, завдають на $s1% більше шкоди.",
        [425098] = "Атаки, здійснені з непомітності та протягом 6 секунд після виходу з неї, завдають на $s1% більше шкоди.",
