        [427076] = "Вигравіювати на шоломі руну \"Смак крові\":",
        [427078] = "Вигравіювати на шоломі руну \"Пильність\":",
        [427080] = "Вигравіювати на шоломі руну \"Майстерність володіння щитом\":",
        [427081] = "Вигравіювати на браслетах руну \"Шаленство\":",
        [427082] = "Вигравіювати на браслетах руну \"Мечем і щитом\":",
        [427084] = "Вигравіювати на браслетах руну \"Погром\":",
        [427712] = "Періодична шкода від ваших здібностей \"Пошесть\", \"Нестабільна химородь\", \"Прокляття агонії\", \"Жертовний вогонь\", \"Прокляття приречення\" та \"Витягування життя\" тепер може бути критичною.",
        [427726] = "Обпалює ворогів поблизу, завдаючи ${$<power>*$427725m1/100} шкоди щоразу, коли вас атакують в ближньому бою (але не частіше, ніж раз на секунду), зменшує всю отриману магічну шкоду на $s2% та збільшує вашу шкоду від вогню на $s3%. Діє до скасування.",
        [427733] = "Викликає вартового скверни, підкореного чорнокнижникові.\n\nВартовий скверни взаємодіє з усіма талантами та ефектами, що й ваші інші демони.",
        [427742] = "Провокує ціль, що збільшує ймовірність того, що вона атакуватиме вартового скверни.",
        [427744] = "Розмашиста атака, яка вражає ціль вартового скверни та одного її союзника, завдаючи збілььшену на $s1 шкоду від зброї.",
        [427774] = "Ви відчуваєте потойбічний тиск нищівної сили.",
        [428717] = "\"Вибуховий постріл\" та пастки завдають на $s1% більше шкоди. Окрім того, первинна шкода \"Вибухової пастки\" та періодична шкода \"Обпалюючої пастки\" збільшуються на $s3% від вашої сили атаки ближнього чи дальнього бою.",
        [428738] = "Збільшення сили вашого \"Щита мани\", \"Крижаного оберегу\" і \"Вогняного оберегу\" на $s1%, а також зменшення витрат мани на поглинання шкоди \"Щитом мани\" на $s2%.",
        [428861] = "Телепортує на місце використання останнього \"Блиму\", і завершує його відновлення. Може бути використано протягом 10 секунд після використання \"Блиму\".",
        [428863] = "Отримати здібність \"Заміщення\":",
        [429133] = "Збільшує запобігання шкоді вашого \"Благословення прихистку\" на $s1% і збільшує його шкоду на $s2% від вашого показника блокування щитом.",
        [429139] = "\"Освячення\" тепер може завдавати критичної шкоди, а заклинання \"Екзорцизм\", \"Священний шок\", \"Сонячне сяйво\", \"Священний гнів\" і \"Освячення\" отримують збільшену ймовірність завдання критичної шкоди на значення, що дорівнює вашій ймовірності завдання критичного удару в ближньому бою.",
        [429151] = "Кидає у ворога молот, що завдає від ${$m1*$<damagepower>+0.15*$SPH+0.15*$AP} до ${$M1*$<damagepower>+0.15*$SPH+0.15*$AP} шкоди святістю. Можна застосовувати лише проти ворогів, у яких не більше 20% здоров'я.",
        [429152] = "\"Молот гніву\" тепер вимовляється миттєво і його відновлення завершується щоразу, коли він завдає шкоди ворогу, у якого менше $s1% здоров'я.",
        [429242] = "Вигравіювати на браслетах руну \"Милість Світла\":",
        [429243] = "Отримати здібність \"Милість Світла\":",
        [429245] = "Отримати здібність \"Покращений прихисток\":",
        [429247] = "Вигравіювати на шоломі руну \"Покращений прихисток\":",
        [429248] = "Отримати здібність \"Гнів\":",
        [429249] = "Вигравіювати на шоломі руну \"Гнів\":",
        [429250] = "Отримати здібність \"Фанатизм\":",
        [429251] = "Вигравіювати на шоломі руну \"Фанатизм\":",
        [429254] = "Отримати здібність \"Сила очищення\":",
        [429255] = "Вигравіювати на браслетах руну \"Сила очищення\":",
        [429259] = "Отримати здібність \"Покращений молот гніву\":",
        [429261] = "Вигравіювати на браслетах руну \"Покращений молот гніву\":",
        [429283] = "Отримати здібність \"Пандемія\":",
        [429303] = "Отримати здібність \"Глибока заморозка\":",
        [429304] = "Вигравіювати на шоломі руну \"Глибока заморозка\":",
        [429305] = "Отримати здібність \"Темпоральна аномалія\":",
        [429306] = "Вигравіювати на шоломі руну \"Темпоральна аномалія\":",
        [429307] = "Отримати здібність \"Розплавлений обладунок\":",
        [429308] = "Вигравіювати на браслетах руну \"Розплавлений обладунок\":",
        [429309] = "Вигравіювати на браслетах руну \"Заміщення\":",
        [429310] = "Отримати здібність \"Стріла руйнівного полум'я\":",
        [429311] = "Вигравіювати на браслетах руну \"Стріла руйнівного полум'я\":",
        [429434] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [429687] = "Підкорює гуманоїда до $s1 рівня на $d.",
        [429688] = "Підкоряє гуманоїда-ворога до $s1 рівня на $d, але збільшує час між його атаками на $s2%.",
        [429748] = "Замінює здібність \"Героїчний удар\" на \"Швидкий удар\":",
        [429765] = "Безрозсудна миттєва атака дворучною зброєю, що завдає від ${$AP*$m1/100} до ${$AP*$M1/100} фізичної шкоди. Ця здібність отримує бонус від усіх ефектів, пов'язаних з \"Героїчним ударом\", і активує їх.",
        [429820] = "Завдає ворогам у вибраній області $s1 шкоди від таємної магії кожні $t1 с протягом $d.",
        [429821] = "Випускає у ворога палаючу стрілу, завдаючи шкоди зброї плюс $s1. Уся завдана шкода належить до школи вогню.",
        [429822] = "Завдає звичайної шкоди ворогові та його найближчим союзникам, вражаючи до $x1 цілей.",
        [429823] = "Завдає ворогові $s2 шкоди від таємної магії, а потім додатково $s1 шкоди кожні $t1 с протягом $d.",
        [429825] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній наступній цілі більше шкоди від сил природи.",
        [429827] = "Миттєво жбурляє у ворога блискавку, завдаючи шкоди від сил природи.",
        [429856] = "Викликати тренувального ночезуба стражів. Можна використовувати лише в Ясенедолі.",
        [429857] = "Викликати тренувального вовка вершників. Можна використовувати лише в Ясенедолі.",
        [429863] = "Збільшує шанс влучення на ${$s1}.1%.",
        [430318] = "Повертає мертвого гравця до життя з $s1% здоров’я та мани.  Не можна використати в бою.",
        [430723] = "Завдає ворогові фізичної шкоди кожні $t1 с. протягом $d.",
        [430947] = "Збільшення ймовірності завдання удару закляттями на 3%, ймовірності завдання кричного удару в ближньому та дальньому бою на 2%, сили атаки на 20, шкоди заклять на 25, а швидкості руху — на 20%. Триває 120 хвилин.",
        [430948] = "Відновлює $s1 мани кожні $t1 с.",
        [430949] = "Збільшує ваш шанс завдання удару заклинаннями на $s1%.",
        [430952] = "Збільшує шанс критичного удару закляттями на ${$s1}.1%.",
        [431046] = "Під час використання дворучної зброї, ваша швидкість атаки збільшується на $s1%.",
        [431111] = "Збільшення ймовірності завдання удару закляттями на 3%, ймовірності завдання кричного удару в ближньому та дальньому бою на 2%, сили атаки на 20, шкоди заклять на 25, а швидкості руху — на 20%. Триває 120 хвилин.",
        [431388] = "Вашу \"Дубову шкіру\" тепер можна застосовувати на союзників з будь-якої подоби і вона більше не зменшує швидкість атак чи вимови заклять.",
        [431446] = "Отримати здібність \"Кривавість\":",
        [431447] = "Вигравіювати на шоломі руну \"Кривавість\":",
