        [446806] = "Зачаклувати себе, щоб вас важче було виявити у Затонулому храмі.",
        [446888] = "Шкоду, отриману під час виконання випробування тотема, збільшено на $s1%.",
        [446912] = "Перехід в іншу область, охоплену кошмаром.",
        [447238] = "Завдає $s1 шкоди ворогам у конусі позаду заклинача й відкидає їх назад.",
        [447255] = "+$s1 до сили атаки проти драконідів.",
        [447274] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [447546] = "Завдає ворогові шкоди від вогню.",
        [447547] = "Обрушує стовп полум’я, що обпалює всіх ворогів у вибраній ділянці та завдає додаткової шкоди кожні $t2 с. протягом $d.",
        [447548] = "Завдає ворогам в області шкоди від сил природи протягом $d, сповільнюючи їхній рух на $s2% і збільшуючи час між їхніми атаками на $s3%.",
        [447549] = "Жреця оточує антимагічна енергія.  Кожне успішно застосоване проти жерця закляття спалює $19270s1 мани нападника, завдаючи 1 шкоди від тіні за кожну спалену одиницю мани.  Триває $d.",
        [447563] = "Засліплює ціль, змушуючи її дезорієнтовано блукати до $d.  Будь-яка завдана шкода знімає ефект.",
        [447581] = "Gloom",
        [447586] = "Прикликає $s1 $lTreant Ally:Treant Allies; супроводжувати заклинача, доки їх не відкличуть.",
        [447587] = "Прикликає $s1 $lForce of Nature:Forces of Nature; на допомогу заклиначеві в бою на $d.",
        [447589] = "Знемовлює ворогів поблизу, не дозволяючи їм застосовувати заклинання протягом $d.",
        [447891] = "Приголомшує ворога, позбавляючи його можливості рухатися чи атакувати протягом $d.",
        [448107] = "Збільшує отримувану ворогами поблизу фізичну шкоду на $s1 протягом $d.",
        [448323] = "Прикликає $s1 $lFire Elemental:Fire Elementals; супроводжувати заклинача, доки їх не відкличуть.",
        [448572] = "Присипляє ворожу ціль на час до $d.  Будь-яка завдана шкода пробуджує ціль.  Одночасно може спати лише одна ціль.",
        [448614] = "Прикинутися кущем, з будь-якої причини.",
        [448618] = "Знайти застосування всім тим порожнім ящикам з-під припасів.",
        [448686] = "Збільшує шкоду вашого наступного заклинання спеціалізації \"Химородь\", що не вимагає промовляння, на $s1%.",
        [448707] = "Відкидає ворогів поблизу.",
        [448828] = "Знерухомлює заклинача, але збільшує швидкість його атаки на $s2% протягом $d.",
        [449288] = "$s1 шкоди від сил природи.",
        [449422] = "Вражає ворогів у конусі перед заклиначем і відкидає їх назад.",
        [449431] = "Завдає ворогам у вибраній області $s1 шкоди від таємної магії кожні $t1 с протягом $d.",
        [449668] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [449669] = "Завдає $s1 шкоди від святості будь-якій істоті, що атакує учасника групи поблизу. На гравцеві одночасно може діяти лише одна аура від одного паладина. Аура діє до скасування.",
        [449825] = "Перехід в іншу область, охоплену кошмаром.",
        [449869] = "Видихає хмару кислоти на ворогів у конусі перед заклиначем, зменшуючи їхню броню й завдаючи шкоди від сил природи кожні $t1 с. протягом $d.",
        [449890] = "Завдає $s1 шкоди ворогам у конусі позаду заклинача й відкидає їх назад.",
        [449907] = "Вивільняє вибухову хвилю магії, завдаючи ворогам поблизу шкоди від таємної магії.",
        [449925] = "Зменшує витрати мани на всі перевтілення на $s1%.",
        [449932] = "Силу атаки збільшено на $s1.",
        [449970] = "Дає вам $h% ймовірність виконати додаткову атаку по тій самій цілі після завдання удару зброєю.",
        [449975] = "Збільшує показник блокування вашого щита на $s1.",
        [450013] = "Зменшує час вимови наступного закляття \"Жертовний вогонь\" на $s1%.",
        [450084] = "Збільшує швидкість атаки ближнього бою на $s1%.",
        [450098] = "Заклинач б'є по землі, завдаючи $s1 фізичної шкоди всім гравцям та відкидаючи їх.",
        [450106] = "Відновлює $s1 здоров’я.",
        [450107] = "Відновлює $s1 здоров’я.",
        [450108] = "Дозволяє заклиначеві бачити очима цілі протягом $d.  Не працює, якщо ціль перебуває в іншій копії підземелля або на іншому континенті.",
        [450409] = "Поєднує Джанґ’траз і Санґ’траз, утворюючи могутній меч Сул’траз.",
        [450554] = "Відновлює $s1 мани.",
        [450600] = "Перетворює ворога на жабу, позбавляючи його змоги атакувати чи застосовувати закляття протягом $d.",
        [450601] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній наступній цілі більше шкоди від сил природи.",
        [450602] = "Вражає ворога блискавкою, завдаючи шкоди від сил природи.",
        [450603] = "Закликає сили природи, щоб зцілити союзника.",
        [450607] = "Заражає ворога хворобою на $d, збільшуючи отримувану ним фізичну шкоду на $s1 і зменшуючи витривалість на $s2. Уражена хворобою ціль має $h% шанс заразити одного союзника поблизу, коли отримує удар у бою.",
        [450643] = "Заражає ворога на $d, змушуючи його завдавати союзникам поблизу $3585s1 шкоди від сил природи кожні $t1 с.",
        [450646] = "Промовляє слово темряви, завдаючи ворогові шкоди від тіні кожні $t1 с. протягом $d.",
        [450650] = "Закликає святу магію, щоб зцілити союзника.",
        [450654] = "Оточує заклинача щитом, сплетеним із магії тіні. Щит триває $d., поглинає до $s1 фізичної або магічної шкоди й завдає $s2 шкоди нападникам ближнього бою.",
        [450658] = "Зцілює союзника на $s1 кожні $t1 сек. протягом $d.",
        [450659] = "Жбурляє у ворога стрілу темної магії, завдаючи шкоди від тіні.",
        [450662] = "Присипляє ворога на час до $d. Будь-яка завдана шкода пробудить ціль. Одночасно може спати лише одна ціль.",
        [450663] = "Завдає ворогові шкоди від сил природи.",
        [450667] = "Дозволяє розбійнику крастися, але зменшує вашу швидкість на $s3%.  Триває, доки не буде скасовано.",
        [451714] = "$?$a446847[Навчає виготовляти гоблінську мортиру][]",
        [452454] = "Успішні блоки зцілюють.",
        [452456] = "Швидкість руху збільшено на $s1%.",
        [452460] = "Успішні блоки спричиняють вибух, що завдає шкоди від вогню.",
        [452464] = "Ймовірність блокування збільшено на $s1%.",
        [452857] = "Збиває ворога з ніг, приголомшуючи його на $d",
        [453053] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [453622] = "Навичка спеціалізації \"Дикість\" збільшується на 5. Не поєднується з іншими рунами для перснів.",
        [453635] = "Вигравіювати на персні руну \"Спеціалізація на мечах\":",
        [453688] = "Вигравіювати на персні руну \"Спеціалізація на сокирах\":",
        [453689] = "Вигравіювати на персні руну \"Спеціалізація на булавах\":",
        [453690] = "Вигравіювати на персні руну \"Спеціалізація на кинджалах\":",
        [453691] = "Вигравіювати на персні руну \"Спеціалізація на кулачній зброї\":",
        [453692] = "Вигравіювати на персні руну \"Спеціалізація на зброї дальнього бою\":",
        [453694] = "Вигравіювати на персні руну \"Спеціалізація на держаковій зброї\":",
        [453695] = "Вигравіювати на персні руну \"Спеціалізація на аркані\":",
        [453696] = "Вигравіювати на персні руну \"Спеціалізація на вогні\":",
        [453697] = "Вигравіювати на персні руну \"Спеціалізація на кризі\":",
        [453698] = "Вигравіювати на персні руну \"Спеціалізація на природі\":",
        [453700] = "Вигравіювати на персні руну \"Спеціалізація на тіні\":",
        [453702] = "Вигравіювати на персні руну \"Спеціалізація на святості\":",
        [453703] = "Вигравіювати на персні руну \"Спеціалізація на дикості\":",
        [455350] = "Зменшує ефективність зцілення ворога на $s1% на $d.",
        [455852] = "Шкоду \"Шипів\" збільшено на $s1%, а тривалість збільшено на $s2%.",
        [455858] = "Збільшує ймовірність завдання удару закляттями та атаками на $s1%.",
        [455859] = "Зменшує час відновлення \"Зорепаду\" на $s1%.",
        [455872] = "Періодична шкода здібностей \"Роздирання\" та \"Розірвання\" тепер може бути критичною.",
        [456194] = "Коли ви застосовуєте \"Осяяння\" на іншого гравця, воно також застосовується на вас.",
        [456195] = "Збільшує відновлення мани цілі на $s2% і дозволяє $s1% відновлення мани тривати під час вимовляння заклять. Триває $d.",
        [456222] = "Після вимови \"Цілющого дотику\" або \"Підживлення\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [456322] = "Зменшує час відновлення \"Спокою\" на $s1% та збільшує його зцілення на $s2%.",
        [456325] = "Ви можете вимовляти \"Переродження\" та \"Осяяння\" перебуваючи у подобі ведмедя та жахливого ведмедя.",
        [456328] = "\"Несамовитість\" має на ${$m1/-1000} секунд зменшений час відновлення і більше не зменшує вашу броню.",
        [456332] = "У подобах ведмедя та жахливого ведмедя ви спричиняєте на $s1% більше загрози, а \"Зіщулювання\" тепер прибирає всю вашу загрозу цілі але має на ${$m2/1000} с більший час відновлення.",
        [456341] = "Поки ви вистежуєте створінь певного виду, ви завдаєте їм на $s1% більше шкоди.",
        [456396] = "Ви невразливі до будь-якої шкоди, поки промовляєте \"Прикликання\".",
        [456402] = "\"Магівський обладунок\" збільшує відновлення мани під час вимови заклять ще на $s1%. \"Розплавлений обладунок\" збільшує шкоду і зцілення ваших заклять на $s2. \"Льодяний обладунок\" збільшує ймовірність спрацювання ефекту \"Крижаних пальців\" на $s3%.",
        [456404] = "Ваші \"Темпоральні маяки\" тривають на $s1% довше.",
        [456477] = "Збільшує все ваше хрономантичне зцілення на $s1%.",
        [456481] = "Щоразу, коли ви зцілюєте ціль \"Регенерацією\", час відновлення \"Повернення у часі\" скорочується на $s1 с.",
        [456485] = "Зцілює ціль на ${$<healpower>*$m1/100*3} здоров'я протягом $d і накладає «Часовий маяк» на $400735s3 с. \r\n\r\nЧасовий маяк\r\n$@spellicon400735\r\n$@spelldesc400735",
        [456488] = "Збільшує ймовірність спрацювання \"Присуду світла\" та \"Присуду мудрості\" для ваших союзників до $s1%.",
        [456494] = "\"Присуд світла\" та \"Присуд мудрості\" також накладають ефект \"Присуду лицаря\".",
        [456533] = "Ваші печатки наказу, праведності та мучеництва, а також \"Сонячне сяйво\" завдають на $s2% менше шкоди, але продовжують діяти протягом $s1 с після накладання іншої печатки або до накладання третьої. \"Присуд\" тепер може викликати спрацювання кількох печаток.",
        [456536] = "Збільшує показник блокування вашого щита на $s1.",
        [456541] = "Священний щит більше не має зарядів і не спадає від блокувань. Крім того, його шкода збільшується на $s2% від вашого показника блоку щитом.",
        [456546] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [456547] = "Збільшує ймовірність критичного ефекту \"Молитви зцілення\" та \"Кола зцілення\" на $s1%.",
        [456548] = "Ми можете вимовляти \"Швидке зцілення\" в \"Тінеобразі\".",
        [456881] = "Орда дозволяє вам перебувати тут. Поки що.",
        [457323] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [457339] = "Збільшує бонус критичної шкоди для ваших отрут на $s1%.",
        [457344] = "Ваші завершальні рухи з ймовірністю $b1% за кожен прийом в комбінації дозволять використати наступну здібність без витрат енергії.",
        [457475] = "Радіус дії тотемів, що діють на союзників, збільшується до ${$m1+20} м.",
        [457478] = "Після вимови \"Хвилі зцілення\", \"Малої хвилі зцілення\" та \"Бистрини\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [457494] = "Ваша \"Хвиля зцілення\" також перестрибує на цілі неподалік, з кожним стрибком зцілюючи на $s2% менше. Максимум до ${$m1-1} стрибків.",
        [457530] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [457532] = "Талант \"Шквал\" збільшує вашу швидкість атаки ще на $s1%.",
        [457541] = "Парирування та ухилення також викликають спрацювання ефекту руни \"Майстерність володіння щитом\".",
        [457544] = "Ваш \"Тотем кам'яної шкіри\" також зменшує отриману фізичну шкоду на $s1%, а ваш \"Тотем стіни вітру\" також зменшує отриману магічну шкоду на $s1%",
        [457548] = "\"Витік життя\" відновлює на $s1% більше мани та спричиняє на $s2% менше загрози.",
        [457549] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [457553] = "Ймовірність спрацювання таланту \"Сутінки\" збільшується на $s1%. \"Спалення\" з ймовірністю $h% спричиняє ефект \"Винищення\" незалежно від запасу здоров'я цілі.",
        [457571] = "\"Вигнання\" тепер вимовляється миттєво і його можна застосувати до себе, поки ви є демоном. Самовигнання неможливе, якщо ви маєте ефект стриманості, а його застосування накладає на вас ефект стриманості на 1 хвилину.",
        [457572] = "Щоразу, коли ви отримуєте шкоду, ви і ваш вихованець отримуєте ману в обсязі, що дорівнює отриманій шкоді, але не більше $s1 мани за раз. Цей ефект може спрацьовувати лише раз на кілька секунд.",
        [457645] = "Збільшує показник блокування вашого щита на $s1.",
        [457646] = "Ви отримуєте додатково ${$457648m1/10} люті щоразу, коли отримуєте будь-яку шкоду чи завдаєте удару автоматичною атакою.",
        [457651] = "Збільшує вашу загрозу в захисній стійці додатково на $s1% та збільшує вашу шкоду в стійці гладіатора на $s2%.",
        [457652] = "Після зміни стійки витрати люті на вашу наступну бойову здібність зменшуються на $s1.",
        [457848] = "Освячує зброю заклинача, додаючи $s1 шкоди до її наступної атаки. Уся завдана шкода належить до святої магії.",
        [458287] = "\"Освячення\" тепер зцілює учасників групи, що перебувають в зоні його дії, на $s1% від шкоди.",
        [458393] = "\"Укус мангусти\" з ймовірністю $s3% завершує відновлення від ваших атак ближнього бою і з ймовірністю 100%, коли ворог ухиляється. Ця ймовірність накопичується, збільшуючись на $s3% від кожної атаки, що не завершила час відновлення. \"Укус мангусти\" також завдає додаткової шкоди в обсязі $s2% від вашої сили атаки.",
        [458819] = "Завдає ворогові шкоди від вогню.",
        [458872] = "Кінець епохи вже близько!\nЗапас здоров'я обмежено.\nШвидкість руху обмежено до 100%.",
