        [474570] = "Вогонь.",
        [474571] = "Чума.",
        [474742] = "Завдає $s1 шкоди ворогам у конусі позаду заклинача й відкидає їх назад.",
        [1213144] = "Випий мене.",
        [1213145] = "Виконати старовинний обряд кіражів.",
        [1213147] = "Збільшує зцілення магічних заклять і ефектів на величину до $s1 на $d.",
        [1213155] = "Заражає ворога на $d, змушуючи його завдавати союзникам поблизу $24929s1 шкоди від сил природи кожні $t1 с.",
        [1213159] = "Зменшує час відновлення заклять \"Переродження\" та \"Осяяння\" на $s1%.",
        [1213160] = "Критичні ефекти \"Цілющого дотику\", \"Розростання\" та \"Підживлення\" миттєво відновлюють цілі ще $s1% від первинного ефекту зцілення.",
        [1213164] = "Талант \"Природна благодать\" отримує 1 додатковий заряд при спрацюванні.",
        [1213167] = "Збільшує додаткову шкоду від критичних ударів заклять \"Зоряний вогонь\", \"Зоряний сплеск\" та \"Гнів\" на $s1%.",
        [1213171] = "\"Шматування\" більше не має вимоги до позиціонування, але завдає на $s1% більше шкоди, якщо ви знаходитесь за спиною цілі.",
        [1213201] = "Ймовірність ухилення та парирування ваших атак ближнього бою зменшено на $s1%.",
        [1213240] = "Зменшує магічні опори цілей ваших заклять на $s1.",
        [1213246] = "Час відновлення \"Вбивчого пострілу\" зменшується на $s3%. Поки діє \"Швидка стрілянина\" з гравіюванням \"Швидкого вбивства\", \"Вбивчий постріл\" не має часу відновлення, а при використанні проти цілі, яка не контролюється гравцем, вистрілює $s4 додаткові \"Вбивчі постріли\", що завдають $s5% шкоди, з мінімальною дальністю дії.",
        [1213248] = "Жбурляє у ворога блискавку, завдаючи шкоди від сил природи.",
        [1213250] = "Викликає дощ місячного сяйва, що завдає всім ворогам у вибраній області $s1 шкоди від таємної магії кожні $t1 с протягом $d.",
        [1213253] = "Обплутує ворога корінням, завдаючи шкоди від сил природи кожні $t2 с. і знерухомлюючи його на час до $d.",
        [1213268] = "Накладає на ціль Мітку мисливця, збільшуючи силу атаки дальнього бою всіх нападників проти цієї цілі на $s2.  Крім того, мисливець завжди бачить ціль цієї здібності, навіть якщо вона входить у непомітність або стає невидимою.  Ціль також відображається на мінімапі.  Триває $d.",
        [1213269] = "Завдає ворогові та його союзникам поблизу шкоди зброєю та додатково $s1 шкоди від вогню.",
        [1213271] = "Встановлює вогняну пастку, що обпалює першого ворога, який наблизиться, завдаючи $14301o1 шкоди від вогню протягом $14301d. Пастка існує $d. Пастки можна встановлювати лише поза боєм. Одночасно може бути активна лише одна пастка.",
        [1213272] = "Стріляє у ворога, завдаючи фізичної шкоди.",
        [1213276] = "Завдає ворогові шкоди від криги та зменшує швидкість його руху на $d.",
        [1213279] = "Викликає хуртовину на $d., що завдає всім ворогам у вибраній зоні $s1 шкоди від криги кожні $t1 сек.",
        [1213288] = "Зменшує шанс ухилення чи парирування ваших атак на $s1%.",
        [1213298] = "Закликає святу магію, щоб зцілити союзника.",
        [1213300] = "Захищає заклинача від усіх атак і заклять протягом $d., але в цей час заклинач також не може атакувати чи застосовувати закляття.",
        [1213301] = "Приголомшує ворога, позбавляючи його можливості рухатися чи атакувати протягом $d.",
        [1213306] = "Збільшує шкоду \"Вбивчого пострілу\" проти цілей, що не перебувають під контролем гравців, на $s1%.",
        [1213307] = "Збільшує періодичну шкоду \"Удару виверни\" на $s1% та збільшує максимальний запас концентрації вашого супутника на $s2.",
        [1213309] = "Збільшує первинну шкоду \"Укусу мангусти\" та всіх ударів на $s1%.",
        [1213310] = "Прискорює відновлення концентрації ваших вихованців на $s1%.",
        [1213312] = "\"Арканічний спалах\" додатково збільшує шкоду на $s1% за кожен ефект.",
        [1213319] = "Збільшує шкоду від таланту \"Займання\" на $s1%.",
        [1213321] = "Закляття \"Вогняна куля\", \"Стріла крижаного полум'я\" та \"Стріла руйнівного полум'я\" завдають на $s1% більше шкоди за кожен ваш вогняний ефект на цілі, максимум до $s2%.",
        [1213331] = "Вражає ворога антимановою стрілою. За кожну поглинуту стрілою одиницю мани ціль отримує $e1 шкоди.",
        [1213332] = "Підкорює гуманоїда до $s1 рівня на $d.",
        [1213334] = "Приймає Тіньову форму, збільшуючи завдану шкоду від тіні на $s2% і зменшуючи отримувану шкоду ближнього бою на $s1%. Тіньова форма триває, доки не буде скасовано.",
        [1213336] = "Завдає ворогові шкоди від тіні, але створює велику кількість загрози.",
        [1213349] = "Зменшує час відновлення \"Божественного світла\" на $s1%.",
        [1213353] = "Коли \"Маяк Світла\" зцілює ціль, він також зцілює найближчу дружню поранену ціль на $s1% свого ефекту.",
        [1213355] = "Миттєво вражає ціль блискавкою, завдаючи $s1 шкоди від сил природи.",
        [1213356] = "Підкоряє гуманоїда-ворога до $s1 рівня на $d, але збільшує час між його атаками на $s2%.",
        [1213375] = "Поглинає $s1 шкоди. Триває $d.",
        [1213390] = "Збільшує шанс завдання додаткового удару в ближньому чи дальньому бою на $s1% за кожен екіпірований вами загартований часом обладунок.",
        [1213397] = "Збільшує шкоду \"Удару лицаря\" на $s1%.",
        [1213398] = "Збільшує швидкість вимови заклять на $s1% за кожен екіпірований вами загартований часом обладунок.",
        [1213405] = "Збільшує ефективність ваших заклять зцілення та поглинання шкоди на $s1% за кожен екіпірований вами загартований часом обладунок.",
        [1213407] = "Зменшує шанс ухилення чи парирування ваших атак на $s1% за кожен екіпірований вами загартований часом обладунок.",
        [1213413] = "Після застосування \"Щита праведника\" ваше наступне \"Священне світло\" вимовляється миттєво. При застосуванні закляття на себе, воно відновить $s1% витраченої мани, і на нього не впливатиме ефект \"Під захистом Світла\".",
        [1213418] = "Удар блискавки завдає $s1 шкоди від сил природи.",
        [1213420] = "Іноді зцілює власника на $s1 під час атаки ворога.",
        [1213441] = "Завдає ворогові звичайної шкоди та ще $s1.",
        [1213442] = "Під час атаки з непомітності завдає ворогові $s1 шкоди кожні $t1 сек. протягом $d.",
        [1213450] = "Оскверняє ворогів поблизу, завдаючи шкоди від тіні кожні $t1 с. протягом $d.",
        [1213451] = "Обрушує розплавлений дощ, що обпалює всіх ворогів у вибраній ділянці на $s1 шкоди від вогню кожні $t1 с. протягом $d.",
        [1213452] = "Вселяє у ворога страх, змушуючи його тікати в жаху протягом $d. Одночасно можна налякати лише 1 ціль.",
        [1213462] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [1213463] = "Здійснює ривок до ворога, завдаючи звичайної шкоди плюс $s3 та приголомшуючи супротивника на $d.",
        [1213464] = "Завдає ворогам поблизу $s1 шкоди від сил природи, збільшуючи час між їхніми атаками на $s3% і зменшуючи швидкість руху на $s2% на $d.",
        [1213465] = "Кричить на ворога, паралізуючи його жахом на $d. і змушуючи всіх інших ворогів поблизу тікати в страху.",
        [1213466] = "Прикликає $s1 $lRazormane Wolf:Razormane Wolves; супроводжувати заклинача, доки їх не відкличуть.",
        [1213467] = "Поки ви тримаєте одноручну зброю, \"Удар лицаря\" вивільняє ефекти ваших печаток на цілі, але не поглинає їх.",
        [1213477] = "Вражає ворога блискавкою, яка перескакує на іншого ворога поблизу. Закляття уражає до $x1 цілей, завдаючи кожній наступній цілі більше шкоди від сил природи.",
        [1213479] = "Оточує заклинача $n кулями блискавки, які мають $h% шанс уразити нападників ближнього або дальнього бою на $s1 шкоди. Після кожного спрацювання блискавичного щита одна куля розсіюється. Тож щит зникає через $d або після $n спрацювань.",
        [1213480] = "Викликає Тотем земних пут, який існує $d. і періодично зменшує швидкість руху ворогів поблизу до $3600s1% від звичайної.",
        [1213482] = "Миттєво обпалює ворога, а потім завдає додаткової шкоди від вогню кожні $t2 с. протягом $d.",
        [1213624] = "Ваша \"Молитва загоєння\" отримує ще $s1 заряди.",
        [1213631] = "\"Коло зцілення\" відновлює найбільш пораненому учаснику групи цілі на $s1% більше здоров'я.",
        [1213675] = "\"Муки розуму\" більше не зазнають переривання промовляння при отриманні шкоди, а також запускають безкоштовне \"Пронизування розуму\" в ціль при початку промовляння.",
        [1213705] = "\"Пронизування розуму\" тепер вимовляється миттево, завдає на $s2% більше шкоди і його можна вимовити під час промовляння інших заклять.",
        [1213708] = "Руна \"Біль і страждання\" також може поновлювати тривалість ефекту \"Ненажерної чуми\".",
        [1213713] = "Збільшує шкоду здібностей \"Скалічити\" та \"Удар шаблею\" на $s1%.",
        [1213714] = "Зменшує час відновлення \"Викиду адреналіну\" на ${$m1/-60000} хв.",
        [1213754] = "\"Удар лівицею\" вражає ще одну ціль, та дозволяє \"Підступному удару\" вражати одну додаткову ціль протягом 10 секунд. Додаткові удари не подвоюються \"Шквалом клинків\".",
        [1213759] = "Під час дії ефекту \"Удару лівицею\" ви зцілюєтесь на $s1% від заданої шкоди \"Підступним ударом\". Надлишкове зцілення захистить вас \"Бар'єром крові\", що поглинатиме шкоду в обсязі до $s2% від максимального запасу здоров'я.",
        [1213763] = "Ваші завершальні рухи витрачають на $s1% менше енергії.",
        [1213810] = "Ваша \"Бистрина\" також збільшує ефективність \"Ланцюгового зцілення\" на $s1%.",
