        [1217152] = "Закликає та відкликає їздового кіражського бойового танка. Це дуже швидкий верховий звір.",
        [1217153] = "Закликає та відкликає їздового кіражського бойового танка. Це дуже швидкий верховий звір.",
        [1217154] = "Закликає та відкликає їздового кіражського бойового танка. Це дуже швидкий верховий звір.",
        [1217155] = "Закликає та відкликає їздового кіражського бойового танка. Це дуже швидкий верховий звір.",
        [1217156] = "Закликає та відкликає їздового кіражського бойового танка. Це дуже швидкий верховий звір.",
        [1217297] = "Зменшує витрати мани на всі перевтілення на $s1%.",
        [1217511] = "Збільшує шанс ухилитися від атаки на $s1%.",
        [1218134] = "Намагається зняти з ворожої істоти $s1 ефект Шаленства.",
        [1218363] = "Карає ворога, завдаючи шкоди від святості.",
        [1218364] = "Карає ворога, завдаючи шкоди від святості.",
        [1218485] = "Збільшує всю шкоду цілям у Силітусі, Ан'Кіражі, Східних Зачумлених землях та Наксрамасі на $s1%, а також збільшує критичну шкоду цілям в цих зонах на $s2%.",
        [1218506] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [1219043] = "Розтрощити труп полеглого друга чи ворога, завдавши $s1 шкоди навколишнім ворогам.",
        [1219057] = "Розтрощити труп полеглого друга чи ворога, завдавши $s1 шкоди навколишнім ворогам.",
        [1219083] = "При отриманні удару в ближньому бою авдає $s1 шкоди від тіні нападникам. Спричиняє вдвічі більше загрози.",
        [1219274] = "Вивчіть здібність жерців іншої раси, щоб активувати цю здібність.",
        [1219355] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [1219379] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [1219388] = "Завдає $s1 шкоди від вогню.",
        [1219415] = "Збільшує шкоду й зцілення магічними закляттями та ефектами на величину до $s1.",
        [1219475] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [1219500] = "Збільшує швидкість атаки на $s1% протягом $d1.",
        [1219506] = "Відновлює $s1 мани.",
        [1219507] = "Накласти на наплічники чари, що збільшують зцілення від магічних заклинань і ефектів на $s2, а також відновлюють $s3 мани кожні 5 с.",
        [1219513] = "Збільшує зцілення наступних 5 заклять на величину до $s1 на $d.",
        [1219515] = "Збільшує шкоду та зцілення магічних заклять і ефектів на величину до $s1 на $d.",
        [1219519] = "Збільшує силу атаки на $s1 протягом $d.",
        [1219520] = "Збільшує показник блокування вашого щита на $s1 на $d.",
        [1219521] = "Збільшує силу атаки на $s1 в бою з невмерлими та демонами. Також дозволяє отримувати камені Скари для Сріблястого Світанку.",
        [1219522] = "Збільшує шкоду магічних заклять і ефектів проти нежиті та демонів на величину до $s1. Дає змогу збирати камені Скверни від імені Сріблястого Світанку.",
        [1219541] = "Провокує ціль атакувати вас, але не має ефекту, якщо ціль уже вас атакує.",
        [1219552] = "Збільшує шкоду і зцілення магічних заклинань і ефектів для всіх учасників групи в межах $a1 м на $s1. Цей ефект не поєднується при накладанні з кілької джерел.",
        [1219553] = "Збільшує зцілення на $s1, а шкоду на $s2 для всіх магічних заклинань і ефектів учасників групи в межах $a1 м. Цей ефект не поєднується при накладанні з кілької джерел.",
        [1219557] = "Збільшує швидкість вимови заклять для всіх учасників групи в межах $a1 м на $s1%. Цей ефект не поєднується при накладанні з кілької джерел.",
        [1219558] = "Збільшує ймовірність завдання критичного удару закляттями для всіх учасників групи в межах $a1 м на $s1%. Цей ефект не поєднується при накладанні з кілької джерел.",
        [1219706] = "Відновлює $s1 енергії.",
        [1219707] = "Відновлює $s1 люті.",
        [1219708] = "Відновлює $s1 мани.",
        [1219745] = "Наповнити наплічники душею кровожера:\n\nКритичні удари \"Здолання\" поновлюють тривалість ефекту \"Розриву\" на цілі до максимальної тривалості.",
        [1219748] = "Наповнити наплічники душею руйнівника:\n\nУдари \"Розтрощення\" завершують відновлення здібностей \"Смертельний удар\", \"Кровожерливість\" та \"Трощення щитом\".",
        [1219780] = "Наповнити наплічники душею виваженого бійця:\n\n\"Удар за ударом\" тепер активується щоразу, коли ви продовжуєте комбінацію прийомів.",
        [1219782] = "Наповнити наплічники душею фехтувальника:\n\nВідновлення \"Удару лівицею\" завершується щоразу, коли ви ухиляєтесь чи парируєте.",
        [1219783] = "Наповнити наплічники душею шибайголови:\n\n\"Удар лівицею\" вражає ще одну ціль, та дозволяє \"Підступному удару\" вражати одну додаткову ціль протягом 10 секунд. Додаткові удари не подвоюються \"Шквалом клинків\".",
        [1219795] = "Наповнити наплічники душею демонічного екзорциста:\n\n\"Вигнання\" тепер вимовляється миттєво і його можна застосувати до себе, поки ви є демоном. Самовигнання неможливе, якщо ви маєте ефект стриманості, а його застосування накладає на вас ефект стриманості на 1 хвилину.",
        [1219802] = "Наповнити наплічники душею ритуаліста:\n\nЕфект \"Демонічної жертви\" зберігається, доки ви не викличете принесеного в жертву прислужника. Одночасно на вас може діяти лише один ефект \"Демонічної жертви\".",
        [1219834] = "Наповнити наплічники душею сутінкового мандрівника:\n\nМи можете вимовляти \"Швидке зцілення\" в \"Тінеобразі\".",
        [1219839] = "Наповнити наплічники душею непохитного осквернителя:\n\n\"Муки розуму\" більше не зазнають переривання промовляння при отриманні шкоди, а також запускають безкоштовне \"Пронизування розуму\" в ціль при початку промовляння.",
        [1219841] = "Наповнити наплічники душею розносника чуми:\n\nРуна \"Біль і страждання\" також може поновлювати тривалість ефекту \"Ненажерної чуми\".",
        [1219852] = "Наповнити наплічники душею пробудника:\n\nВи невразливі до будь-якої шкоди, поки промовляєте \"Прикликання\".",
        [1219877] = "Наповнити наплічники душею арбітра:\n\n\"Присуд світла\" та \"Присуд мудрості\" також накладають ефект \"Присуду лицаря\".",
        [1219886] = "Наповнити наплічники душею храмовника:\n\nПоки ви тримаєте одноручну зброю, \"Удар лицаря\" вивільняє ефекти ваших печаток на цілі, але не поглинає їх.",
        [1219888] = "Наповнити наплічники душею майстра щитів:\n\nПарирування та ухилення також викликають спрацювання ефекту руни \"Майстерність володіння щитом\".",
        [1219917] = "Наповнити наплічники душею лавового мудреця:\n\nШкода \"Виверження лави\" збільшується на відсоток ймовірності критичного удару.",
        [1219920] = "Наповнити наплічники душею Лагідної Лапи:\n\nВи можете вимовляти \"Переродження\" та \"Осяяння\" перебуваючи у подобі ведмедя та жахливого ведмедя.",
        [1219925] = "Наповнити наплічники душею розірвання:\n\nВаш \"Розмах\" тепер поширює ефект вашої здібності \"Розірвати\" з вашої цілі на інші уражені цілі.",
        [1219928] = "Наповнити наплічники душею осяяння:\n\nКоли ви застосовуєте \"Осяяння\" на іншого гравця, воно також застосовується на вас.",
        [1219937] = "Наповнити наплічники душею хижих інстинктів:\n\nПеріодична шкода здібностей \"Роздирання\" та \"Розірвання\" тепер може бути критичною.",
        [1219950] = "Наповнити наплічники душею Благодатного:\n\nТалант \"Природна благодать\" отримує 1 додатковий заряд при спрацюванні.",
        [1219955] = "Сюди можна гравіювати душу полеглого воїна.",
        [1219957] = "Після зміни стійки витрати люті на вашу наступну бойову здібність зменшуються на $s1.",
        [1219962] = "Критичні удари \"Здолання\" поновлюють тривалість ефекту \"Розриву\" на цілі до максимальної тривалості.",
        [1219964] = "Здібності \"Героїчний удар\", \"Розтрощення\" та \"Здолання\" завдають на $s1% більше шкоди.",
        [1219966] = "Удари \"Розтрощення\" завершують відновлення здібностей \"Смертельний удар\", \"Кровожерливість\" та \"Трощення щитом\".",
        [1219968] = "Зменшує час відновлення \"Жаги смерті\" на $s1%.",
        [1219970] = "Ви завдаєте на $s1% більше шкоди, поки на когось з ворогів неподалік діють обидва ваші ефекти \"Розрив\" та \"Глибокі рани\".",
        [1219972] = "Збільшує показник блокування вашого щита на $s1.",
        [1219974] = "Ви отримуєте додатково ${$457648m1/10} люті щоразу, коли отримуєте будь-яку шкоду чи завдаєте удару автоматичною атакою.",
        [1219976] = "Збільшує вашу загрозу в захисній стійці додатково на $s1% та збільшує вашу шкоду в стійці гладіатора на $s2%.",
        [1219978] = "Ви отримуєте ${$468066m1/10} люті щоразу коли парируєте атаку чи вашу атаку парирують.",
        [1219984] = "Зменшує час відновлення \"Громового удару\" на $s1%.",
        [1219986] = "\"Трощення щитом\" спричиняє на $s1% більше загрози, а його відновлення миттєво завершується, якщо його блокували, ухилилися або парирували.",
        [1219988] = "Зменшує час відновлення здібності \"Трощення щитом\" на ${$m1/-1000} с.",
        [1219990] = "Зменшує час відновлення здібності \"Кривава лють\" на ${$m1/-1000} с, поки ви перебуваєте в стійці гладіатора.",
        [1219992] = "Зменшує час відновлення \"Ударної хвилі\" на $s1%.",
        [1219996] = "Збільшує бонус критичної шкоди для ваших отрут на $s1%.",
        [1219998] = "Ваші завершальні рухи з ймовірністю $b1% за кожен прийом в комбінації дозволять використати наступну здібність без витрат енергії.",
        [1220000] = "Здібності, що починають комбінацію прийомів, з ймовірністю $h% дозволять використати наступну здібність без витрат енергії.",
        [1220002] = "Збільшує шкоду вашої зброї в правій руці на $s1% для здібностей, що продовжують комбінацію прийомів.",
        [1220004] = "Зменшує час відновлення \"Зникнення\" до ${$m3/60000} хв. Не поєднується з \"Невловимістю\".",
        [1220006] = "Збільшує шкоду здібностей \"Скалічити\" та \"Удар шаблею\" на $s1%.",
        [1220008] = "Зменшує час відновлення \"Викиду адреналіну\" на ${$m1/-60000} хв.",
        [1220010] = "Збільшує ймовірність завдати критичного удару кинджалами на $s1%.",
        [1220012] = "Збільшує шанс критичного удару Засідки на $s1%.",
        [1220014] = "Ваші завершальні рухи витрачають на $s1% менше енергії.",
        [1220022] = "\"Удар за ударом\" тепер активується щоразу, коли ви продовжуєте комбінацію прийомів.",
        [1220023] = "\"Удар за ударом\" також збільшує броню від предметів на $s1% за кожен ефект (але не більше ${$s1*5}%).",
        [1220026] = "Відновлення \"Удару лівицею\" завершується щоразу, коли ви ухиляєтесь чи парируєте.",
        [1220028] = "\"Удар лівицею\" вражає ще одну ціль, та дозволяє \"Підступному удару\" вражати одну додаткову ціль протягом 10 секунд. Додаткові удари не подвоюються \"Шквалом клинків\".",
        [1220030] = "Під час дії ефекту \"Удару лівицею\" ви зцілюєтесь на $s1% від заданої шкоди \"Підступним ударом\". Надлишкове зцілення захистить вас \"Бар'єром крові\", що поглинатиме шкоду в обсязі до $s2% від максимального запасу здоров'я.",
        [1220032] = "\"Витік життя\" відновлює на $s1% більше мани та спричиняє на $s2% менше загрози.",
        [1220034] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1220035] = "Ймовірність спрацювання таланту \"Сутінки\" збільшується на $s1%. \"Спалення\" з ймовірністю $h% спричиняє ефект \"Винищення\" незалежно від запасу здоров'я цілі.",
        [1220038] = "Збільшує шкоду ваших заклять періодичної шкоди та вартового скверни на $s1%.",
        [1220040] = "Періодична шкода заклять \"Тіньове полум'я\", \"Нестабільна химородь\" та \"Прокляття агонії\", а також шкода вартового скверни з ймовірністю $h% спричинить ефект \"Тінетрансу\".",
        [1220042] = "\"Тіньова стріла\" завдає на $s1% більше шкоди за кожен ваш ефект на цілі, максимум до $s2%.",
        [1220044] = "Зменшує час відновлення \"Стріли Хаосу\" на $s1% та збільшує шкоду \"Стріли Хаосу\" та \"Тіньової стріли\" на $s2%. Окрім того, \"Стріла Хаосу\" тепер може спричинити ефект таланту \"Покращена тіньова стріла\" та збільшує максимальну кількість його ефектів на $s3 (не поєднується з додатковими ефектами від \"Тіньового полум'я\").",
        [1220048] = "Збільшує силу атаки та шкоду заклять, які ваш прислужник отримує від ваших атрибутів, на $s1%.",
        [1220050] = "Посилює ефект таланту \"Майстер-демонолог\" на $s1%.",
        [1220052] = "\"Вигнання\" тепер вимовляється миттєво і його можна застосувати до себе, поки ви є демоном. Самовигнання неможливе, якщо ви маєте ефект стриманості, а його застосування накладає на вас ефект стриманості на 1 хвилину.",
        [1220054] = "Щоразу, коли ви отримуєте шкоду, ви і ваш вихованець отримуєте ману в обсязі, що дорівнює отриманій шкоді, але не більше $s1 мани за раз. Цей ефект може спрацьовувати лише раз на кілька секунд.",
        [1220062] = "Надлишкове самозцілення перетворюється на щит, який поглинає шкоду. Цей щит може поглинути до $s1% від вашого максимального запасу здоров'я, а також підсилюється від подальшого самозцілення.",
        [1220066] = "Ефект \"Демонічної жертви\" зберігається, доки ви не викличете принесеного в жертву прислужника. Одночасно на вас може діяти лише один ефект \"Демонічної жертви\".",
        [1220076] = "Ваш \"Прицільний постріл\" завдає на $s1% більше шкоди цілям, ураженим однією з ваших пасток.",
        [1220078] = "Здібності-постріли, що завдають шкоди, завдають на $s1% більше шкоди, якщо попередній постріл було застосовано на іншу ціль.",
        [1220080] = "Шкода \"Жала змії\" збільшується на $s1% від вашої сили атаки.",
        [1220082] = "Збільшує шкоду \"Вбивчого пострілу\" проти цілей, що не перебувають під контролем гравців, на $s1%.",
        [1220084] = "Час відновлення \"Вбивчого пострілу\" зменшується на $s3%. Поки діє \"Швидка стрілянина\" з гравіюванням \"Швидкого вбивства\", \"Вбивчий постріл\" не має часу відновлення, а при використанні проти цілі, яка не контролюється гравцем, вистрілює $s4 додаткові \"Вбивчі постріли\", що завдають $s5% шкоди, з мінімальною дальністю дії.",
        [1220086] = "Збільшує бонус до сили атаки вашого супутника від ваших характеристик на $s1%.",
        [1220088] = "Прискорює відновлення концентрації вашого вихованця на $s1%.",
        [1220090] = "Прискорює відновлення концентрації ваших вихованців на $s1%.",
        [1220098] = "Збільшує шкоду зброї в правій руці для здібностей \"Удар раптора\" та \"Удар виверни\" на $s1%.",
        [1220100] = "Ваша періодична шкода з ймовірністю $h% завершить відновлення здібності-удару з найдовшим поточним часом відновленння.",
        [1220102] = "Збільшує періодичну шкоду \"Удару виверни\" на $s1% та збільшує максимальний запас концентрації вашого супутника на $s2.",
        [1220104] = "Збільшує первинну шкоду \"Укусу мангусти\" та всіх ударів на $s1%.",
        [1220108] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1220110] = "Збільшує ймовірність критичного ефекту \"Молитви зцілення\" та \"Кола зцілення\" на $s1%.",
        [1220112] = "Дозволяє $s1% відновлення мани продовжувати діяти під час застосування заклять.",
        [1220114] = "Ваше періодичне зцілення з ймовірністю $h% дозволить миттєво вимовити наступне закляття з тривалістю вимови менше 10 с.",
        [1220118] = "Ваша \"Молитва загоєння\" отримує ще $s1 заряди.",
        [1220120] = "\"Коло зцілення\" відновлює найбільш пораненому учаснику групи цілі на $s1% більше здоров'я.",
        [1220122] = "Зменшує час відновлення \"Сповіді\" на ${$m1/-1000} с.",
        [1220124] = "Збільшує обсяг поглинання закляття \"Слово сили: Щит\" на $s1%.",
        [1220126] = "Ми можете вимовляти \"Швидке зцілення\" в \"Тінеобразі\".",
        [1220130] = "Зменшує час відновлення закляття \"Слово тіні: Смерть\" на ${$m1/-1000} с.",
        [1220136] = "\"Муки розуму\" більше не зазнають переривання промовляння при отриманні шкоди, а також запускають безкоштовне \"Пронизування розуму\" в ціль при початку промовляння.",
        [1220138] = "\"Пронизування розуму\" тепер вимовляється миттево, завдає на $s2% більше шкоди і його можна вимовити під час промовляння інших заклять.",
        [1220140] = "Руна \"Біль і страждання\" також може поновлювати тривалість ефекту \"Ненажерної чуми\".",
        [1220142] = "Ваші \"Темпоральні маяки\" тривають на $s1% довше.",
        [1220144] = "Збільшує все ваше хрономантичне зцілення на $s1%.",
        [1220146] = "Щоразу, коли ви зцілюєте ціль \"Регенерацією\", час відновлення \"Повернення у часі\" скорочується на $s1 с.",
        [1220148] = "Ваші \"Арканічні снаряди\" відновлюють вам $s1% від базових витрат мани на них щоразу, коли завдають шкоди.",
        [1220150] = "\"Арканічний спалах\" має на $s1% більшу ймовірність викликати ефект \"Обстрілу снарядами\", а \"Обстріл снарядами\" впливає на \"Регенерацію\" так само, як і на \"Арканічні снаряди\".",
        [1220152] = "Ваші \"Темпоральні маяки\", спричинені \"Масовою регенерацією\" тепер тривають $m1 с.",
        [1220154] = "\"Арканічний спалах\" додатково збільшує шкоду на $s1% за кожен ефект.",
        [1220158] = "Збільшує ймовірність спрацювання руни \"Крижані пальці\" на $s1%.",
        [1220160] = "Збільшує шкоду заклять \"Крижана стріла\" та \"Чарокрижана стріла\" на $s1%.",
        [1220162] = "Ви невразливі до будь-якої шкоди, поки промовляєте \"Прикликання\".",
        [1220166] = "\"Магівський обладунок\" збільшує відновлення мани під час вимови заклять ще на $s1%. \"Розплавлений обладунок\" збільшує шкоду і зцілення ваших заклять на $s2. \"Льодяний обладунок\" збільшує ймовірність спрацювання ефекту \"Крижаних пальців\" на $s3%.",
        [1220168] = "Зменшує загрозу ваших вогняних заклять на $s1%.",
        [1220170] = "\"Вогняна брила\" завдає на $s1% більше шкоди цілі, що перебуває під ефектом періодиної шкоди вашої \"Вогняної кулі\".",
        [1220172] = "Збільшує загальну шкоду ефекту \"Вогняної кулі\" на $s1% від первинної шкоди.",
        [1220176] = "Збільшує шкоду від таланту \"Займання\" на $s1%.",
        [1220178] = "Закляття \"Вогняна куля\", \"Стріла крижаного полум'я\" та \"Стріла руйнівного полум'я\" завдають на $s1% більше шкоди за кожен ваш вогняний ефект на цілі, максимум до $s2%.",
        [1220180] = "Збільшує показник блокування вашого щита на $s1.",
        [1220184] = "Священний щит більше не має зарядів і не спадає від блокувань. Крім того, його шкода збільшується на $s2% від вашого показника блоку щитом.",
        [1220186] = "Збільшує бонус до ймовірності блокування від \"Священного щита\" на $s1%.",
        [1220190] = "Талант \"Воздаяння\" з ймовірністю $s1% за ранг спрацьовує, коли ви блокуєте.",
        [1220194] = "Після застосування \"Щита праведника\" ваше наступне \"Священне світло\" вимовляється миттєво. При застосуванні закляття на себе, воно відновить $s1% витраченої мани, і на нього не впливатиме ефект \"Під захистом Світла\".",
        [1220196] = "Збільшує ймовірність спрацювання \"Присуду світла\" та \"Присуду мудрості\" для ваших союзників до $s1%.",
        [1220198] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1220202] = "Збільшує ймовірність критичного ефекту \"Священного шоку\" на $s1%.",
        [1220204] = "Збільшує шкоду вашого \"Освячення\" на $s1%.",
        [1220206] = "Якщо на вас не діє \"Маяк світла\", ви зцілюєте ціль вашого \"Маяка світла\" на $s1% від вашої шкоди, завданої закляттями \"Освячення\", \"Екзорцизм\", \"Священний шок\", \"Священний гнів\" та \"Молот гніву\".",
        [1220208] = "Зменшує час відновлення \"Божественного світла\" на $s1%.",
        [1220210] = "Коли \"Маяк Світла\" зцілює ціль, він також зцілює найближчу дружню поранену ціль на $s1% свого ефекту.",
        [1220212] = "\"Присуд світла\" та \"Присуд мудрості\" також накладають ефект \"Присуду лицаря\".",
        [1220214] = "Ваші печатки наказу, праведності та мучеництва, а також \"Сонячне сяйво\" завдають на $s2% менше шкоди, але продовжують діяти протягом $s1 с після накладання іншої печатки або до накладання третьої. \"Присуд\" тепер може викликати спрацювання кількох печаток.",
        [1220216] = "Ваші \"Присуди\" завдають на $s1% більше шкоди та не поглинають ефекти печаток з цілі. Також \"Присуди\" тепер можуть викликати спрацювання кількох печаток.",
        [1220218] = "Зменшує час відновлення \"Присудів\" на ${$m1/-1000} с, але зменшує їхню шкоду на $s2%.",
        [1220222] = "Збільшує шкоду \"Удару лицаря\" на $s1%.",
        [1220226] = "Збільшує шкоду \"Священного шоку\" на $s1%.",
        [1220228] = "Зменшує час відновлення \"Екзорцизму\" на ${$m1/-1000} с та збільшує його шкоду на $s2%.",
        [1220230] = "Поки ви тримаєте одноручну зброю, \"Удар лицаря\" вивільняє ефекти ваших печаток на цілі, але не поглинає їх.",
        [1220234] = "Парирування та ухилення також викликають спрацювання ефекту руни \"Майстерність володіння щитом\".",
        [1220236] = "Ваш \"Тотем кам'яної шкіри\" також зменшує отриману фізичну шкоду на $s1%, а ваш \"Тотем стіни вітру\" також зменшує отриману магічну шкоду на $s1%",
        [1220242] = "Щоразу, коли ви блокуєте атаку, ви з ймовірністю $h% отримаєте ефект \"Зброї Водоверті\".",
        [1220248] = "Радіус дії тотемів, що діють на союзників, збільшується до ${$m1+20} м.",
        [1220250] = "Після вимови \"Хвилі зцілення\", \"Малої хвилі зцілення\" та \"Бистрини\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1220252] = "Ваша \"Хвиля зцілення\" також перестрибує на цілі неподалік, з кожним стрибком зцілюючи на $s2% менше. Максимум до ${$m1-1} стрибків.",
        [1220254] = "Ваші неперіодичні критичні ефекти шкоди та зцілення з ймовірністю $h% активують ефект \"Водяного щита\", але не поглинають його та не починають його відновлення.",
        [1220256] = "\"Ланцюгова блискавка\" також зцілює останню ціль вашого \"Щита землі\" на $s1% від завданої шкоди.",
        [1220258] = "Збільшує ефективність \"Ланцюгового зцілення\" та шкоду \"Ланцюгової блискавки\" на $s1%.",
        [1220260] = "Ваша \"Бистрина\" також збільшує ефективність \"Ланцюгового зцілення\" на $s1%.",
        [1220264] = "Збільшує шанс завдання критичного удару всіма заклинаннями та атаками на $s1%.",
        [1220266] = "Талант \"Шквал\" збільшує вашу швидкість атаки ще на $s1%.",
        [1220268] = "Шанс спрацювання \"Електростатики\" збільшується на $m1% (на ${$m1/2}% якщо тримаєте по зброї в кожній руці).",
        [1220270] = "Збільшує шкоду зброї в правій руці для \"Штормового удару\" на $s1%.",
        [1220272] = "Поки ви мажєте активну руну \"Електростатика\", ваш \"Блискавковий щит\" отримує заряд щоразу, коли ви вражаєте ціль \"Блискавкою\" чи \"Ланцюговою блискавкою\", накопичуючи до ${$432134m1+3} зарядів, а його шкода може бути критичною.",
        [1220274] = "Збільшує шкоду \"Штормового удару\" та \"Удару лавою\" на $s1%. Збільшує шкоду на $s2% при використанні дворучної зброї.",
        [1220282] = "Критичні удари ваших заклять з ймовірністю $h% спричинять ефект таланту \"Стихійна зосередженість\".",
        [1220284] = "Ефект \"Вірний бета\" вашої здібності \"Дух альфа-вовка\" тепер збільшує шкоду від вогню, криги та природи на $s1%.",
        [1220286] = "Поки діє ефект \"Ясномови\" ви завдаєте на $s2% більше нефізичної шкоди.",
        [1220288] = "З ймовірністю $s1% ви уникнете затримки вимови заклять \"Блискавка\", \"Ланцюгова блискавка\" та \"Виверження лави\" при отриманні шкоди, а шанс спрацювання таланту \"Стихійна зосередженість\" збільшується на $s2%.",
        [1220291] = "Збільшує додаткову шкоду від критичних ударів заклять вогню, криги та природи на $s1%.",
        [1220293] = "Шкода \"Виверження лави\" збільшується на відсоток ймовірності критичного удару.",
        [1220295] = "Збільшує шанс блокувати атаки щитом на $s1%.",
        [1220297] = "Збільшує ймовірність спрацювання руни \"Сплеск сили\" на $s1%.",
        [1220299] = "Ви можете вимовляти \"Переродження\" та \"Осяяння\" перебуваючи у подобі ведмедя та жахливого ведмедя.",
        [1220301] = "\"Несамовитість\" має на ${$m1/-1000} секунд зменшений час відновлення і більше не зменшує вашу броню.",
        [1220303] = "У подобах ведмедя та жахливого ведмедя ви спричиняєте на $s1% більше загрози, а \"Зіщулювання\" тепер прибирає всю вашу загрозу цілі але має на ${$m2/1000} с більший час відновлення.",
        [1220307] = "Здібності \"Нівечення (ведмідь)\", \"Розмах (ведмідь)\", \"Терзання\" та \"Розірвати\" мають на $s1% більшу ймовірність завдання критичного удару цілям під ефектом здібності \"Розірвати\".",
        [1220310] = "Ваш \"Розмах\" тепер поширює ефект вашої здібності \"Розірвати\" з вашої цілі на інші уражені цілі.",
        [1220316] = "Коли ви застосовуєте \"Осяяння\" на іншого гравця, воно також застосовується на вас.",
        [1220318] = "Після вимови \"Цілющого дотику\" або \"Підживлення\" ви з ймовірністю $h% відновите ману в обсязі $s1% від базової вартості закляття.",
        [1220320] = "Зменшує час відновлення \"Спокою\" на $s1% та збільшує його зцілення на $s2%.",
        [1220328] = "Зменшує час відновлення заклять \"Переродження\" та \"Осяяння\" на $s1%.",
        [1220330] = "Критичні ефекти \"Цілющого дотику\", \"Розростання\" та \"Підживлення\" миттєво відновлюють цілі ще $s1% від первинного ефекту зцілення.",
        [1220334] = "Періодична шкода здібностей \"Роздирання\" та \"Розірвання\" тепер може бути критичною.",
        [1220338] = "Збільшує тривалість ефекту \"Роздирання\" на ${$m2/1000} с та збільшує його періодичну шкоду на $m1%.",
        [1220342] = "Здібності \"Шматування\", \"Безжалісний укус\" та \"Нівечення (кіт)\" завдають на $s1% більше шкоди за кожен ваш ефект кровотечі, максимум до $s2%.",
        [1220344] = "\"Шматування\" більше не має вимоги до позиціонування, але завдає на $s1% більше шкоди, якщо ви знаходитесь за спиною цілі.",
        [1220348] = "Шкоду \"Шипів\" збільшено на $s1%, а тривалість збільшено на $s2%.",
        [1220350] = "Збільшує ймовірність завдання удару закляттями та атаками на $s1%.",
        [1220352] = "Зменшує час відновлення \"Зорепаду\" на $s1%.",
        [1220355] = "Збільшує шкоду та радіус шкоди зірок \"Зорепаду\" та \"Урагану\" на $s1%.",
        [1220360] = "Талант \"Природна благодать\" отримує 1 додатковий заряд при спрацюванні.",
        [1220362] = "Збільшує додаткову шкоду від критичних ударів заклять \"Зоряний вогонь\", \"Зоряний сплеск\" та \"Гнів\" на $s1%.",
        [1220366] = "Збільшує ймовірність завдання критичного удару \"Гнівом\" на $s1%.",
        [1220368] = "Ймовірність ухилення та парирування ваших атак ближнього бою зменшено на $s1%.",
        [1220408] = "Завдає ворогові $s1 шкоди від вогню.",
        [1220418] = "+$s1 до сили атаки лише у формі кота, ведмедя та лютого ведмедя.",
        [1220422] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220423] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220424] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220425] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220426] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220428] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220429] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220430] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220432] = "Збільшує вашу шкоду проти нежиті на $s1%.",
        [1220515] = "Жбурляє стріли темної магії, завдаючи ворогам поблизу шкоди від тіні.",
        [1220517] = "Огортає заклинача кістяною бронею, що поглинає $s1 шкоди протягом $d. Поки броня тримається, фізичні атаки не переривають застосування заклять.",
        [1220519] = "Викликає $s1 $lSkeletal Servant:Skeletal Servants; супроводжувати заклинача, доки їх не буде відпущено.",
        [1220529] = "Викликає $s1 $lCrypt Scarab:Crypt Scarabs; на допомогу заклиначеві в бою на $d.",
