        [1235538] = "Здійснює ривок до ворога, завдаючи звичайної шкоди плюс $s3 та приголомшуючи супротивника на $d.",
        [1235681] = "Збільшує шкоду \"Безжалісного укусу\" на $s1%.",
        [1235793] = "Зменшує шкоду від падіння.",
        [1236125] = "Завдає ворогу $s1 шкоди кожні $t1 с протягом $d.",
        [1236151] = "Зцілює ціль на $o1 протягом $d.",
        [1236153] = "Зцілює дружню ціль на $s1.",
        [1236154] = "Прикликає силу душі члена групи, щоб захистити його щитом, який поглинає $s1 шкоди.  Триває $d.  Поки щит тримається, отримана шкода не перериває застосування заклинань.  Після накладання щита ціль не можна захистити ним знову протягом $6788d.",
        [1236156] = "Розвіює магію на цілі, знімаючи $s1 шкідливі $lspell:заклинання:заклинання; із союзника або $s1 корисні $lspell:заклинання:заклинання; з ворога.",
        [1236172] = "Завдає ворогові шкоди від вогню.",
        [1236173] = "Завдає ворогові шкоди від вогню, а потім додаткової шкоди кожні $t2 с. протягом $d.",
        [1236174] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [1236175] = "Телепортує заклинача на 20 ярдів уперед, якщо ніщо не заважає. Також звільняє заклинача від усіх пут.",
        [1236176] = "Роззброює ворога на $d.",
        [1236177] = "Калічить ворога, завдаючи $s1 шкоди та зменшуючи його швидкість руху на $s2% протягом $d.",
        [1236179] = "Завдає ворогові $s2 шкоди й приголомшує його на $d.",
        [1236181] = "Закликає святу магію, щоб зцілити союзника.",
        [1236182] = "Завдає ворогові $s1 шкоди й збільшує отримувану ним шкоду від святості на $s2 за кожен Удар хрестоносця. Накопичується до 5 разів. Триває $d.",
        [1236183] = "Завдає ворогові та його найближчим союзникам шкоди зброєю плюс $s1, уражаючи до $x1 цілей.",
        [1236188] = "Прицільний постріл, що збільшує шкоду дальнього бою на $s1.",
        [1236190] = "Випускає град снарядів у ворога та його союзників поблизу, вражаючи до $x1 цілей звичайною шкодою плюс $s1.",
        [1236191] = "Ошелешує ворога, зменшуючи швидкість його руху на $s1% протягом $d.",
        [1236220] = "Збільшує час між атаками ворогів поблизу на $s1%, сповільнює їхній рух на $s2% та швидкість вимовляння заклять на $s3% на $d.",
        [1236266] = "Створює $s1 Вибухову вівцю, яка $lcharges:charge; до найближчого $lenemy:enemies; і $lexplodes:explode;. Вибухові вівці нестабільні й самознищаться через $d.",
        [1236269] = "Завдає $s1 шкоди від вогню всім ворогам у вибраній зоні.",
        [1236270] = "Завдає всім цілям у конусі перед інженером, що використовує зброю, $13184s1 шкоди від вогню протягом $d. Хіба що вона вибухне.....",
        [1236290] = "Перетворює ворога на вівцю, змушуючи його блукати до $d. Під час блукання вівця не може атакувати чи застосовувати закляття, але дуже швидко відновлюється. Будь-яка шкода поверне цілі звичайну форму. Одночасно можна перетворити лише одну ціль. Діє лише на звірів, драконів, велетнів, гуманоїдів і створінь.",
        [1236291] = "Завдає ворогові шкоди від вогню, а потім додаткової шкоди кожні $t2 с. протягом $d.",
        [1236307] = "Зцілює союзника кожні $t1 с. протягом $d.",
        [1236308] = "На дружній цілі виростають шипи, які завдають нападникам $s1 шкоди від сил природи, коли ті влучають у ціль.  Триває $d.",
        [1236879] = "Збільшує дух учасників групи поблизу на $M1.",
        [1237064] = "Назавжди встановлює приціл на лук або рушницю, збільшуючи ймовірність влучання на 3%.",
        [1237312] = "Запускає у ворога крижановогняну стрілу, завдаючи $s2 шкоди від крижаного вогню, сповільнюючи рух на $s1% і завдаючи додатково $o3 шкоди від крижаного вогню протягом $d. Закляття перевіряється проти меншого з опорів цілі кризі та вогню й вважається одночасно шкодою від криги та вогню.",
        [1237313] = "Запускає у ворога крижановогняну стрілу, завдаючи $s2 шкоди від крижаного вогню, сповільнюючи рух на $s1% і завдаючи додатково $o3 шкоди від крижаного вогню протягом $d. Закляття перевіряється проти меншого з опорів цілі кризі та вогню й вважається одночасно шкодою від криги та вогню.",
        [1237938] = "Плює отрутою у ворога, завдаючи шкоди від сил природи, а потім додаткової шкоди кожні $t2 с протягом $d.",
        [1238069] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1.",
        [1238070] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1.",
        [1238073] = "Кусає ціль, завдаючи $s2% звичайної шкоди плюс $s1.",
        [1238096] = "Дає шанс приголомшити ворога під час атаки. Триває $d.",
        [1238214] = "Зцілює ціль і її групу на $o1 протягом $d. Учасники групи мають бути в межах $a1 ярдів від цілі. На початку Дике зростання зцілює швидше, а ближче до завершення дії — повільніше.",
        [1238215] = "Зцілює ціль і її групу на $o1 протягом $d. Учасники групи мають бути в межах $a1 ярдів від цілі. На початку Дике зростання зцілює швидше, а ближче до завершення дії — повільніше.",
        [1238299] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $s2% більше шкоди.",
        [1238300] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $s2% більше шкоди.",
        [1238319] = "Завдає $s1 шкоди від тіні кожні $t1 с.",
        [1238373] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $408490s2% більше шкоди.",
        [1238376] = "Жбурляє в ціль розплавлену лаву, завдаючи $s1 шкоди від вогню. Якщо на цілі діє ваш Вогняний шок, Викид лави завдає на $408490s2% більше шкоди.",
        [1238787] = "Розподіляє шкоду порівну між усіма ураженими цілями.",
        [1239242] = "Зцілює дружню ціль на $s1, додатково на $o2 протягом $d і збільшує ефективність Ланцюгового зцілення, застосованого безпосередньо до цієї цілі, на $s3%.",
        [1239243] = "Зцілює дружню ціль на $s1, додатково на $o2 протягом $d і збільшує ефективність Ланцюгового зцілення, застосованого безпосередньо до цієї цілі, на $s3%.",
        [1239482] = "Карає ворога, завдаючи шкоди від святості.",
        [1239696] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239697] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239699] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1239700] = "Вражає ціль енергією, завдаючи $s1 шкоди від таємної магії. Щоразу, коли ви застосовуєте «Таємний вибух», шкода всіх інших ваших заклять збільшується на $400573s1%, а витрати мани на «Таємний вибух» — на $400573s2%. Ефект сумується до $400573u разів і триває $400573d або доки не буде застосовано інше закляття шкоди.",
        [1240044] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240045] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240046] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240047] = "Завдає ворожій цілі $s1 шкоди від криги. Завдає на $s2% більше шкоди замороженим цілям.",
        [1240193] = "Завдає супротивнику удару, спричиняючи шкоду від зброї плюс $s1.",
        [1240345] = "Дозволяє шахтарю переплавити шматок мідної руди на мідний злиток.  Потребує горна.",
        [1240682] = "Жбурляє у ворога магічну стрілу, завдаючи шкоди від таємної магії.",
        [1240687] = "Завдає звичайної шкоди та додатково $s1 усім ворогам поблизу.",
        [1240732] = "Зцілення кожні $t2 с протягом $d.",
        [1240733] = "Зцілення кожні $t2 с протягом $d.",
        [1240734] = "Завдає шкоди від святості кожні $t2 с.",
        [1240736] = "Завдає шкоди від святості кожні $t2 с.",
        [1240770] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240771] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240772] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240773] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240774] = "Зцілює дружню ціль і заклинача на $s1. Низька загроза.",
        [1240826] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [1240827] = "Накладає на ціль закляття, яке зцілює її на ${($m1+($bh*$bc))*$<mult>} наступного разу, коли вона отримає шкоду або неперіодичне зцілення. Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $401880a1 ярдів. Перескакує до $s2 разів і триває $401877d після кожного переходу. Одночасно один заклинач може накласти це закляття лише на одну ціль.",
        [1240848] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [1240849] = "Накладає на ціль закляття, яке зцілює її наступного разу, коли вона отримає шкоду або зцілення.  Коли зцілення спрацьовує, Молитва відновлення перескакує на учасника групи або рейду в межах $a1 ярдів.  Перескакує до $n разів і триває $d після кожного переходу.  Одночасно це закляття може бути накладене лише на одну ціль.",
        [1240927] = "Дозволяє створювати й використовувати бинти до можливої навички 75.   Тканину для бинтів можна знайти на гуманоїдах у світі.",
        [1240928] = "Дозволяє створювати й використовувати бинти до можливої навички 150.   Тканину для бинтів можна знайти на гуманоїдах у світі.",
        [1240929] = "Дає лікарю змогу виготовляти й використовувати бинти до максимальної навички 225. Тканину для бинтів можна знайти на гуманоїдах у світі.",
        [1240930] = "Дозволяє лікарю виготовляти й використовувати бинти, розвиваючи навичку до 300.   Тканину для цих бинтів можна знайти на гуманоїдах у світі.",
        [1240943] = "Дозволяє алхіміку варити базові зілля до максимальної навички 75.  Потребує трав, зібраних за допомогою травництва.",
        [1240944] = "Дозволяє ковалю виготовляти базову зброю та обладунки до максимальної навички 75.  Потребує каменю й металу, добутих за допомогою гірництва.",
        [1240945] = "Дозволяє кухарю готувати базові страви до максимальної навички 75.  Потребує м’яса звірів і вогню для приготування їжі.",
        [1240946] = "Дає зачаровувачу змогу зачаровувати базові предмети до максимальної навички 75. Потребує пилу й есенцій, отриманих розпиленням магічних предметів.",
        [1240947] = "Дозволяє інженеру виготовляти базові пристрої до максимальної навички 75.  Потребує каменю й металу, добутих за допомогою гірництва.",
        [1240948] = "Спорядіть вудку й знайдіть водойму для риболовлі. Клацніть правою кнопкою миші на поплавці, коли він сіпнеться, щоб упіймати рибу. Вища навичка збільшує шанс успішної риболовлі у високорівневих місцевостях.\r\n",
        [1240949] = "Основи збирання трав із кущів та інших рослин для алхімії.  Дає можливість підвищити навичку травництва до 75.",
        [1240950] = "Дозволяє шкірнику виготовляти шкіряні обладунки до максимальної навички 75.  Потребує клаптів шкіри та шкур, здобутих за допомогою зняття шкур.",
        [1240951] = "Навчає видобувати руду й камінь із жил для інженерії та ковальства.  Дає можливість підвищити навичку гірництва до 75.  Потребує кирки.",
        [1240952] = "Основи зняття шкур і хутра з тварин для шкіряництва. Максимальна навичка зняття шкур — 75. Потрібен ніж для зняття шкур.",
        [1240953] = "Дозволяє кравцю виготовляти базові тканинні обладунки до максимальної навички 75.  Потребує тканини, яку можна знайти на гуманоїдах.",
        [1240954] = "Дозволяє алхіміку варити звичайні зілля до максимальної навички 150.",
        [1240955] = "Дозволяє ковалю виготовляти добротну зброю та обладунки до максимальної навички 150.",
        [1240956] = "Дозволяє кухарю готувати смачні страви до максимальної навички 150.",
        [1240957] = "Дає зачаровувачу змогу зачаровувати зброю та обладунки до максимальної навички 150.",
        [1240958] = "Дозволяє інженеру виготовляти потужніші пристрої та вибухівку до максимальної навички 150.",
        [1240959] = "Спорядіть вудку й знайдіть водойму для риболовлі. Клацніть правою кнопкою миші на поплавці, коли він сіпнеться, щоб упіймати рибу. Вища навичка збільшує шанс успішної риболовлі у високорівневих місцевостях.",
        [1240960] = "Навчає знаходити та збирати складніші трави.   Дає можливість підвищити навичку травництва до 150.",
        [1240961] = "Дозволяє шкірнику виготовляти добротні шкіряні обладунки до максимальної навички 150.",
        [1240962] = "Просунутий рівень гірництва.  Дає можливість підвищити навичку гірництва до 150.",
        [1240963] = "Поглиблені навички зняття шкур зі звірів для шкіряництва. Максимальна навичка зняття шкур — 150. Потрібен ніж для зняття шкур.",
        [1240964] = "Дозволяє кравцю виготовляти модні тканинні сорочки й обладунки до максимальної навички 150.",
        [1240965] = "Дозволяє алхіміку варити дивовижні зілля до максимальної навички 225.",
        [1240966] = "Дозволяє ковалю виготовляти майстерну зброю та обладунки до максимальної навички 225.",
        [1240967] = "Дозволяє кухарю готувати вишукані страви до максимальної навички 225.",
        [1240968] = "Дає зачаровувачу змогу накладати майстерні чари на зброю та обладунки до максимальної навички 225.",
        [1240969] = "Дозволяє інженеру виготовляти дивовижні бомби й механізми до максимальної навички 225.",
        [1240970] = "Спорядіть вудку й знайдіть водойму для риболовлі. Клацніть правою кнопкою миші на поплавці, коли він сіпнеться, щоб упіймати рибу. Вища навичка збільшує шанс успішної риболовлі у високорівневих місцевостях.",
        [1240971] = "Навчає знаходити та збирати складніші трави.   Дає можливість підвищити навичку травництва до 225.",
